(window.GIM_TS=window.GIM_TS||{})["Temurah.0"]={"from":0,"a":[["\u0003הכל ממירין\u0004 (יכולים לעשות תמורה), \u0003אחד\u0004 (בין) \u0003אנשים ואחד\u0004 (ובין) \u0003נשים.\u0004 ומעתה, אם המירו (שאמרו על בהמת חולין שלהם שתהא תמורת, או תחת, בהמת קדשים זו) — התקדשה בכך בהמת החולין, ואילו בהמת הקדשים עומדת בקדושתה. ומסייגים את הדברים: \u0003לא\u0004 (אין כוונת הדברים) \u0003שאדם רשאי להמיר, אלא\u0004 ללמדנו \u0003שאם\u0004 עבר ו\u0003המיר\u0004 — מה שהוא חולין \u0003מומר,\u0004 ונעשה הוא קדוש, \u0003ו\u0004אילו הממיר \u0003סופג\u0004 (לוקה) על כך \u0003את הארבעים\u0004 מלקות, מן התורה, לפי שעבר על מצוות לא תעשה.","שנינו במשנתנו: \"הכל ממירין... לא שאדם רשאי להמיר...\" ושואלים: \u0003הא גופא קשיא\u0004 \u0005[זו\u0006 המשנה \u0005עצמה קשה]\u0006 שכן בתחילה \u0003אמרת: \"הכל ממירין\"\u0004 — ולשון זו מורה שרשאי אדם להמיר מ\u0003לכתחילה,\u0004 \u0003והדר תני\u0004 \u0005[וחזר,\u0006 והמשיך התנא ו\u0005שנה]:\u0006 \u0003\"לא שאדם רשאי להמיר אלא שאם המיר מומר\"\u0004 — משמע שאין מעשה התמורה אלא ב\u0003דיעבד\u0004 (שכבר נעשה), אבל אינו מותר לכתחילה. ונמצאת איפוא סתירה בין חלקי המשנה!","ודוחים: \u0003ותיסברא\u0004 \u0005[וכי סבור אתה]\u0006 שמשמעות הלשון \u0003\"הכל ממירין\"\u0004 שאף \u0003לכתחילה\u0004 מותר לעשות כן? אם כך, \u0003אדקשיא\u0004 \u0005[עד שקשה]\u0006 \u0003לך\u0004 על כך \u0003ממתניתין\u0004 \u0005[מ\u0006המשך לשון \u0005משנתנו],\u0006 \u0003תיקשי\u0004 \u0005[יוקשה]\u0006 \u0003לך\u0004 מ\u0003קרא\u0004 \u0005[המקרא]\u0006 עצמו, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 בדין התמורה: \u0003\"לא יחליפנו ולא ימיר אתו\u0004 טוב ברע או רע בטוב\" (ויקרא כז, י), הרי שאסור הדבר מן התורה!","\u0003אלא אמר רב יהודה: הכי קתני\u0004 \u0005[כך היא,\u0006 המשנה, \u0005נשנית,\u0006 זו היא כוונתה\u0005]\u0006 — \u0003הכל מתפיסין\u0004 (יכולים להתפיס קדושת בהמת קדשים על בהמת חולין) \u0003ב\u0004אמצעות מעשה ה\u0003תמורה, אחד אנשים ואחד נשים. לא\u0004 (אין כוונת הדברים) \u0003שאדם רשאי להמיר\u0004 לכתחילה, אלא \u0003שאם המיר\u0004 — \u0003מומר, וסופג\u0004 (ולוקה) \u0003את הארבעים\u0004 מלקות.","שנינו במשנתנו: \u0003\"הכל\u0004 ממירין, אחד אנשים ואחד נשים\", ומבררים: לשון כוללת זו (\"הכל\") \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 היא באה, שאף הוא בכלל הממירים? ומסבירים: \u0003לאיתויי\u0004 \u0005[לרבות]\u0006 את ה\u0003יורש\u0004 שירש מאביו קרבן שהפרישו האב ולא הספיק להקריבו לפני מותו, שאם המיר היורש בהמת חולין בבהמת קרבן זו, חלים עליה דיני תמורה. \u0003ו\u0004מעירים: שיטת משנתנו זו היא ש\u0003לא כ\u0004שיטת \u0003ר' יהודה.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 ה\u0003יורש סומך\u0004 על קרבן מורישו, וכן ה\u0003יורש ממיר\u0004 בהמת חולין בקרבן מורישו אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר:\u0004 ה\u0003יורש אינו סומך, ו\u0004ה\u0003יורש אינו ממיר.\u0004 ודנים בשיטות הללו.","\u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לשיטתו זו של \u0003ר' יהודה?\u0004 — \u0003יליף\u0004 \u0005[לומד]\u0006 דין הנוגע ל\u0003תחילת הקדש\u0004 (כלומר, לענין תמורה, שהיא תחילת הקדש הקרבן) \u0003מ\u0004דין הנוגע ל\u0003סוף הקדש\u0004 (לענין סמיכה על הקרבן, לפני שחיטתו). והוא למד: \u0003מה\u0004 (כשם) ב\u0003סוף הקדש\u0004 — ה\u0003יורש אינו סומך, אף תחילת הקדש\u0004 — ה\u0003יורש אינו ממיר.\u0004","ושואלים: \u0003וסמיכה גופה מנלן\u0004 \u0005[עצמה, מנין לנו]\u0006 שאין היורש סומך? ומשיבים: שכן בפרשת השלמים (ויקרא ג) \u0003תלת\u0004 \u0005[שלוש]\u0006 פעמים המלה \u0003\"קרבנו\" כתיבי\u0004 \u0005[נאמרו].\u0006 וכל אחד מהם בא ללמד: \u0003חד\u0004 \u0005[\u0006דבר \u0005אחד]\u0006 — שרק על \u0003קרבנו\u0004 של ישראל בעליו סומך, \u0003ולא\u0004 על \u0003קרבן\u0004 של \u0003גוי\u0004 אף שהוא קרב במקדש, ואולם אין סומכים עליו. \u0003וחד\u0004 \u0005[ואחד]\u0006 — רק על \u0003קרבנו\u0004 שלו הוא סומך, \u0003ולא\u0004 על \u0003קרבן חבירו. וחד\u0004 \u0005[ואחד]\u0006 — רק על \u0003קרבנו\u0004 שלו הוא סומך, \u0003ולא\u0004 על \u0003קרבן\u0004 שירש מ\u0003אביו.\u0004","\u0003ולר' מאיר\u0004 ש\u0003אמר\u0004 ש\u0003יורש סומך\u0004 על קרבן אביו, יש לשאול: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"קרבנו\",\u0004 שלמדנו ממנו למעט את היורש מסמיכה! ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 \"קרבנו\" \u0005נצרך לו\u0006 ללימוד אחר\u0005]:\u0006 \u0003לרבות כל בעלי חוברין\u0004 (כמה אנשים המשתתפים בקרבן אחד) \u0003ל\u0004דין ה\u0003סמיכה,\u0004 שקרבן זה נחשב כ\"קרבנו\" של כל אחד מהם, וכולם סומכים עליו.","ושואלים: \u0003ור' יהודה\u0004 שלמד מ\"קרבנו\" זה למעט את היורש מסמיכה, מנין לו שאף בעלי חוברים סומכים? ומשיבים: ר' יהודה, \u0003בעלי חוברין לסמיכה לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור כן\u0005],\u0006 שלשיטתו אינם סומכים. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — משום \u0003דהא לא מיחד\u0004 \u0005[שהרי אינו מיוחד]\u0006 ה\u0003קרבן דידהו\u0004 \u0005[שלהם]\u0006 לאדם מסויים, אלא משותף לכולם. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר בשיטת ר' יהודה: \u0003לעולם\u0004 אכן \u0003אית ליה\u0004 \u0005[יש לו],\u0006 אף הוא סבור שבעלי חוברים סומכים, \u0003ו\u0004אולם דינים אלו שאין הסמיכה נוהגת ב\u0003קרבן גוי ו\u0004כן שאינה נוהגת ב\u0003קרבן חבירו\u0004 — לא משני מקראות נפרדים הם נלמדים, אלא שניהם \u0003מחד קרא נפקא\u0004 \u0005[ממקרא אחד יוצא,\u0006 נלמד\u0005],\u0006 ולפיכך, \u0003אייתר ליה חד\u0004 \u0005[נותר לו\u0006 \"קרבנו\" \u0005אחד]\u0006 \u0003ל\u0004למדנו לרבות אף \u0003בעלי חוברין לסמיכה.\u0004","\u0003ו\u0004מבררים עתה את שיטת ר' מאיר ש\u0003אמר יורש ממיר, מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 לשיטתו? \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 ר' מאיר: כפל לשון 'המרה' שנאמר בכתוב \u0003\"אם המר ימיר\u0004 בהמה בבהמה והיה הוא ותמורתו יהיה קודש\" (ויקרא כז, י), בא \u0003לרבות\u0004 את \u0003היורש,\u0004 שאף הוא בכלל דין הממירים."],["\u0003ויליף\u0004 \u0005[ולמד]\u0006 דין הנוגע ל\u0003סוף הקדש\u0004 (סמיכה) \u0003מ\u0004דין הנוגע ל\u0003תחילת הקדש\u0004 (תמורה), ובאופן זה: \u0003מה\u0004 (כשם) שב\u0003תחילת הקדש\u0004 — ה\u0003יורש מימר\u0004 (ממיר), \u0003אף\u0004 ב\u0003סוף הקדש\u0004 — ה\u0003יורש סומך.\u0004","ושואלים: ולשיטת \u0003ר' יהודה\u0004 שיורש אינו ממיר, \u0003האי\u0004 \u0005[\u0006כפל הלשון שבפסוק \u0005זה]\u0006 \u0003\"ואם המר ימיר\"\u0004 (ויקרא כז, י), \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו,\u0006 דורש ממנו\u0005]?\u0006 ומשיבים: כפל לשון זה בא \u0003לרבות את האשה\u0004 לענין תמורה, שאם המירה אשה — חלה התמורה, והריהי לוקה על כך, כאיש. \u0003וכדתניא\u0004 \u0005[וכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003לפי שכל הענין כולו\u0004 (פרשת התמורה האמורה בתורה, ויקרא כז, י) \u0003אינו מדבר אלא\u0004 ב\u0003לשון זכר, ש\u0004כן \u0003נאמר: \"לא יחליפנו ולא ימיר אתו\",\u0004 ויש לשאול: \u0003אשה מנין\u0004 לנו שאף היא בכלל דין התמורה? לכך \u0003תלמוד לומר\u0004 (משמיענו) המשך הפסוק: \u0003\"ואם המר ימיר\"\u0004 — \u0003לרבות\u0004 \u0003את האשה.\u0004","ושואלים: \u0003ול\u0004שיטת \u0003ר' מאיר\u0004 שדרש מכתוב זה שהיורש ממיר — \u0003אשה\u0004 שאף היא בכלל דין התמורה \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מ\u0004האמור בפסוק זה \u0003\"ואם\u0004 המר ימיר\", ובאה תוספת הוא\"ו שבמלה \"ואם\" לרבות דין האשה בתמורה. ושואלים: \u0003ור' יהודה\u0004 מדוע אין הוא לומד את דין האשה בתמורה מ\"ואם\"? ומשיבים: מתוספת זו, \u0003\"ואם\"\u0004 \u0003לא דריש\u0004 \u0005[אינו דורש],\u0006 שלדעתו אין ללמוד מכך.","ושואלים: \u0003ובין\u0004 לשיטת \u0003ר' מאיר\u0004 הלמד מהכתוב \"ואם\" שהאשה בכלל דין התמורה, \u0003ובין ר' יהודה\u0004 הלמד דין זה מהכתוב \"ואם המר ימיר\", מובן כי \u0003טעמא\u0004 \u0005[טעם]\u0006 הדבר שהאשה היא בכלל דין התמורה הוא רק משום \u0003דרבי קרא\u0004 \u0005[שריבה הכתוב]\u0006 \u0003לאשה,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי\u0006 מכאן\u0005]\u0006 שאם \u0003לא רבייה קרא\u0004 \u0005[מרבה הכתוב אותה],\u0006 כי אז \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כי עבדא\u0004 \u0005[כאשר\u0006 אשה \u0005עשתה]\u0006 \u0003תמורה\u0004 — \u0003לא לקיא\u0004 \u0005[אינה לוקה]\u0006 על כך. ויש להקשות, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב יהודה, אמר רב, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 בכתוב \u0003\"איש או אשה כי יעשו מכל חטאת האדם\u0004 למעול מעל בה' ואשמה הנפש ההיא\" (במדבר ה, ו) \u0003השוה הכתוב אשה לאיש לכל עונשין שבתורה\u0004 ובכלל זה גם עונש מלקות לממירה!","ומשיבים: אף שהושוותה האשה לאיש לכל עונשים בתורה, מכל מקום \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הכתוב ללמדנו שאשה לוקה על התמורה, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה,\u0006 שאשה נענשת כאיש\u0005]\u0006 אמורים דווקא ב\u0003עונש\u0004 ה\u0003שוה בין ביחיד\u0004 \u0003בין בצבור,\u0004 \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בתמורה\u0005]\u0006 \u0003כיון\u0004 ש\u0003עונש שאינה שוה בכל הוא,\u0004 שאין דין תמורה נוהג בציבור, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה בסוף פרקנו\u0005]:\u0006 \u0003אין הצבור והשותפין עושין\u0004 בבהמותיהם של חולין \u0003תמורה\u0004 לבהמת הקדש, וכן אין ממירים בהמת הקדש של ציבור ושל שותפים על בהמת חולין, ואם כן \u0003אשה נמי\u0004 \u0005[גם כן]\u0006 \u0003כי עבדא\u0004 \u0005[כאשר\u0006 עברה ו\u0005עשתה\u0006 תמורה\u0005]\u0006 — \u0003לא לקיא\u0004 \u0005[אינה לוקה],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שהאשה לוקה על איסור תמורה.","ומתוך שנידון דינה של האשה בתמורה, נידון אף דינו של הקטן בתמורה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: קטן מהו\u0004 דינו לענין זה \u0003שימיר\u0004 (שמעשה תמורה שלו יהיה תקף)? ודנים בשאלה זו: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק המדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בקטן שלא הגיע\u0004 עדיין \u0003לעונת נדרים\u0004 (שהריהו פחות מבן שתים עשרה שנה ויום אחד, ואין נדריו נחשבים) — בכגון זה \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 כלל, \u0003כיון\u0004 ש\u0003אקדושי לא אקדיש\u0004 \u0005[להקדיש\u0006 לקרבן \u0005אין\u0006 קטן זה \u0005מקדיש],\u0006 האם \u0003אמורי\u0004 \u0005[להמיר]\u0006 הוא \u0003ממיר?! אלא כי קמבעיא ליה\u0004 \u0005[כאשר נשאלה לו,\u0006 לרמי בר חמא\u0005]\u0006 שאלה זו, הריהי \u0003בקטן שהגיע לעונת נדרים.\u0004","והסבר השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו],\u0006 כי \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 על הכתוב בפרשת ערכין \u0003\"איש\u0004 כי יפליא נדר בערכך נפשות לה'\" (ויקרא כז, ב): \u0003מה תלמוד לומר\u0004 (מה מלמדתנו) לשון מיוחדת זו \u0003\"כי יפליא נדר\",\u0004 ולא רק \"כי ידור נדר\"? — \u0003לרבות\u0004 את מי שהוא \u0003מופלא הסמוך לאיש\u0004 (קטן מיום שמלאו לו שתים עשרה שנה ויום אחד ועד להיותו בן שלש עשרה שנה ויום אחד שאם נדר, ומצאו שהוא יודע לשם מי נדר — נדרו נדר), \u0003דקדשו\u0004 \u0005[שהקדשו]\u0006 שהקדיש הרי הוא \u0003קדוש.\u0004 ומעתה יש לדון בדבר: האם \u0003מ\u0004כיון שקטן שכזה \u0003אקדושי\u0004 \u0005[להקדיש]\u0006 הוא \u0003מקדיש\u0004 — \u0003אמורי נמי\u0004 \u0005[להמיר גם כן]\u0006 הוא \u0003ממיר. או דלמא\u0004 \u0005[שמא]:\u0006 \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003בר עונשין הוא\u0004 על מעשיו, שהרי עדיין קטן הוא — \u0003בתמורה לא מיתפיס\u0004 \u0005[אין\u0006 הוא \u0005מתפיס, גורם שתיתפס בקדושה אף בבהמת החולין].\u0006","ובעקבות בעיה זו הנוגעת לדין הקטן בתמורה העלה רמי בר חמא בעיה נוספת: \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 בהכרעת הבעיה הקודמת, ש\u0003קטן\u0004 (מופלא הסמוך לאיש) \u0003עביד\u0004 \u0005[עושה]\u0006 \u0003תמורה,\u0004 וטעם הדבר — משום שאף שעתה אינו בן עונשים, מכל מקום שייך הוא בכך, \u0003דהא אתי\u0004 \u0005[שהרי\u0006 הוא \u0005בא],\u0006 לכשיגדל, \u0003לכלל עונשין\u0004 של תורה, ואולם \u0003גוי\u0004 שאינו בא לעולם לכלל עונשים \u0003מהו\u0004 דינו לענין זה \u0003שימיר?\u0004 וצדדי השאלה: \u0003מי אמרת מדאקדושי\u0004 \u0005[האם אומר אתה מ\u0006כיון \u0005שלהקדיש]\u0006 הוא \u0003מקדיש, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"איש איש\u0004 מבית ישראל ומן הגר הגר בישראל אשר יקריב קרבנו לכל נדריהם ולכל נדבותם אשר יקריבו לה' לעולה\" (ויקרא כב, יח), ו\u0003מה תלמוד לומר\u0004 (מלמדנו) כפל לשון זה \u0003\"איש איש\"\u0004 — \u0003לרבות את הגוים, ש\u0004הריהם \u0003נודרים נדרים ונדבות כישראל,\u0004 שהקדשם הקדש. לכן יש מקום לומר ש\u0003אמורי נמי\u0004 \u0005[להמיר גם כן]\u0006 \u0003ממיר\u0004 הגוי. או דלמא \u0005[שמא]:\u0006 \u0003כיון דלא אתי\u0004 \u0005[שאין\u0006 הוא \u0005בא]\u0006 לעולם \u0003לכלל עונשין\u0004 שהרי גוי הוא, משום כך \u0003כי עביד\u0004 \u0005[כאשר\u0006 הוא \u0005עשה]\u0006 \u0003תמורה\u0004 — \u0003לא קדשה\u0004 \u0005[אינה מתקדשת]?!\u0006 \u0003אמר\u0004","\u0003רבא: תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 בברייתא\u0005],\u0006 \u0003קדשי גוים\u0004 — \u0003לא נהנין ולא מועלין\u0004 בהם (שאין נוהג בהם דין מעילה, שאם נהנה מהם אינו מביא קרבן אשם מעילות), ואין חייבין עליהם משום פיגול (אם חשב עליהם הכהן בשעת הקרבתם לאכול את בשרם מחוץ לזמן אכילתם), ואין חייבים על קרבנות הגוי משום \u0003נותר\u0004 (אם אכלום לאחר שעבר זמן אכילת הקרבן) \u0003וטמא\u0004 (אם נטמא). וכן \u0003אין\u0004 הגוים \u0003עושין תמורה, ואין\u0004 הם \u0003מביאין\u0004 \u0003עליהם נסכים\u0004 בפני עצמם, כקרבן לעצמו בפני עצמם. \u0003אבל קרבנו\u0004 של הגוי \u0003טעון\u0004 (חייב בהבאת) \u0003נסכים.\u0004 כל אלה \u0003דברי ר' שמעון.\u0004","\u0003אמר ר' יוסי: בכולן,\u0004 בכל הדינים הללו, \u0003אני רואה\u0004 (דעתי) \u0003להחמיר,\u0004 אף בקדשי הגוים. ובמה ששנינו בדברי ר' שמעון שאין דין מעילה בקדשי גוים, מסבירים: \u0003במה דברים אמורים\u0004 — דווקא \u0003בקדשי מזבח\u0004 בקרבנות המוקדשים להקרב על המזבח, \u0003אבל בקדשי בדק הבית\u0004 (שמקדיש כל דבר בעל ערך לצורך המקדש) — \u0003מועלין בהן.\u0004 עד כאן דברי הברייתא. \u0003קתני מיהא\u0004 \u0005[שנינו על כל פנים]\u0006 בה ש\u0003אין\u0004 הגוים \u0003עושין תמורה!\u0004","ושואלים: \u0003ורמי בר חמא\u0004 ששאל שאלה זו, מה משיב הוא על פתרון זה מהברייתא? ומשיבים: אין מברייתא זו פתרון לשאלה, משום ש\u0003ב\u0004מקרה ש\u0003הקדיש\u0004 ה\u0003גוי\u0004 קרבן כדי \u0003להתכפר\u0004 בו אותו ה\u0003גוי\u0004 — \u0003לא קמיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 כלל, שברור שאין הגוי עושה תמורה. ובמקרה זה עוסקת הברייתא. ואולם \u0003כי קמיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 שאלתי זו — הריהי \u0003בהקדיש גוי ומתכפר בישראל\u0004 (כדי שיתכפר בו ישראל). וצדדי השאלה: האם \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מקדיש\u0004 הגוי \u0003אזלינן\u0004 \u0005[הולכים אנו],\u0006 ואין הוא עושה תמורה. \u0003או בתר\u0004 \u0005[אחר]\u0006 ה\u0003מתכפר\u0004 הישראלי \u0003אזלינן\u0004 \u0005[הולכים אנו],\u0006 ועושה הגוי תמורה?","ומציעים: \u0003תיפשוט ליה\u0004 \u0005[תיפתר לו,\u0006 לרמי בר חמא\u0005]\u0006 הבעיה \u0003מ\u0004תוך דברי \u0003ר' אבהו,\u0004 שכן אמר ר' אבהו, \u0003אמר ר' יוחנן: המקדיש\u0004 בהמה משלו כדי שיתכפר בה חבירו, ונפל בה מום, אם הוא רוצה לפדותה, הריהו \u0003מוסיף\u0004 על מחירה \u0003חומש\u0004 (חמישית), כדין כל בעל חפץ שפודה את מה שהקדיש, אבל מי שעבורו הקדיש בהמה זו אינו מוסיף חומש. \u0003ו\u0004מצד אחר, \u0003מתכפר,\u0004 כלומר, מי שבשבילו נועד הקרבן — הוא \u0003עושה תמורה. ו\u0004עוד: \u0003התורם\u0004 (המפריש תרומה) לכהן \u0003מ\u0004תבואתו \u0003שלו\u0004"],["\u0003על\u0004 תבואתו \u0003של חבירו\u0004 כדי לפוטרו מחובת הפרשה זו — \u0003טובת הנאה,\u0004 כל ההנאות הבאות לו מחמת נתינה זו, הריהן \u0003שלו,\u0004 של נותן התרומה, ולא של בעל התבואה. הרי למדנו איפוא שהמתכפר עושה תמורה, ולא המקדיש, ונמצא פתרון לשאלת רמי בר חמא!","\u0003אמר ליה\u0004 \u0005[לו],\u0006 יכול רמי בר חמא להשיב על כך: אין להביא ראיה מדברי ר' אבהו אלה, שכן \u0003התם\u0004 \u0005[שם]\u0006 כשגם המקדיש וגם המתכפר הם ישראלים, כך \u0003הוא\u0004 הדין, שהמתכפר עושה תמורה ולא המקדיש, משום \u0003דקאתי\u0004 \u0005[שהוא,\u0006 הקרבן \u0005בא]\u0006 \u0003מכח ישראל,\u0004 ו\u0003משום הכי אזלינן בתר\u0004 \u0005[ומשום כך הולכים אנו אחר]\u0006 ה\u0003מתכפר, והוה ליה\u0004 \u0005[ונהיה לו,\u0006 נחשב הדבר\u0005]\u0006 \u0003תחילתו וסופו ביד ישראל.\u0004 ונמצא שכל הזמן היה הקרבן ברשות מי שהוא בכלל דין תמורה. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בבעיה זו, שהמקדיש הוא גוי והמתכפר ישראל, \u0003הכי קא מיבעיא ליה\u0004 \u0005[כך נשאלה לו]\u0006 לרמי בר חמא: \u0003מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 ש\u0003מתחילה ועד סוף דתיקו\u0004 \u0005[שתעמוד]\u0006 בהמת הקרבן \u0003ברשות מאן דעביד\u0004 \u0005[מי שעושה,\u0006 יכול לעשות\u0005]\u0006 \u0003תמורה?\u0004 ומסכמים: לא נפתרה השאלה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ונפנים לברר את דברי הברייתא שהובאה קודם. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בתחילת הברייתא כי \u0003מוקדשי גוים לא נהנין ולא מועלין\u0004 בהם (אין בהם דין מעילה). ומסבירים: יש להבחין בין שתי הלכות אלה, שכן מה ששנינו ש\u0003לא נהנין\u0004 מהם — איסור זה הוא \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003ו\u0004אילו מה ששנינו ש\u0003לא מועלין\u0004 בהם — הלכה זו היא \u0003מדאורייתא\u0004 \u0005[מדין תורה].\u0006","\u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה] להלכה זו שאין בקדשי גוים דין מעילה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 בפרשת המעילה \u0003\"נפש כי תמעל מעל וחטאה בשגגה\u0004 מקדשי ה'\" (ויקרא ה, יד), \u0003וילפינן\u0004 \u0005[ולמדים אנו]\u0006 בגזירה שווה \u0003\"חטא\"\u0004 (במעילה), \u0003\"חטא\" מתרומה\u0004 (שנאמר בה \"ולא ישאו עליו חטא\", ויקרא כב, ט). \u0003ובתרומה כתיב\u0004 \u0005[נאמר]\u0006 \"ואני הנני נתתי לך את משמרת תרומותי לכל קדשי \u0003בני ישראל\"\u0004 (במדבר יח, ח) — והרי זה בא למעט שאין דין התרומה נוהג אלא בבני ישראל \u0003ולא\u0004 ב\u0003גוים.\u0004 ובגזירה שווה נלמד שאף דין המעילה נוהג רק בבני ישראל.","\u0003ו\u0004עוד שנינו בברייתא ש\u0003אין חייבין עליהם,\u0004 על קדשי גוים, \u0003משום פיגול\u0004 ומשום \u0003נותר ו\u0004משום \u0003טמא.\u0004 ומסבירים: טעם הדבר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003בה בטומאה\u0004 של הקדשים: \u0003\"דבר אל אהרן ואל בניו וינזרו מקדשי בני ישראל ולא יחללו את שם\u0004 קדשי אשר הם מקדישים לי\" (ויקרא כב, ב). שבהיותם טמאים, עליהם לפרוש (\"וינזרו\") מן הקדשים.","\u0003ויליף\u0004 \u0005[ולמד]\u0006 החכם \u0003נותר\u0004 בגזירה שווה \u0003\"חילול\"\u0004 (האמור בנותר) ו\u0003\"חילול\" מטומאה, דכתיב גבי\u0004 \u0005[ש\u0006כן \u0005נאמר אצל]\u0006 \u0003טומאה:\u0004 \"וינזרו מקדשי \u0003בני ישראל ולא יחללו\u0004 את שם קדשי אשר הם מקדישים לי\", \u0003וכתיב גבי\u0004 \u0005[ונאמר אצל]\u0006 דין ה\u0003נותר:\u0004 \"ביום זבחכם יאכל וממחרת והנותר עד יום השלישי באש ישרף... \u0003ואכליו עונו ישא כי את קדש ה' חלל\"\u0004 (ויקרא יט, ו—ח). ומעתה, כשם שדין טומאה בקדשים אינו נוהג אלא בקדשי בני ישראל, אף דין נותר אינו נוהג בקדשי גוים.","\u0003ויליף\u0004 \u0005[ולמד]\u0006 את דין ה\u0003פיגול\u0004 בקדשי גוים מגזירה שווה \u0003\"עון\"\u0004 (בפיגול) \u0003\"עון\" מנותר, דכתיב גבי\u0004 \u0005[ש\u0006כן \u0005נאמר אצל]\u0006 דין ה\u0003פיגול:\u0004 \"ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא יירצה המקריב אותו לא יחשב לו פיגול יהיה \u0003והנפש האכלת ממנו עונה תשא\"\u0004 (ויקרא ז, יח), \u0003וכתיב גבי\u0004 \u0005[ונאמר אצל]\u0006 דין ה\u0003נותר: \"ואכליו עונו ישא כי את קדש ה' חלל\".\u0004 וכשם שהנותר, כאמור, אינו נוהג אלא בקדשי בני ישראל, אף דין הפיגול אינו נוהג בקדשי גוים. \u0003וכולהו\u0004 \u0005[כולם,\u0006 פיגול, נותר וטמא\u0005]\u0006 — אינם נוהגים אלא בקדשי \u0003בני ישראל ולא\u0004 בקדשי \u0003גוים.\u0004","\u0003ו\u0004עוד שנינו בברייתא ש\u0003אין\u0004 הגוים \u0003עושין תמורה.\u0004 ומסבירים: טעם הדין, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשת התמורה: \u0003\"לא יחליפנו ולא ימיר\u0004 אותו\" (ויקרא כז, י), \u0003וכתיב בריש\u0004 \u0005[ונאמר בתחילת]\u0006 ה\u0003ענין: \"דבר אל בני ישראל לאמר איש כי יפליא נדר בערכך\"\u0004 (ויקראכז, י) הרי שכל האמור בפרשה דינו אמור רק לגבי ישראל.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר].\u0006 מה ששנינו בברייתא בדין קדשי הגוים: \u0003\"ואין עושין תמורה\".\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 להלכה זו? ומשיבים: \u0003דאיתקשא\u0004 \u0005[ש\u0006כן \u0005הוקשה,\u0006 הושוותה\u0005]\u0006 דין \u0003תמורת בהמה ל\u0004דין \u0003מעשר בהמה, ו\u0004דין \u0003מעשר בהמה\u0004 הוקש \u0003ל\u0004דין \u0003מעשר דגן. וגבי\u0004 \u0005[ואצל]\u0006 \u0003מעשר דגן כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"[כי את] מעשר בני ישראל אשר ירימו לה'... בני ישראל\"\u0004 (במדבר יח, כד) — לומר שמעשר דגן נוהג רק בבני ישראל \u0003ולא\u0004 ב\u0003גוים,\u0004 ומההיקש נלמד, שאף מעשר בהמה ותמורה אינם נוהגים אלא בבני ישראל ולא בגוים.","\u0003ו\u0004עוד שנינו בברייתא זו שכאשר גוי מביא קרבן, \u0003אין\u0004 הוא \u0003מביא (עליהן) נסכים\u0004 בפני עצמם, \u0003אבל\u0004 כדין כל קרבן אף \u0003קרבנו טעון נסכים.\u0004 אלו \u0003דברי ר' שמעון.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מאין אלו הדברים,\u0006 מה המקור להם\u0005]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]:\u0006 נאמר בפרשת הנסכים \"כל האזרח יעשה ככה את אלה להקריב אשה\" (במדבר טו, יג), ולשון \u0003\"אזרח\"\u0004 באה להורות: דווקא מי שהוא בגדר \u0003אזרח\u0004 (אדם מישראל) \u0003מביא נסכים\u0004 לעצמם. \u0003יכול\u0004 (אפשר) אף \u0003לא תהא עולתו\u0004 של הגוי \u0003טעונה נסכים\u0004 כלל — \u0003תלמוד לומר\u0004 באותה פרשה: \"ויין תקריב לנסך חצי ההין אשה ריח ניחוח לה'. \u0003ככה\u0004 יעשה לשור האחד או לאיל האחד או לשה בכבשים או בעזים\" (במדבר י—יא), ללמדנו שכל קרבן חייב בנסכים (\"ככה יעשה\"), ואף זה של הגוי.","עוד שנינו בברייתא ש\u0003אמר ר' יוסי: רואה אני בכולן\u0004 (בכל הדברים הללו, איסור הנאה, מעילה, פיגול, נותר, טמא, ותמורה) \u0003להחמיר\u0004 בהם בקדשי גוים\". ודנים בדבריו: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 של ר' יוסי? שכן גם בקרבן הגוי \u0003\"לה'\" כתיב ביה\u0004 \u0005[נאמר בו],\u0006 ככתוב: \"איש איש מבית ישראל ומן הגר בישראל אשר יקריב קרבנו לכל נדריהם ולכל נדבותם אשר יקריבו לה' לעולה\" (ויקרא כב, יח), ומשמע שקדשי הגוים (\"ומן הגר בישראל\") הריהם כשאר קדשי ה' לכל דבר.","ומעירים: \u0003במה דברים אמורים\u0004 — הרי זה דווקא \u0003בקדשי מזבח, אבל בקדשי בדק הבית\u0004 שהתנדבו גוים — \u0003מועלין בהן.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומשיבים: \u0003דכי גמרינן\u0004 \u0005[ש\u0006כן \u0005כאשר למדים אנו]\u0006 שאין דין \u0003מעילה\u0004 בגוי, הרי זה נסמך על גזירה שווה של המילים \u0003\"חטא\" \"חטא\" מ\u0004דין ה\u0003תרומה\u0004 ואין למדים ממנה אלא דבר שהוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003תרומה\u0004 עצמה \u0003דקדוש\u0004 \u0005[ש\u0006היא \u0005קדושה]\u0006 \u0003קדושת הגוף, אבל בקדושת בדק הבית,\u0004 שהיא \u0003קדושת דמים,\u0004 שאין הדבר עצמו קדוש, אלא דמיו, שהוא עומד למכירה לצרכי בדק הבית — \u0003לא\u0004 נאמרה הלכה זו, וקדשי גוים יש בהם מעילה.","שנינו במשנתנו כי הממיר לוקה ארבעים. ודנים בדין המלקות. \u0003אמר רב יהודה, אמר רב: כל\u0004 איסור \u0003לא תעשה\u0004 הכתוב \u0003בתורה,\u0004 אם עבר אדם ו\u0003עשה בה מעשה\u0004 — הריהו \u0003חייב\u0004 בשל כך מלקות. ואם \u0003לא עשה בה מעשה\u0004 — הריהו \u0003פטור\u0004 ממלקות.","ושואלים: \u0003וכללא\u0004 \u0005[ו\u0006כי \u0005כלל]\u0006 \u0003הוא\u0004 זה, שכל העובר על איסור \u0003לאו שאין בו מעשה\u0004 הריהו \u0003פטור\u0004 ממלקות? \u0003והרי מימר,\u0004 ש\u0003לאו שאין בו מעשה הוא, ו\u0004בכל זאת הריהו \u0003לקי\u0004 \u0005[לוקה],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]\u0006 בדינו של הממיר: \u0003לא שהוא רשאי להמיר, אלא שאם המיר\u0004 — הרי זה \u0003מומר, וסופג את הארבעים!\u0004","\u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב\u0004 בתשובה: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: לאו שאין בו מעשה\u0004 — \u0003לוקין עליו.\u0004 וחלקו עליו חכמים.","ומקשים: \u0003ומי מצית מוקמת למתניתין\u0004 \u0005[והאם יכול אתה להעמיד את משנתנו]\u0006 \u0003כר' יהודה? והא אוקימתא לרישא\u0004 \u0005[והרי העמדת את תחילת\u0006 המשנה\u0005]\u0006 ש\u0003לא כר' יהודה, דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנתנו \u0003\"הכל ממירין\",\u0004 ושאלנו בבירור הלשון: \u0003\"הכל\" לאיתויי מאי\u0004 \u0005[לרבות\u0006 את \u0005מה],\u0006 והסברנו כי לשון זו באה \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את ה\u0003יורש\u0004 שאף הוא בכלל הממירים, \u0003ו\u0004ש\u0003לא כ\u0004שיטת ר' יהודה. ומשיבים:","\u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 של משנתנו \u0003סבר לה כוותיה בחדא\u0004 \u0005[סבור הוא כמותו,\u0006 כר' יהודה, \u0005ב\u0006הלכה \u0005אחת]\u0006 — ש\u0003לאו שאין בו מעשה לוקין עליו, ו\u0004אולם הוא \u0003פליג עליה בחדא\u0004 \u0005[חולק עליו ב\u0006הלכה \u0005אחת] — ש\u0006\u0003אילו ר' יהודה סבר\u0004 \u0005[סבור]\u0006 ש\u0003יורש אינו סומך, יורש אינו ממיר, ו\u0004אילו ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003יורש סומך, יורש ממיר.\u0004","\u0003אמר רב אידי בר אבין, אמר רב עמרם, אמר ר' יצחק, אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוסי הגלילי: כל\u0004 איסור \u0003לא תעשה שבתורה,\u0004 אם עבר אדם ו\u0003עשה בו מעשה\u0004 — הריהו \u0003לוקה\u0004 על כך. ואם עבר אדם ב\u0003לא\u0004 ש\u0003עשה בו מעשה\u0004 — הריהו \u0003פטור\u0004 על כך ממלקות. \u0003חוץ מנשבע, ומימר, ומקלל חבירו בשם,\u0004 שבכל אלה, \u0003אף על פי שלא עשה מעשה\u0004 — הריהו \u0003חייב\u0004 מלקות. \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוסי בר' חנינא אמרו: אף המקדים\u0004 להפריש מפירותיו את ה\u0003תרומה ל\u0004פני שהפריש מהם את ה\u0003ביכורים,\u0004 לוקה אף שאין בו מעשה.","שנינו בשם ר' יוסי הגלילי שהנשבע לוקה אף שאין בכך מעשה. ומבררים: ה\u0003נשבע מנלן\u0004 \u0005[מנין לנו]\u0006 שלוקה? \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' מאיר:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין השבועה \"לא תשא את שם ה' אלהיך לשוא \u0003כי לא ינקה ה' את אשר ישא את שמו לשוא\"\u0004 (שמות כ, ז). ומדיוק לשון הכתוב למדים, כי דווקא \u0003בית דין של מעלה\u0004"],["\u0003אין מנקין אותו\u0004 (שאין לו כפרה בתשובה בלבד), \u0003אבל בית דין של מטה\u0004 — \u0003מלקין אותו, ו\u0004בכך \u0003מנקין אותו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ואימא\u0004 \u0005[ו\u0006אולי \u0005אומר]\u0006 שזו הכוונה ב\"לא ינקה\": ש\u0003לא תיהוי ליה\u0004 \u0005[לא תהיה לו]\u0006 \u0003נקיות כלל,\u0004 שאין תקנה כלל לעוונו לא בבית דין של מעלה ולא בבית דין של מטה?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא לאביי בתשובה: \u0003אם כן,\u0004 כדבריך, \u0003לכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 רק \u0003\"לא ינקה\", ולישתוק\u0004 \u0005[וישתוק,\u0006 ולא יוסיף\u0005]\u0006 דבר, תוספת זו של \u0003\"ה'\", למה לי\u0004 (מה באה לומר בדיוק)? — דווקא \u0003בית דין של מעלה הוא\u0004 ש\u0003אין מנקין אותו, אבל בית דין של מטה\u0004 — \u0003מלקין\u0004 אותו \u0003ו\u0004בכך \u0003מנקין אותו.\u0004","ולאחר שלמדנו מקור הדין שהנשבע לוקה, דנים עוד בדבר. \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מכתוב זה (\"לא תשא את שם ה' אלהיך לשוא כי לא ינקה ה' את אשר ישא את שמו לשוא\", שמות כ, ז) שלוקים על לאו שאין בו מעשה ב\u0003שבועת שוא,\u0004 ואולם לענין \u0003שבועת שקר מנלן\u0004 \u0005[מנין לנו]\u0006 שלוקים עליה? \u0003ר' יוחנן דידיה\u0004 \u0005[משל עצמו],\u0006 ולא בשם תנאים שאמר הלכה בענין שבועת שוא בשמם (בעמוד הקודם), \u0003אמר:\u0004 נאמר בכתוב זה \u0003\"לשוא\" \"לשוא\" שני פעמים,\u0004 ומייתור הלשון נלמד: \u0003אם אינו ענין לשבועת שוא\u0004 שכבר נאמרה פעם אחת — \u0003תניהו ענין לשבועת שקר,\u0004 ש\u0003לוקה\u0004 עליה,","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבהו: שבועת שקר\u0004 זו שלמד ר' יוחנן מכפל הלשון \"לשוא\" \"לשוא\" \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 באופן שנשבע ו\u0003אמר \"שלא אוכל\", ואכל\u0004 — \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא מעשה עבד\u0004 \u0005[עשה],\u0006 כאשר אכל, והרי זה לאו שיש בו מעשה, ובודאי לוקים עליו, ואין צורך במקרא מיוחד. \u0003ואלא\u0004 תאמר שמדובר באופן שנשבע ו\u0003אמר \"שאוכל\", ולא אכל\u0004 — אף על כך יש להקשות: \u0003ההוא מי לקי\u0004 \u0005[אותו\u0006 אופן של שבועה \u0005האם\u0006 הוא \u0005לוקה]\u0006 עליו? \u0003והאיתמר\u0004 \u0005[והרי נאמר]\u0006 לגבי מי שנשבע ואמר \u0003\"שבועה שאוכל ככר זה היום\", ועבר היום ולא אכל\u0004 את הככר — \u0003ר' יוחנן ור' שמעון בן לקיש\u0004 שניהם \u0003אמרי\u0004 \u0005[אומרים]\u0006 ש\u0003אינו לוקה.\u0004 וכל אחד מהם מנמק דין זה, ובאופן שונה.","\u0003ר' יוחנן אומר: אינו לוקה\u0004 — משום ש\u0003לאו שאין בו מעשה הוא,\u0004 שהרי במה שעבר על שבועתו, לא עשה מעשה, \u0003ו\u0004כלל הוא כי \u0003כל לאו שאין בו מעשה\u0004 — \u0003אין לוקין עליו. ו\u0004אילו \u0003ריש לקיש אמר: אינו לוקה\u0004 — \u0003משום דהוה ליה\u0004 \u0005[שהרי הינו]\u0006 \u0003התראת ספק,\u0004 שהרי צריך להתרות בו סמוך לזמן העבירה, וכיון שאין יודעים אם כוונתו שלא לאכול או לאכול, נמצא שבכל רגע ספק הוא, \u0003ו\u0004כלל הוא כי \u0003כל התראת ספק\u0004 — \u0003אין לוקין עליו!\u0004","\u0003אלא אמר ר' אבהו: תהא\u0004 (יש להעמיד) הלכה זו שלוקה על שבועת שקר שאין בה מעשה, \u0003ב\u0004מקרה שנשבע על לשעבר ואמר \u0003\"אכלתי\"\u0004 והוא לא אכל, \u0003ו\u0004כן באופן שנשבע ואמר \u0003\"לא אכלתי\"\u0004 והוא אכל.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה,\u0006 מיוחד\u0005]\u0006 שבועה לשעבר משבועה לעתיד לענין זה, \u0003דקא\u0004 \u0005[ש\u0006התורה\u0005]\u0006 \u0003מרבה\u0004 מקרה זה של הנשבע \u0003\"אכלתי\"\u0004 והוא לא אכל, \u0003ו\u0004כן הנשבע ואמר \u0003\"לא אכלתי\",\u0004 שלוקה אף שלא עשה מעשה, \u0003מ\u0004מקרה זה של הנשבע ואמר \u0003\"אוכל\" ו\u0004הוא \u0003לא אכל,\u0004 שאינו לוקה על כך, משום שלא עשה מעשה? \u0003אמר רבא\u0004 בהסבר הדבר: \u0003בפירוש ריבתה תורה\u0004 סוג זה של שבועת \u0003שקר\u0004 שלוקים עליה, שהיא ב\u0003דומה ל\u0004שבועת \u0003שוא, מה\u0004 שבועת \u0003שוא\u0004 — הריהי דווקא שבועה המתייחסת \u0003לשעבר, אף\u0004 שבועת \u0003שקר\u0004 שלוקים עליה — הריהי זו המתייחסת דווקא \u0003לשעבר.\u0004","\u0003איתיביה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה לר' אבהו\u0004 ממה ששנינו: האומר \u0003\"שבועה שלא אוכל ככר זו\"\u0004 והוסיף ואמר \u0003\"שבועה שלא אוכלנה\"\u0004 והוסיף עוד ואמר \u0003\"שבועה שלא אוכלנה\", ואכלה\u0004 את הככר, למרות שנשבע כמה פעמים — \u0003אינו חייב\u0004 מלקות \u0003אלא\u0004 פעם \u0003אחת. וזוהי\u0004 (שבועה כגון זו) הריהי \u0003שבועת ביטוי, שחייבין על זדונה\u0004 (אם עבר עליה בזדון) — \u0003מכות, ועל שגגתה\u0004 (אם עבר על השבועה בשגגה) — \u0003קרבן עולה ויורד\u0004 (קרבן חטאת המשתנה לפי מצבו הכלכלי של המביא) ומדייק ר' ירמיה: הלשון \u0003\"זוהי\"\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 ממלקות שבועה אחרת. ומעתה נשאל, \u0003מאי\u0004 \u0005[מה]\u0006 באה למעט? \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 שבועה של האומר \u0003\"אכלתי\" ו\u0004כן של הנשבע \u0003\"לא אכלתי\"\u0004 — \u0003דלא לקי\u0004 \u0005[שאינו לוקה]\u0006 על כך, ושלא כדברי ר' אבהו?!","ודוחה ר' אבהו: \u0003לא\u0004 ממלקות באה הלשון \"זוהי\" למעט, אלא מקרבן, וכך הוא לומד: \u0003זו היא\u0004 ש\u0003על שגגתה מייתי\u0004 \u0005[מביא]\u0006 \u0003קרבן, אבל\u0004 על השבועה \u0003\"אכלתי\" ו\"לא אכלתי\"\u0004 — \u0003לא מייתי\u0004 \u0005[אין מביא]\u0006 \u0003קרבן. ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' ישמעאל היא,\u0004 ש\u0003אמר:\u0004 הנשבע \u0003אינו חייב\u0004 קרבן אם עבר על שבועתו בשוגג \u0003אלא על\u0004 שבועה שנשבע על \u0003העתיד לבא.\u0004 ולא התמעטו שבועת \"אכלתי\" ו\"לא אכלתי\" אלא לענין קרבן, \u0003אבל\u0004 לענין \u0003מילקא\u0004 \u0005[מלקות]\u0006 — \u0003לקי\u0004 \u0005[לוקה]\u0006 על שבועת שקר אף לשעבר.","ודנים עוד, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנה זו: הנשבע שבועת שוא, כגון שנשבע על אבן שהיא זהב, ועוד, \u0003זוהי שבועת שוא שחייבין על זדונה מכות ועל שגגתה\u0004 — \u0003פטור.\u0004 ונדייק: הלשון \u0003\"זוהי\"\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 ממלקות שבועה באופן אחר. ומעתה נשאל, \u0003מאי\u0004 \u0005[מה]\u0006 באה למעט? \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 אופן שבועה של האומר \u0003\"אכלתי\" ו\u0004כן של הנשבע \u0003\"לא אכלתי\"\u0004 שאף הן מעין שבועת שוא — \u0003דלא לקי\u0004 \u0005[שאינו לוקה]\u0006 עליהן כלל, ושלא כדברי ר' אבהו!","ודוחים: \u0003לא,\u0004 אלא כך הוא הדיוק: \u0003זוהי\u0004 ש\u0003על שגגתה פטור מקרבן, אבל\u0004 על שבועה על העבר \u0003\"אכלתי\" ו\"לא אכלתי\"\u0004 — \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003קרבן. ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: מביאין\u0004 (חייבים) \u0003קרבן\u0004 על שבועה \u0003לשעבר\u0004 כמו על שבועה על העתיד.","ויש לשאול: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 כי ה\u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 היא כשיטת \u0003ר' ישמעאל\u0004 החלוקה על שיטת ר' עקיבא! \u0003אלא,\u0004 יש לומר כי \u0003מ\u0004תוך שה\u0003סיפא\u0004 \u0005[סוף\u0006 המשנה\u0005]\u0006 כשיטת \u0003ר' עקיבא\u0004 היא — \u0003רישא נמי\u0004 \u0005[תחילת\u0006 המשנה \u0005גם כן]\u0006 כשיטת \u0003ר' עקיבא\u0004 היא, \u0003ורישא לאו למעוטי\u0004 \u0005[ותחילת\u0006 המשנה \u0005לא למעט]\u0006 אופני השבועה \u0003\"אכלתי\" ו\"לא אכלתי\", אלא למעוטי\u0004 \u0005[למעט]\u0006 אופן השבועה \u0003\"אוכל\" ולא אכל, ו\u0004שואלים:","\u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה],\u0006 מדוע יש לפרש את המשנה דווקא באופן זה? ומשיבים: מסתבר, \u0003משום דקאי\u0004 \u0005[ש\u0006כאשר הוא, התנא, \u0005עומד]\u0006 \u0003ב\u0004שבועה המתייחסת \u0003להבא\u0004 (\"שבועה שלא אוכל ככר זה\", \"שבועה שלא אוכלנה\" וכו') — \u0003ממעט\u0004 התנא שבועה אחרת המתייחסת \u0003להבא\u0004 (\"שבועה שאוכל ככר זה\"). אבל אם \u0003קאי\u0004 \u0005[עומד]\u0006 \u0003ב\u0004שבועה המתייחסת \u0003להבא\u0004 — \u0003ממעט\u0004 שבועה המתייחסת \u0003לשעבר?\u0004 ולפיכך מסתבר לומר שכל המשנה כשיטת ר' עקיבא, שברישא שנשבע על העתיד ממעט ב\"זוהי\" \"לא אוכל\" ממלקות, ובסיפא שנשבע על העבר ממעט \"אכלתי\" ו\"לא אכלתי\", מקרבן.","\u0003ו\u0004עוד שנינו בדברי ר' יוסי הגלילי שהובאו בעמוד הקודם, כי אף ה\u0003מימר\u0004 לוקה, אף שלא עשה מעשה. ובענין זה נמסר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לתנא\u0004 \u0005[לשונה המשניות]:\u0006 כאשר הינך שונה בבית המדרש לפני הציבור דברים אלה, \u0003לא תתני\u0004 \u0005[אל תשנה]\u0006 בתוכם \u0003\"ומימר\", משום\u0004 שאין הממיר בכלל אלו שלא עשו מעשה ולוקים, שכן \u0003בדיבורו עשה מעשה,\u0004 שעשה מבהמת חולין קדשים.","עוד שנינו בדברי ר' יוסי הגלילי כי אף \u0003המקלל את חבירו בשם\u0004 הריהו לוקה, אף שלא עשה מעשה. ודנים בדבר, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 הלכה זו? אמר ר' אלעזר, \u0003אמר ר' אושעיא: אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"אם לא תשמר\u0004 לעשות את כל דברי התורה הזאת הכתובים בספר הזה ליראה את השם הנכבד והנורא הזה את ה' אלהיך\" (דברים כח, נח), שהמקלל את חבירו בשם ה' מראה שאינו ירא את השם הנכבד והנורא. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם בפסוק שלאחריו \u0003\"והפלא ה' את מכותך\".\u0004 ויש לדון בדבר: \u0003הפלאה זו איני יודע מהו\u0004 מובנה. ואולם \u0003כשהוא\u0004 (המקרא עצמו) \u0003אומר\u0004 במקום אחר, לענין דין המלקות שלוקה אדם בבית דין \"והיה אם בן הכות הרשע \u0003והפילו השפט והכהו לפניו\u0004 כדי רשעתו במספר\" (דברים כה, ב) — \u0003הוי אומר: הפלאה זו מלקות,\u0004 ומכאן, שהמקלל את חבירו בשם לוקה, אף שלא עשה מעשה.","ושואלים: אם מקור הלכה זו הוא בפסוק זה, \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אפילו\u0004 הנשבע \u0003שבועת אמת\u0004 בכלל, שאף הוא בכלל מי שאינו ירא את השם! ומשיבים: אינך יכול לומר כן, שכן \u0003בהדיא כתיב\u0004 \u0005[במפורש נאמר]\u0006 בתורה, בדין השומרים, שמותר להישבע, שכן נאמר \u0003\"שבעת ה' תהיה בין שניהם\u0004 אם לא שלח ידו במלאכת רעהו ולקח בעליו ולא ישלם\" (שמות כב, י).","וחוזרים ושואלים: \u0003אימר\u0004 \u0005[אמור]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 שמותר להישבע שבועת אמת אמורים\u0005] — דווקא לעניין שיכול להשבע על מנת\u0006 \u0003לפייס את חבירו,\u0004 כגון זה התובע מיד השומר את פקדונו, והלה אינו רוצה לשלם בטענה כי אותו הפקדון \"מת או נשבר או נשבה\" (שמות כב ט). ובשבועה זו מחזק השומר את טענתו, ונפטר מלשלם. \u0003אבל מילקא\u0004 \u0005[ללקות]\u0006 על כך, על שנשבע למרות שיכול היה לשלם ולא להישבע — \u0003לילקי\u0004 \u0005[שילקה]!\u0006 ודוחים: \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר]\u0006 כך, \u0003דהכתיב\u0004 \u0005[שהרי נאמר]\u0006 \"את ה' אלהיך תירא ואותו תעבוד ובשמו תשבע\" (דברים ו, יג), הרי שהתירה התורה להישבע שבועת אמת, ואין זה מסתבר שילקה אדם על כך.","ומשיבים על ראיה זו: אין להביא מכאן הוכחה שמותר להישבע שבועת אמת, שכן הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004למדנו \u0003כ\u0004אותה הלכה של \u0003רב,\u0004 שכן \u0003אמר רב גידל, אמר רב: מנין שנשבעין לקיים את המצות\u0004 — \u0003שנאמר: \"נשבעתי ואקימה לשמר משפטי צדקך\"\u0004 (תהלים קיט, קו)! ודוחים: אכן, הכתוב \"את ה' אלהיך תירא ואותו תעבוד ובשמו תשבע\" בא להשמיענו שנשבעים לקיים את המצוות, ואולם \u0003הכתיב קרא אחרינא\u0004 \u0005[הרי נאמר מקרא אחר]\u0006 \"את ה' אלהיך תירא אותו תעבוד \u0003ובו תדבק ובשמו תשבע\"\u0004 (דברים י, כ), והרי אלו שני מקראות שעניינם אחד,","\u0003אלא למאי אתא\u0004 \u0005[למה,\u0006 לאיזה ענין \u0005בא]\u0006 מקרא נוסף זה — \u0003ל\u0004עניינו של ה\u0003מקלל את חבירו בשם\u0004 שהוא לוקה אף שלא עשה מעשה. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הכתוב \u0003ל\u0004עניינו של ה\u0003מוציא שם שמים לבטלה\u0004 וללמדנו שלוקה על כך, אף שלא עשה מעשה, אבל המקלל את חבירו בשם אינו לוקה? ודוחים: \u0003מי גרע\u0004 \u0005[האם גרוע יותר,\u0006 פחות וחלש\u0005]\u0006 ה\u0003מקלל את חבירו בשם\u0004 שלא ילקה על כך \u0003ממוציא שם שמים לבטלה\u0004 הלוקה? והלא המקלל את חבירו חמור הוא מהמוציא שם שמים לבטלה. שהרי המקלל, מלבד שהוציא שם שמים מפיו אף קילל!","ומסבירים את השאלה: \u0003אנן, הכי קא קשיא לן\u0004 \u0005[אנו, כך היה קשה לנו],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 שה\u0003מוציא שם שמים לבטלה\u0004 שקל הוא — \u0003תיסגי ליה\u0004 \u0005[די לו]\u0006 על כך \u0003ב\u0004עונש \u0003מלקות\u0004 כדי להתכפר על ידן. \u0003אבל\u0004 ה\u0003מקלל חבירו בשם,\u0004 שחמור הוא, \u0003כיון דקעביד תרתי\u0004 \u0005[שהוא עושה שתי\u0006 עבירות\u0005],\u0006 \u0003דקא מפיק\u0004 \u0005[שהוא מוציא]\u0006 \u0003שם שמים לבטלה, וקמצער ליה לחבריה\u0004 \u0005[והוא מצער את חבירו]\u0006 בקללתו — \u0003לא תיסגי ליה\u0004 \u0005[לא יהיה די לו]\u0006 \u0003במלקות\u0004 כדי להתכפר בהן!"],["\u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר\u0006 כן\u0005]\u0006 שהכתוב בא ללמדנו דין הכפרה במלקות רק לעניין המוציא שם שמים לבטלה, ולא לעניין המקלל את חבירו בשם ה', \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 \u0003\"לא תקלל חרש\"\u0004 (ויקרא יט, יד), ומשמע שבכלל איסור זה כל אופני הקללה, בין קללה סתם ובין קללה בשם ה'. \u0003ו\u0004מעתה נדון ונאמר: \u0003אי אמרת בשלמא\u0004 \u0005[נוח\u0006 הדבר אם אומר אתה] שהאיסור \u0003לקלל את חבירו\u0004 בשם — \u0003אזהרתיה מהכא, דכתיב\u0004 \u0005[אזהרתו מכאן,\u0006 ממה \u0005שנאמר]\u0006 \u0003\"לא תקלל חרש\".\u0004 הרי לפנינו איפוא אזהרה (בכתוב זה) ועונש (\"אם לא תשמור... והפלא\"), \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שהכתוב \"אם לא תשמור... והפלא\" בא לחייב עונש מלקות ל\u0003מוציא שם שמים לבטלה,\u0004 יש לשאול: \u0003אזהרתיה מהיכא\u0004 \u0005[אזהרתו\u0006 של מוציא שם שמים לבטלה \u0005מהיכן]\u0006 היא?","ודוחים: \u0003אלמה\u0004 \u0005[ולמה]\u0006 תאמר ש\u0003לא\u0004 מצאנו אזהרה למוציא שם שמים לבטלה, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"את ה' אלהיך תירא ואתו תעבד\u0004 ובשמו תשבע\" (דברים ו, יג), והרי זו אזהרה לירא את ה' ובכלל זה שלא להוציא שם שמים לבטלה! ומשיבים: הפסוק \u0003ההוא\u0004 אין הוא אזהרה הבאה בלשון שלילה (\"לא\", \"אל\" ודומיהן), אלא \u0003אזהרת עשה הוא,\u0004 ואין אזהרת עשה נחשבת להעניש עליה.","שנינו למעלה (ג,א), בין הלוקים על איסור מן התורה (\"לאו\") אף שאין בו מעשה, כי \u0003משום\u0004 (בשם) \u0003ר' יוסי בר' חנינא אמרו\u0004 ש\u0003אף המקדים\u0004 הפרשת \u0003תרומה\u0004 מן הפירות \u0003ל\u0004נתינת פירות ה\u0003ביכורים\u0004 לכהן דינו כן. ודנים בדבר. \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לשיטתו זו של \u0003ר' יוסי בר' חנינא\u0004 שאסור להקדים את התרומה לביכורים? ומשיבים, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מלאתך ודמעך לא תאחר\"\u0004 (שמות כב, כח). ובפירוש הכתוב למדנו כי האמור \u0003\"מלאה\"\u0004 — הרי \u0003אלו ביכורים,\u0004 שמשעה שנגמרה מלאכתה של התבואה (\"מלאה\"), הריהי מתחייבת בביכורים. \u0003\"ודמעך\"\u0004 — \u0003אלו תרומה,\u0004 שכן התרומה שהתערבה בחולין (ואין בהם מאה כנגדה) הריהי אוסרתם (\"מדמעת\" אותם). \u0003ואמרה\u0004 תורה בכתוב זה \u0003\"לא תאחר\"\u0004 את \"מלאתך\" ל\"דמעך\", כלומר, שאין להקדים את התרומה לביכורים.","ודנים עוד, \u0003איתמר\u0004 \u0005[נאמר]\u0006 בדינו של זה ש\u0003הקדים תרומה לביכורים\u0004 שנחלקו בו החכמים \u0003ר' אלעזר ור' יוסי בר' חנינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לוקה\u0004 על כך, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אינו לוקה\u0004 על כך. וכיון שלא נתפרשו בעלי הדעות, מציעים: \u0003תסתיים\u0004 \u0005[תוגדר\u0006 שיטה בשם אומרה\u0005]\u0006 כי \u0003ר' יוסי בר' חנינא הוא\u0004 זה ש\u0003אמר לוקה, מ\u0004אחר שבהמשך לרשימת הלוקים (אף שלא עשו מעשה) \u0003אמר ר' יוסי בר' חנינא\u0004 במפורש ש\u0003אף המקדים תרומה לביכורים לוקה.\u0004","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 אפשר לומר כי \u0003תסתיים\u0004 \u0005[תוגדר\u0006 שיטה בשם אומרה\u0005]\u0006 ש\u0003ר' אלעזר הוא\u0004 זה ש\u0003אמר\u0004 שהמקדים תרומה לביכורים \u0003לוקה. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היו לפניו שתי כלכלות\u0004 (כעין סלים) \u0003של\u0004 פירות \u0003טבל\u0004 (שלא עושרו), \u0003ואמר:\u0004 \"כל ה\u0003מעשר\u0004 (המעשרות) \u0003של\u0004 (שמחוייבת בהם) כלכלה \u0003זו\u0004 (הראשונה) יהיו \u0003ב\u0004כלכלה \u0003זו\u0004 (השנית)\", שמפירות הכלכלה השניה יופרשו המעשרות על פירות הכלכלה הראשונה — הכלכלה \u0003הראשונה מעושרת.\u0004 אף שלא עישר מפירות שבה, ולאחר מכן, כשיפריש מהכלכלה השניה על עצמה ועל הראשונה — תתוקן אף השניה.","אולם אם אמר: \"המעשרות \u0003של\u0004 כלכלה \u0003זו\u0004 הראשונה יהיו \u0003בזו\u0004 הכלכלה השניה, \u0003ו\u0004המעשרות \u0003של\u0004 כלכלה \u0003זו\u0004 השניה יהיו \u0003בזו\u0004 הכלכלה הראשונה\" — הכלכלה \u0003הראשונה מעושרת,\u0004 כאמור, \u0003ו\u0004אולם הכלכלה \u0003השניה אינה מעושרת.\u0004 שכן, כשאמר בתחילה \"המעשרות של זו הראשונה יהיו בשניה\" — נתקנה בכך הכלכלה הראשונה, ונפטרה מן המעשרות. ואולם כשאמר בהמשך \"ושל זו (השניה) בזו (הראשונה)\" הכלכלה השניה לא נתקנה, שהרי הכלכלה הראשונה הריהי עתה פטורה מן המעשרות, ואי אפשר להפריש מפירותיה הפטורים על פירות השניה החייבים. ואם אמר: \u0003\"מעשרותיהם\u0004 של שתי הכלכלות יהיו \u0003מעשר\u0004 של כל \u0003כלכלה בחבירתה\"\u0004 — שתיהן מתוקנות, שהרי \u0003קרא את השם\u0004 של מעשר על שתיהן כאחת, וקבע את מעשרותיהן.","\u0003ואתמר\u0004 \u0005[ונאמר]\u0006 על האמור כי \u0003ר' אלעזר אמר:\u0004 הרי זה \u0003לוקה, מפני\u0004 שבאופן הראוי מפריש מעשר ראשון ולאחר מכן מעשר שני (או עני, כסדר שנות השמיטה). ואילו במקרה זה, כאשר אמר \"של זו בזו\", והפריש מהכלכלה השניה עבור הראשונה, נמצא איפוא \u0003שהקדים מעשר שני שבה\u0004 בכלכלה השניה \u0003למעשר ראשון שבחבירתה\u0004 (החוברת לה, הראויה להיות סמוכה וקודמת לה), אשר יופרש רק לאחר מכן (כשיפריש על הכלכלה השניה). נמצאנו למדים שלשיטת ר' אלעזר לוקים על הקדמה בסדר ההפרשה, בין שהקדים מעשר שני למעשר ראשון, בין שהקדים תרומה לביכורים. ומסכמים: אכן \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 כי שיטת ר' אלעזר היא.","ושואלים: \u0003אלא\u0004 מעתה, אם במחלוקת אמוראים זו שבין ר' אלעזר ור' יוסי בר' חנינא, ר' אלעזר הוא זה שאומר שלוקים על הקדמה בסדר הפרשת תרומות ומעשרות, נמצא איפוא ש\u0003ר' יוסי בר' חנינא\u0004 הוא זה ש\u0003אמר\u0004 ש\u0003אינו לוקה\u0004 על כך, ויש לשאול: \u0003לימא קשיא\u0004 \u0005[האם נאמר\u0006 כי \u0005קשה]\u0006 משיטת \u0003ר' יוסי בר' חנינא\u0004 זו, שאינו לוקה על הקדמה בסדר ההפרשה על שיטת \u0003ר' יוסי בר' חנינא\u0004 שהוסיף בהמשך לרשימת הלוקים על לאו שאין בו מעשה אף את המקדים תרומה לביכורים!","ומשיבים: \u0003לא,\u0004 אין זו סתירה בדברי ר' יוסי בר' חנינא, שכן מה שאמר \u0003ר' יוסי בר' חנינא\u0004 \"אף המקדים תרומה לביכורים\" —"],["\u0003אפטורא קאי\u0004 \u0005[על הפטור\u0006 ממלקות הנזכר בראשית הדברים הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך הוא,\u0006 החכם המביא את דברי ר' יוסי הגלילי, \u0005אומר]:\u0006 כלל הוא כי כל \u0003לאו\u0004 (לא תעשה שבתורה), \u0003שאין בו מעשה\u0004 — \u0003אין לוקין עליו. משום\u0004 (בשם) \u0003ר' יוסי בר' חנינא אמרו\u0004 חכמים ש\u0003אף המקדים תרומה לביכורים\u0004 פטור ממלקות.","ודנים בדבר: \u0003ומאי שנא מימר דלקי\u0004 \u0005[ומה שונה,\u0006 מיוחד, \u0005הממיר שלוקה]\u0006 אף שלא עשה מעשה — \u0003משום\u0004 ש\u0003בדיבורו עשה מעשה\u0004 (שהחיל קדושה על בהמת החולין שלפניו), אם כן יש לשאול: ה\u0003מקדים תרומה לביכורים נמי לילקי\u0004 \u0005[גם כן שילקה]\u0006 אף שלא עשה מעשה — \u0003משום\u0004 ש\u0003בדיבורו עשה מעשה,\u0004 שהחיל קדושת תרומה על התבואה שלפניו!","\u0003אמר ר' אבין\u0004 בתשובה: \u0003שאני התם\u0004 \u0005[שונה שם,\u0006 בדין המקדים תרומה לביכורים\u0005],\u0006 שפטור ממלקות, אף שנעשה מעשה על ידו — משום ש\u0003לאו שניתק לעשה הוא,\u0004 שאף שעבר על איסור (הקדמה בסדר ההפרשה), מכל מקום חלה עליו מצות עשה של הפרשת המעשרות, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשת המעשרות: \u0003\"מכל מעשרתיכם תרימו\u0004 את כל תרומת ה'\" (במדבר יח, כט) (ראה גרסות), שחייב לעשר שוב, כיון שהקדים את המעשר לביכורים. וכלל הוא שכל לאו הניתק לעשה, העובר עליו אינו לוקה.","מסופר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב דימי וקאמר לה להא שמעתא\u0004 \u0005[והיה אומר אותה, את ההלכה הזו],\u0006 שהמקדים תרומה לביכורים פטור ממלקות משום שהוא לאו הניתק לעשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ו\u0004כי כלל הוא ש\u0003כל לאו שניתק לעשה לא לקי\u0004 \u0005[אינו לוקה]\u0006 עליו?","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003מימר\u0004 ש\u0003לאו שניתק לעשה הוא,\u0004 שכן נאמר בו \"לא יחליפנו ולא ימיר אותו... ואם המר ימיר בהמה בבהמה והיה הוא ותמורתו יהיה קודש\" (ויקרא כז, י) — \u0003ולקי\u0004 \u0005[ולוקה]\u0006 עליו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003לא שאדם רשאי להמיר, אלא שאם המיר\u0004 — \u0003מומר, וסופג את הארבעים.\u0004","השיב רב דימי לשאלה זו של אביי: ככלל לאו הניתק לעשה אין לוקים עליו, ואין להקשות על כך מדינו של הממיר, כי בענין התמורה \u0003הוי להו תרי לאוי וחד עשה\u0004 \u0005[הריהם שני לאוים,\u0006 \"לא יחליפנו\" \"ולא ימיר אותו\", \u0005ועשה אחד],\u0006 \u0003ו\u0004כלל הוא ש\u0003לא אתי חד עשה ועקר תרי לאוי\u0004 \u0005[לא בא עשה אחד ועוקר שני לאוים].\u0006","ושואלים על כך: \u0003והרי\u0004 דינו של ה\u0003אונס\u0004 את הבתולה שאינה מאורסה, \u0003דחד לאו וחד עשה\u0004 \u0005[שלאו אחד ועשה אחד]\u0006 הוא, שכן מצווה במצות עשה — \"ולו תהיה לאשה תחת אשר ענה\" (דברים כב, כט), ובמצות לא תעשה — \"לא יוכל שלחה כל ימיו\" (ויקרא כז, י). והרי זה איפוא לאו הניתק לעשה, שכן אם אחר שנשאה לאשה עמד וגירשה ועבר על הלאו, הריהו מצווה לחזור ולשאתה ולקיים את העשה. \u0003ו\u0004בכל זאת \u0003לא אתי חד עשה ועקר לאו\u0004 \u0005[אין עשה אחד בא ועוקר,\u0006 ומונע דין מלקות במי שעבר על ה\u0005לאו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 ה\u0003אונס שגירש\u0004 את הנאנסת אחר שנשאה לאשה כמצוות הכתוב, ועבר בכך על איסור לאו של \"לא יוכל שלחה\", אם ישראל הוא המותר לשאת גרושה — הריהו עומד ו\u0003מחזיר\u0004 (נושא אותה שוב), \u0003ואינו לוקה\u0004 על האיסור שעבר עליו. \u0003ואם כהן הוא\u0004 שאסור לשאת גרושה, ובכלל זה אף את גרושתו שלו — הרי זה \u0003לוקה, ואינו מחזיר.\u0004 הרי שלוקים על לאו זה ואין העשה דוחה את הלאו הניתק לו!","ודוחים: וכי של \u0003כהנים קאמרת\u0004 \u0005[אומר אתה]\u0006 להביא ראיה?! אין להוכיח מ\u0003כהנים\u0004 כי \u0003טעמא אחרינא\u0004 \u0005[טעם אחר]\u0006 \u0003הוא\u0004 בהם, שהרי מצאנו \u0003דרבי רחמנא\u0004 \u0005[שריבתה התורה]\u0006 בהם \u0003קדושה יתירא\u0004 \u0005[יתירה],\u0006 יותר מבישראל, ולכן החמירה בהם שילקו על לאו הניתק לעשה, למרות שישראל אינו לוקה על כך.","ודנים עוד בדין המלקות בלאו הניתק לעשה. ומציעים: הלכה זו שאין לוקים על לאו הניתק לעשה, הריהי \u0003כ\u0004שיטתם של \u0003תנאי\u0004 \u0005[תנאים],\u0006 שיש תנאים הסבורים כן, שכן שנינו על האמור בקרבן פסח: \"ו\u0003לא ישאירו ממנו עד בקר\u0004 והנותר ממנו עד בוקר באש תשרופו\" (שמות יב, י) — \u0003בא הכתוב ליתן\u0004 מצות \u0003עשה\u0004 (שריפת הנותר) \u0003אחר\u0004 איסור \u0003לא תעשה\u0004 (שלא להותיר מבשר הקרבן), \u0003לומר ש\u0004אם עברו והותירו מקרבן הפסח — \u0003אין לוקין עליו,\u0004 אלו \u0003דברי ר' יהודה\u0004.","\u0003ר' יעקב אומר:\u0004 הפטור ממלקות של המותיר מקרבן הפסח \u0003לא מן השם\u0004 (מכח הגדרה זו) של לאו הניתק לעשה \u0003הוא זה, אלא משום דהוה\u0004 \u0005[שהריהו]\u0006 \u0003לאו שאין בו מעשה.\u0004 שהרי לא עשה מעשה בהותירו מקרבן הפסח. \u0003ו\u0004כלל הוא ש\u0003כל לאו שאין בו מעשה\u0004 — \u0003אין לוקין עליו.\u0004 ונדייק: \u0003מכלל\u0004 \u0005[מכאן]\u0006 ש\u0003ר' יהודה\u0004 החולק על ר' יעקב \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003לוקין עליו\u0004 על לאו הניתק לעשה.","ושואלים: \u0003ור' יעקב\u0004 הפוטר ממלקות את המותיר מקרבן הפסח משום שהוא לאו שאין בו מעשה, \u0003האי\u0004 \u0005[\u0006מקרא \u0005זה]\u0006 \u0003\"והנתר ממנו עד בקר באש תשרפו\", למאי אתא\u0004 \u0005[למה בא,\u0006 מה מלמדנו\u0005]?\u0006","ומשיבים: \u0003מיבעי ליה לכדתנן\u0004 \u0005[נצרך לו לכמו ששנינו\u0006 במשנה בדין קרבן הפסח\u0005]:\u0006 \u0003העצמות\u0004 של קרבן הפסח שנשאר בהן מח הראוי לאכילה, \u0003והגידין והנותר\u0004 מן הקרבן — \u0003ישרפו\u0004 כולם \u0003ב\u0004יום \u0003ששה עשר\u0004 בניסן, מיד למחרת החג, אך לא בחג עצמו. ואם \u0003חל\u0004 יום \u0003ששה עשר\u0004 בניסן \u0003להיות ב\u0004יום ה\u0003שבת\u0004 — \u0003ישרפו ב\u0004יום \u0003שבעה עשר\u0004 בניסן. ואין הם נשרפים בחג ובשבת, \u0003לפי שאין\u0004 מצות שריפתם של אלו \u0003דוחין לא את השבת ולא את יום טוב.\u0004","\u0003ואמר\u0004 על כך החכם \u0003חזקיה, וכן תנא דבי\u0004 \u0005[שנה\u0006 חכם \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה: מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, שאין אומרים שתבוא מצות העשה של שריפת הנותר ותדחה מצות לא תעשה של מלאכה בחג ובשבת — משום ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \"לא תותירו ממנו עד בוקר \u0003והנתר ממנו עד בקר באש תשרפו\",\u0004 והרי חזרה זו של המילים \"עד בוקר\" מה מלמדת? — \u0003בא הכתוב ליתן בוקר שני לשריפתו,\u0004 שהמצוה לשרוף את הנותר מקרבן הפסח אינה בבוקר הראשון שחל עליו האיסור, הוא בוקרו של יום החג, אלא בבוקר השני, ביום ששה עשר בניסן, ומכאן שאין מצוה זו דוחה איסור מלאכה בחג, וכן בשבת.","\u0003אמר אביי: כל מילתא\u0004 \u0005[דבר]\u0006 ש\u0003אמר רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003לא תעביד\u0004 \u0005[לא תעשה],\u0006 \u0003אם\u0004 עבר אדם ו\u0003עביד\u0004 \u0005[עשה]\u0006 — \u0003מהני\u0004 \u0005[מועיל,\u0006 תקף\u0005],\u0006 ונענש העובר על כך. וטעם שיטתו זו, \u0003דאי סלקא דעתך\u0004 \u0005[ש\u0006\u0005אם עולה על דעתך]\u0006 לומר שאם עושה אדם איסור \u0003לא מהני\u0004 \u0005[אינו מועיל.\u0006 תקף\u0005],\u0006 \u0003אמאי לקי\u0004 \u0005[מדוע לוקה],\u0006 והרי אין כל משמעות למעשיו?! \u0003רבא אמר:\u0004 כל דבר שאסרתו תורה — \u0003לא מהני מידי\u0004 \u0005[לא מועיל בכלל],\u0006 \u0003והאי דלקי\u0004 \u0005[וזה ש\u0006העובר על איסור \u0005לוקה]\u0006 — \u0003משום\u0004 ש\u0003עבר אמימרא דרחמנא\u0004 \u0005[על דבר תורה]\u0006 \u0003הוא.\u0004"],["ודנים בדברים הללו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רבא ממה ששנינו בברייתא (בעמוד הקודם): ה\u0003אונס\u0004 את הבתולה, שחייב לשאתה לאשה ואסור לגרשה, \u0003ש\u0004עמד ו\u0003גירש\u0004 את אשתו זו. \u0003אם ישראל הוא,\u0004 המותר לשאת את הגרושה — \u0003מחזיר\u0004 את גרושתו זו, \u0003ואינו לוקה\u0004 על שעבר וגירשה, שכן החזירה. ומובן הדבר לשיטת אביי, כי מאחר והחזירה הרי שלא הועילו מעשיו (שגירשה), ולכן אינו לוקה. \u0003ו\u0004אולם לשיטת רבא יש לשאול: \u0003אי אמרת\u0004 \u0005[אם אתה,\u0006 רבא, \u0005אומר]\u0006 שכל אדם העובר על איסור תורה, \u0003כיון\u0004 ש\u0003עבר אמימרא דרחמנא\u0004 \u0005[על דבר תורה]\u0006 — \u0003לקי\u0004 \u0005[לוקה],\u0006 אף שלא הועילו מעשיו בכך, \u0003הא נמי לילקי\u0004 \u0005[זה,\u0006 שגירש את אנוסתו, \u0005גם כן שילקה],\u0006 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבא!\u0004","\u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 רבא בתשובה: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הוא הדין \u0005שם,\u0006 באונס שגירש\u0005], שכן\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \"לא יוכל שלחה \u0003כל ימיו\"\u0004 (דברים כב, כט), ומובן הדברים: שמוזהר הוא על גירושין של \u0003כל ימיו,\u0004 וכיון שהמגרש את אנוסתו הריהו כל ימיו \u0003ב\u0004כלל הציווי \u0003\"עמוד והחזיר\",\u0004 נמצא שלא עבר על איסור התורה בגירושיה.","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 הסבור שאין לוקים על לאו שלא הועילו מעשיו, מה טעם כתבה התורה \"כל ימיו\", והלא די בכך שמעשה הגירושין לא הועיל כדי לפוטרו ממלקות? ומשיבים: יש צורך לכתוב \"כל ימיו\" משום ש\u0003אי לאו דאמר רחמנא\u0004 \u0005[אם לא שהיתה התורה אומרת]\u0006 \u0003\"כל ימיו\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי המגרש את אנוסתו, אכן \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003הוא דעבד ליה\u0004 \u0005[שעשה לו],\u0006 שעבר על איסור התורה והועילו מעשיו, ומשום כך לוקה על כך. ובאשר להחזרת גרושתו, הרי זה תלוי ברצונו: \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003ליהדר\u0004 \u0005[שיחזיר],\u0006 \u0003ואי בעי\u0004 \u0005[ואם רוצה]\u0006 — \u0003לא ליהדר\u0004 \u0005[לא יחזיר],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שאם עמד האונס וגירש את אנוסתו הריהו חייב להחזירה, ולא הועילו איפוא מעשיו בגירושיה, ומשום כך אינו לוקה על כך.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר],\u0006 בענין הראיה מדין האונס. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא בדינו של ה\u0003אונס שגירש\u0004 את אנוסתו, ש\u0003אם ישראל הוא\u0004 המותר לשאת גרושה — הריהו \u0003מחזיר\u0004 אותה, \u0003ואינו לוקה\u0004 על שגירשה. \u0003ו\u0004אולם \u0003אם כהן הוא\u0004 האסור בגרושה, ואף בגרושתו שלו — הרי זה \u0003לוקה\u0004 על שגירשה, \u0003ואינו מחזיר\u0004 אותה. ונדייק: \u0003קתני\u0004 \u0005[שנינו]\u0006 בברייתא ש\u0003אם ישראל הוא\u0004 — \u0003מחזיר,\u0004 ומשמע שחייב הוא להחזירה משום שלא הועילו מעשיו כשגירשה. ומעתה לשיטת רבא מובן הדבר, שהרי לדעתו בכל איסורי תורה אם עבר אדם עליהם, לא הועילו מעשיו. ואולם לשיטת אביי, הסבור שבכל איסורי תורה אם עבר אדם עליהם הועילו מעשיו, דין זה של האונס הישראלי שעבר וגירש, שלא הועילו מעשיו, הריהו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003אביי!\u0004","ומשיבים: לשיטת אביי, בכל איסורי תורה אומרים אנו שלא הועילו מעשיו של העובר עליהם, ואולם בדין זה של האונס \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד, \u0005שם],\u0006 שכן \u0003רחמנא אמר\u0004 \u0005[התורה אומרת]\u0006 \u0003\"כל ימיו\"\u0004 — ללמדנו: \u0003כל ימיו ב\"עמוד והחזיר\",\u0004 שדווקא במקרה מסויים זה, לא הועילו מעשיו של העובר על איסור תורה, ולא בשאר איסורים.","ושואלים: \u0003ו\u0004לשיטת \u0003רבא\u0004 הסבור שבכל איסורי תורה לא הועילו מעשיו של העובר, מה צורך לכתוב \"כל ימיו\"? ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 רבא בהסבר הדבר: \u0003אי לא כתב רחמנא\u0004 \u0005[אם לא היתה אומרת התורה]\u0006 \u0003\"כל ימיו\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003לילקי\u0004 \u0005[שילקה]\u0006 האונס המגרש את אנוסתו, אף שלא הועילו מעשיו, \u0003וליהדר\u0004 \u0005[ויחזיר]\u0006 אותה, \u0003דהוה ליה\u0004 \u0005[שהרי הינו]\u0006 \u0003לאו\u0004 (לא תעשה) \u0003גרידא\u0004 \u0005[סתם,\u0006 רגיל\u0005],\u0006 כשאר איסורי תורה, שלוקה העובר עליהם, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"לא יוכל לשלחה\". אהכי כתב קרא\u0004 \u0005[משום כך אמר הכתוב]\u0006 \u0003\"כל ימיו\"\u0004 שהוא מעין ציווי — כדי \u0003לשווייה\u0004 \u0005[לעשותו,\u0006 להגדירו\u0005]\u0006 \u0003לאונס\u0004 המגרש את אנוסתו \u0003ל\u0004איסור \u0003לא תעשה שניתק לעשה,\u0004 ש\u0003אין לוקין עליו.\u0004","ודנים עוד בשיטותיהם של אביי ורבא. \u0003והרי\u0004 בדינו של האדם ה\u0003תורם\u0004 (המפריש את תרומותיו) \u0003מן\u0004 התבואה \u0003הרעה\u0004 (הגרועה) \u0003על היפה\u0004 (המשובחת), \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 בדין הפרשת התרומות \"מכל מתנותיכם תרימו את כל תרומת ה' מכל חלבו\" (במדבר יח, כט), וללמדנו: מ","\u0003חלבו\u0004 (המובחר שבו) — \u0003אין\u0004 \u0005[כן]\u0006 מפריש תרומות הפירות המובחרים, ואולם מן ה\u0003גירועין\u0004 (הגרוע שבו) — \u0003לא\u0004 יופרשו התרומות. נמצא שיש איסור מן התורה להפריש מן הרעה על היפה, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003אין תורמין מן הרעה על היפה, ואם\u0004 עבר ו\u0003תרם\u0004 מן הרעה על היפה — \u0003תרומתו תרומה. אלמא מהני\u0004 \u0005[הרי\u0006 נסיק ש\u0005הועילו]\u0006 מעשיו של העובר על איסור תורה, והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבא\u0004 הסבור שהעובר על איסור תורה לא הועילו מעשיו!","ומתרצים: \u0003אמר\u0004 \u0005[יכול לומר,\u0006 להשיב\u0005]\u0006 \u0003לך רבא\u0004 כי אין להקשות מדין הפרשת תרומות על שאר איסורי תורה, שכן \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם],\u0006 \u0003כ\u0004דברי \u0003ר' אילעא,\u0004 שכן \u0003אמר ר' אילעא: מנין לתורם מן הרעה על היפה, ש\u0004אף שעבר על איסור תורה, \u0003תרומתו תרומה\u0004 — \u0003שנאמר: \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\"\u0004 (במדבר יח פסוק לב), כלומר, אם מפרישים תרומה מן המובחר (\"בהרימכם את חלבו ממנו\") — עושים בכך דבר ראוי (\"ולא תשאו עליו חטא\"), ומכאן משמע שאם מפרישים דבר גרוע — נושאים חטא על כך. ויש לשאול: \u0003אם\u0004 הדבר הגרוע שהופרש \u0003אינו קדוש\u0004 בקדושת תרומה, \u0003נשיאות חטא למה?\u0004 שאם אינה תרומה — לא עשה דבר, ואין במעשה שעשה כל חטא! אלא \u0003מיכן\u0004 (מכאן) \u0003לתורם מן הרעה על היפה\u0004 — \u0003שתרומתו תרומה.\u0004 ודווקא באיסור זה הועילו מעשיו, ולא בשאר איסורים.","ושואלים: \u0003ול\u0004שיטת \u0003אביי,\u0004 הסבור שבכל איסורי תורה הועילו מעשיו של העובר עליהם, מדוע נצרך לימוד מיוחד זה במפריש מן הרעה על היפה! ומשיבים: נצרך הכתוב הזה, כי \u0003אי לאו דאמר רחמנא\u0004 \u0005[אם לא שאמרה התורה]\u0006 כתוב זה \u0003\"ולא תשאו עליו חטא\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הכי אמר רחמנא\u0004 \u0005[כך אמרה התורה]:\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003מצוה מן המובחר,\u0004 להפריש את התרומה מן המשובח שבפירות, \u0003ו\u0004אולם \u0003אי לא עביד\u0004 \u0005[אם לא עשה]\u0006 כן, והפריש מן הגרוע — העושה כן, \u0003\"חוטא\" לא מיקרי\u0004 \u0005[אינו נקרא].\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שהריהו נקרא \"חוטא\".","ודנים עוד בשיטותיהם של אביי ורבא. \u0003והרי\u0004 בדינו של המפריש תרומותיו \u0003ממין על שאינו מינו\u0004 (כגון שהפריש מן הענבים על הזיתים), \u0003דאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003\"כל חלב יצהר\u0004 וכל חלב תירוש ודגן ראשיתם אשר יתנו לה' לך נתתים\" (במדבר יח, יב) — ובאה לשון יתירה זו של \"חלב\" האמורה פעמיים, בתרומת היצהר ובתרומת התירוש, ללמדנו שיש \u0003ליתן\u0004 (להפריש) \u0003חלב\u0004 (מובחר) \u0003ל\u0004מין \u0003זה\u0004 בפני עצמו \u0003וחלב\u0004 (ומובחר) \u0003ל\u0004מין \u0003זה\u0004 בפני עצמו. שאין מעשרים מזה על זה. \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003אין תורמין ממין על שאינו מינו, ואם\u0004 עבר ו\u0003תרם\u0004 ממין על שאינו מינו — \u0003אין תרומתו תרומה. אלמא\u0004 \u0005[מכאן]\u0006 שהעובר על איסור תורה \u0003לא מהני\u0004 \u0005[לא הועילו]\u0006 מעשיו, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003אביי\u0004 ומתרצים:","\u0003אמר\u0004 \u0005[יכול לומר,\u0006 להשיב\u0005]\u0006 \u0003לך אביי\u0004 כי אין להקשות מדין התרומה על שאר איסורי תורה, כי \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם],\u0006 שכן חזר ו\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ראשיתם\"\u0004 ובלשון רבים — ללמדנו שכך יש לנהוג: לתת \u0003\"ראשית\"\u0004 (תרומה) \u0003ל\u0004מין זה בפני עצמו, \u0003ו\"ראשית\" ל\u0004מין \u0003זה\u0004 בפני עצמו. שלא הועילו מעשיו אם הפריש ממין על שאינו מינו. \u0003וכן אמר ר' אילעא\u0004 כי למדנו מן הכתוב \"ראשיתם\" שיש לתת \u0003\"ראשית\"\u0004 לכל מין ומין בפני עצמו.","ושואלים: \u0003ול\u0004שיטת \u0003רבא\u0004 הסבור שבכל איסורי התורה אם עבר עליהם אדם, לא הועילו מעשיו, מדוע נצרך לימוד מיוחד במפריש ממין על שאינו מינו לומר שלא הועילו מעשיו, אם כך הדין בכל איסורי התורה? ומשיבים: \u0003אי לאו דאמר רחמנא\u0004 \u0005[אם לא שהיתה כותבת התורה]\u0006 \u0003\"ראשית\"\u0004 (\"ראשיתם\"), \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא בתרומת \u0003תירוש ויצהר, דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 \u0003\"חלב\" \"חלב\"\u0004 — הוא ש\u0003אין תורמין מזה על זה,\u0004","\u0003אבל\u0004 בתרומת \u0003תירוש ודגן,\u0004 או בתרומת \u0003דגן ודגן\u0004 (כגון מן החיטים על השעורים, ששני מיני דגן הם), \u0003דחד\u0004 \u0005[ש\u0006כתוב \u0005אחד]\u0006 \u0003\"חלב\"\u0004 בלבד \u0003כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (\"וכל חלב תירוש ודגן\". במדבר יח, יב), \u0003כי תרים מהאי אהאי\u0004 \u0005[כאשר תורם מזה על זה]\u0006 — לא עבר על איסור התורה, ו\u0003לא לקי\u0004 \u0005[אינו לוקה]\u0006 על כך. לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"ראשית\"\u0004 (\"ראשיתם\") — ללמדנו כי יש \u0003ליתן חלב ל\u0004מין \u0003זה\u0004 בפני עצמו, \u0003וחלב ל\u0004מין \u0003זה\u0004 בפני עצמו.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בהסברו של רבא מדוע נצרך הכתוב \"ראשיתם\". שאלמלא היה כתוב זה, הייתי אומר שדווקא בתירוש ויצהר, שנאמר בהם \"חלב\" \"חלב\", הוא שאין תורמים מזה על זה, \u0003הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 \u0003תירוש ודגן, דחד\u0004 \u0005[ש\u0006כתוב \u0005אחד]\u0006 \u0003\"חלב\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 — \u0003תרים מהאי אהאי\u0004 \u0005[תורם מזה על זה].\u0006 לכך \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ראשית\"\u0004 (\"ראשיתם\"), לומר שאף בהם אינו מפריש אלא ממין על מינו.","וממשיכים לדון בשיטותיהם של אביי ורבא. \u0003והרי\u0004 בדין ה\u0003חרמים\u0004 (הקדשות שהקדיש אדם מנכסיו בלשון \"חרם\"), והקדישם לכהנים (שכן יש חרמים המוקדשים לבדק הבית), \u0003דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \"אך כל חרם אשר יחרים איש לה' מכל אשר לו מאדם ובהמה ומשדה אחוזתו \u0003לא ימכר ולא יגאל\u0004 כל חרם קודש קדשים הוא לה'\" (ויקרא כז, כח), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005] בערכין\u0006 : \u0003חרמי כהנים\u0004 (חרמים שהוקדשו עבור הכהנים) — \u0003אין פודין אותם,\u0004 \u0003אלא נותנין\u0004 אותם \u0003לכהן.\u0004 ומלשון המשנה עצמה (ערכין כח,ב) \"חרמי כהנים — אין פודין אותם\", יש לדייק: \u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 ש\u0003לא מהני\u0004 \u0005[לא הועילו]\u0006 מעשיו, שאף אם פדאם, לא הועילו מעשיו, והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003אביי\u0004 הסבור שבכל איסורי תורה, אם עבר אדם עליהם, הועילו מעשיו!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 אביי בתשובה: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם],\u0006 שכן \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"קדש קדשים הוא\"\u0004 — ללמדנו שאף אם עבר אדם ופדאו, \u0003בהווייתו יהא.\u0004"],["ושואלים: \u0003ול\u0004שיטת \u0003רבא\u0004 שבכל איסורי תורה, אם עבר עליהם אדם, לא הועילו מעשיו, מה מלמדנו \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \"קודש קדשים \u0003הוא\"\u0004 (ויקרא כז, כח) האמור בחרמים? ומשיבים: כתוב זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 קרבן \u0003בכור\u0004 בהמה טהורה, שאינו בכלל איסור מכירה כחרמים וכקרבן מעשר בהמה, אף שדין זה של מעשר בהמה נלמד מחרמי הכהנים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003בבכור נאמר\u0004 \"אך בכור שור או בכור כשב או בכור עז \u0003לא תפדה\u0004 קודש הם\" (במדבר יח, יז), ומתוך שנאמר בו רק \"לא תפדה\" למדנו שאין הבעלים יכולים לפדותו שייעשה כחולין גמורים, \u0003ו\u0004מכל מקום אם נפל בו מום \u0003נמכר הוא\u0004 לכהן בין חי ובין שחוט בתורת בכור, והריהו כחולין גמורים. הרי שהבכור יכול להימכר. ואילו \u0003ב\u0004קרבן \u0003מעשר\u0004 בהמה \u0003נאמר \"לא יגאל\"\u0004 (ויקרא כז, לג) — הרי זה בא לומר שאין כל דרך להוציאו מקדושתו, \u0003ו\u0004לא רק שאין פודים אותו אלא אף \u0003אינו נמכר\u0004 בשום אופן: \u0003לא חי ולא שחוט, ולא תם ולא בעל מום.\u0004","ודנים עוד במחלוקת אביי ורבא \u0003והרי\u0004 אפשר להביא ראיה מדין ה\u0003תמורה, דאמר רחמנא\u0004 \u0005[ש\u0006כן \u0005אמרה התורה]\u0006 לאסור את מעשה התמורה, ככתוב: \u0003\"לא יחליפנו ולא ימיר אתו\u0004 טוב ברע או רע בטוב\" (ויקרא כז, י), \u0003ותנא\u0004 \u0005[ושנה\u0006 במשנתנו\u0005]:\u0006 \u0003לא\u0004 (אין) הכוונה במה שפתחה המשנה \"הכל ממירין\" \u0003שאדם רשאי להמיר, אלא שאם\u0004 עבר ו\u0003המיר\u0004 — הרי זו, בהמת החולין, \u0003מומר\u0004 (חלה עליה קדושת קרבן), \u0003וסופג\u0004 (ולוקה) הממיר \u0003את הארבעים\u0004 מלקות. ונסיק מכאן: \u0003אלמא מהני\u0004 \u0005[הרי איפוא\u0006 ש\u0005מועילים]\u0006 מעשיו, והרי זו ראיה לאביי, ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רבא\u0004 הסבור שלא הועילו מעשיו של העובר על דין תורה!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 רבא: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 בתמורה, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במפורש בהמשך הכתוב \"ואם המר ימיר בהמה בבהמה \u0003והיה הוא ותמורתו יהיה קדש\",\u0004 והרי זה דין מיוחד בתמורה שיועילו מעשיו של העבריין.","ושואלים: \u0003ולאביי\u0004 הסבור שבכל איסורי התורה הועילו מעשיו, מדוע נצרכה התורה להשמיענו שחלה התמורה? ומשיבים: \u0003אי לאו דאמר רחמנא\u0004 \u0005[אם לא שהיתה כותבת התורה]\u0006 \u0003\"והיה הוא ותמורתו\u0004 יהיה קודש\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי אכן יועילו מעשיו, ותחול התמורה, ואולם באופן זה: ש\u0003תצא זו\u0004 (בהמת הקרבן) מקדושתה \u0003ותכנס זו\u0004 (בהמת החולין) לקדושה במקומה, לכן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב ששתיהן קדושות, ואין בהמת הקודש נפקעת מקדושתה אף שבהמת החולין התקדשה.","ודנים עוד, \u0003והרי\u0004 אפשר להביא ראיה לענין זה מדין ה\u0003בכור\u0004 (בכור בהמה טהורה), \u0003דאמר רחמנא\u0004 \u0005[ש\u0006כן \u0005אמרה התורה]\u0006 שאין לפדותו, ככתוב: \"אך בכור שור או בכור כשב או בכור עז \u0003לא תפדה\u0004 קודש הם\" (במדבר יח, יז), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה להלן\u0005]:\u0006 כל הקדשים שנפל בהם מום \u0003יש להן פדיון\u0004 (פודים אותם), \u0003ו\u0004כן \u0003לתמורותיהן\u0004 (אם הן בעלי מום) יש \u0003פדיון, חוץ מן הבכור ומן המעשר\u0004 שאף שנפל בהם מום, אין בהם דין פדיון. ואם פדה אותם אינם פדויים. ונסיק מכאן: \u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 ש\u0003לא מהני\u0004 \u0005[לא מועילים]\u0006 מעשיו, והרי זו ראיה לשיטת רבא שלא הועילו מעשיו של העובר על דין תורה, ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003אביי\u0004 הסבור שמועילים מעשיו!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 אביי בתשובה לכך: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 בבכור ומעשר שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במפורש בענין הבכור \"קודש \u0003הם\"\u0004 — והרי הדגשה זו באה להורות: שתמיד, אף שהם בעלי מום, ונפדו, \u0003בהווייתן יהו,\u0004 שאין הם יוצאים מקדושתם.","ושואלים: \u0003ול\u0004שיטת \u0003רבא\u0004 הסבור שבכל דיני התורה לא הועילו מעשיו של העובר עליהם, אם כן \u0003האי\u0004 \u0005[\u0006הדגשה \u0005זו]\u0006 \"קודש \u0003הם\" למה ליה\u0004 \u0005[לו],\u0006 למה היא נצרכת? ומשיבים: ללמדנו שאם המיר את קרבן הבכור או את קרבן המעשר, וכדין התמורה חלה קדושתם על בהמת החולין — רק \u0003הן\u0004 עצמם (הבכור והמעשר) \u0003קריבין\u0004 על המזבח, \u0003ואין תמורתן קריבין\u0004 כלל, שאין תמורת הבכור ותמורת המעשר כשאר תמורות, הקריבות אף הן על המזבח.","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 שהכתוב הזה \"קודש הם\" מלמד שלא יועילו מעשיו של הפודה את הבכור והמעשר, \u0003האי סברא מנא ליה\u0004 \u0005[סברה,\u0006 הלכה \u0005זו\u0006 שאין תמורתם של הבכור ושל המעשר קריבה, \u0005מנין לו]?\u0006 ומשיבים: נלמד הדבר מכתוב אחר האמור בקרבן בכור \"אך בכור אשר יבוכר לה' בבהמה לא יקדיש איש אותו \u0003אם שור אם שה לה' הוא\"\u0004 (ויקרא כז, כו) — לדייק: דווקא הוא \u0003לה' קריב, ואין תמורתו קריבה.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003רבא\u0004 שלמד שאין תמורת הבכור והמעשר קריבה מהפסוק \"קודש הם\", מה לומד הוא מהכתוב \"לה' הוא\"? ומשיבים: \u0003אין הכי נמי דמההוא קרא\u0004 \u0005[אכן, אמנם כן שמאותו כתוב\u0006 נלמד הדבר\u0005],\u0006 \u0003אלא\u0004 \"קודש \u0003הם\" למה לי,\u0004 מה הוא מלמד? — \u0003לימד על\u0004 קרבן \u0003בכור ו\u0004קרבן \u0003מעשר שנתערב דמן ב\u0004דמם של קרבנות אחרים מכלל \u0003כל העולין\u0004 למזבח — \u0003שקריבין\u0004 (שנזרקים הדמים המעורבים הללו) \u0003לגבי\u0004 ה\u0003מזבח,\u0004 כדרך שהיו נזרקים כשלעצמם. שכך לימדנו כתוב זה \"קודש הם\" — שהריהם תמיד בהוויתם, אף אם נתערבו באחרים.","ושואלים: \u0003ו\u0004לשיטת \u0003אביי\u0004 שלמד מהכתוב \"קודש הם\" לענין שלא יועילו מעשיו של הפודה את הבכור והמעשר, \u0003האי סברא מנא ליה\u0004 \u0005[סברה,\u0006 הלכה \u0005זו\u0006 שדמם של הבכור והמעשר שהתערב בדם אחרים נזרק על המזבח, \u0005מנין לו]?\u0006 ומשיבים: הלכה זו נלמדת \u0003מ\u0004הכתוב בקרבנות יום הכיפורים, בענין הזאת הכהן הגדול על המזבח הפנימי, לאחר שהזה על הפרוכת מדם הפר לחוד ומדם השעיר לחוד, \u0003\"ולקח מדם הפר ומדם השעיר\u0004 ונתן על קרנות המזבח סביב\" (ויקרא טז, יח), ומשמע הדברים, לשיטתו של ר' יאשיה (שתובא להלן) שמעורבים הדמים זה בזה. ומעתה יש לשאול: \u0003והלא דם הפר מרובה\u0004 \u0003מ\u0004דמו \u0003של\u0004 ה\u0003שעיר,\u0004 ובכל זאת הכתוב מזכיר את דם השעיר, שנאמר \"מדם הפר ומדם השעיר\", הרי שלא התבטל ברובו של דם הפר \u0003מיכן\u0004 (מכאן) נלמד כלל \u0003ל\u0004דינם של כל הקרבנות ה\u0003עולין\u0004 על המזבח, שנתערבו — \u0003שאין\u0004 הדמים \u0003מבטלין זה את זה.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"ולקח מדם הפר ומדם השעיר\"\u0004 — \u0003שיהו\u0004 דם הפר ודם השעיר \u0003מעורבין\u0004 זה בזה, אלו \u0003דברי ר' יאשיה.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003רבא\u0004 שלמד דין זריקת הדמים המעורבים מהכתוב \"קודש הם\", מדוע לא למד דין זה מהכתוב \"ולקח מדם הפר ומדם השעיר\"? ומשיבים: לדעת רבא אין ללמוד מכתוב זה, כי \u0003התם\u0004 \u0005[שם,\u0006 בהזאת דם הפר ודם השעיר\u0005]\u0006 — אין הדמים הללו מעורבים זה בזה, אלא מזה הכהן הגדול \u0003מזה\u0004, מדם הפר \u0003בפני עצמו, ומזה\u0004, מדם השעיר \u0003בפני עצמו, וסבר לה\u0004 \u0005[וסבור הוא]\u0006 רבא \u0003כ\u0004שיטת \u0003ר' יונתן\u0004 החולק על ר' יאשיה, וסבור הוא שאין מערבים כלל את הדמים.","ודנים עוד בשאלה זו. \u0003והרי\u0004 אפשר להביא ראיה מדין \u0003מעשר\u0004 בהמה, \u0003דאמר רחמנא\u0004 \u0005[ש\u0006כן \u0005אמרה התורה]\u0006 \u0003\"לא יגאל\"\u0004 (ויקרא כז, לג) — לומר שאין כל דרך להוציאו מקדושתו, לא בפדיון ולא במכירה, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה להלן\u0005]:\u0006 כל הקדשים שנפל בהם מום \u0003יש להן פדיון\u0004 (פודים אותם), \u0003ו\u0004כן \u0003לתמורותיהן\u0004 (אם הן בעלי מום) יש דין פדיון, \u0003חוץ מן הבכור ומן המעשר\u0004 שנפל בהם מום, שאין להם פדיון, ונאכלים על ידי בעליהם במומם. ונסיק מכאן: \u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 ש\u0003לא מהני\u0004 \u0005[לא מועילים]\u0006 מעשיו, והרי זו ראיה לשיטת רבא שלא הועילו מעשיו של העובר על איסור תורה, ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003אביי\u0004 ומשיבים:","\u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 אביי בתשובה לכך: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 במעשר \u0003דיליף\u0004 \u0005[ש\u0006כן \u0005נלמד]\u0006 דינו של מעשר בהמה בגזירה שווה לשון \u0003\"עברה\"\u0004 האמורה במעשר בהמה, \"וכל מעשר בקר וצאן כל אשר יעבור תחת השבט העשירי יהיה קודש לה'\" (ויקרא כז, לב), מלשון \u0003\"עברה\"\u0004 האמורה ב\u0003בכור \"והעברת כל פטר רחם לה'\" (שמות יג, יב) ובבכור, כאמור לעיל, יש לימוד מיוחד לענין זה.\u0004","ודנים עוד. \u0003והרי\u0004 אפשר להביא ראיה באותו נושא ממי ש\u0003הקדימה\u0004 להפרשת \u0003תרומה ל\u0004פני שנתן לכהן את ה\u0003ביכורים, דאמר רחמנא\u0004 \u0005[שאמרה\u0006 \u0005התורה]\u0006 \u0003\"מלאתך ודמעך לא תאחר\"\u0004 (שמות כב, כח). ובפירוש הכתוב למדנו כי \"מלאה\" — אלו ביכורים, \"דמעך\" — זו התרומה. ואסר כתוב זה להקדים את התרומה לביכורים, כאמור \"לא תאחר\" את \"מלאתך\" ל\"דמעך\". \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדים\u0004 את התרומה לביכורים, \u0003אף על פי שהוא\u0004 עובר \u0003בלא תעשה\u0004 — \u0003מה שעשה עשוי.\u0004 והרי זו ראיה לאביי שהועילו מעשיו של העובר על איסור תורה, וקושיה לשיטת רבא הסבור שלא הועילו מעשיו!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא\u0004 בתשובה לכך: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 בתרומה וביכורים שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"מכל מעשרתיכם תרימו תרומה\"\u0004 (במדבר יח, כח), ובכלל כתוב זה איסור הקדמת מעשר ראשון לפני תרומה, וכן איסור הקדמת התרומה לביכורים, ומכל מקום השמיענו הכתוב שתרומתו תרומה אף אם הקדימה לביכורים (כנלמד למעלה ד,ב).","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 שבכל איסורי תורה הועילו מעשיו של העובר, מדוע יש צורך בכתוב שיודיענו שחלה התרומה שהוקדמה לביכורים? ומשיבים: \u0003מיבעיא ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה ללימוד אחר. כמובא בדינו של מעשר ראשון שאם הקדימו הבעלים לתתו ללוי עוד בהיות התבואה בשבוליה, לפני שדשו אותה, ולפני שהפרישו ממנה תרומה גדולה לכהן — פטור מעשר זה מתרומה גדולה. שאף שצריך להפריש תחילה מן התבואה תרומה גדולה לכהן, והיה צריך ליטול תרומה גדולה גם מן התבואה שבמעשר זה, מכל מקום נפטר הלוי שקיבלה מהפרשה זו. וטעם הדבר — שנאמר: \"והרמותם ממנו תרומת ה' מעשר מן המעשר\" (במדבר יח, כו), ומלשון הכתוב נסיק: מעשר מן המעשר (תרומת מעשר) בלבד הריהו מחוייב, ולא תרומה גדולה ותרומת מעשר מן המעשר. ועל הלכה זו \u0003אמר רב פפא לאביי\u0004 בשאלה: \u0003אלא מעתה\u0004 שנלמד הדבר מן הכתוב, אם כן \u0003אפילו\u0004 כאשר \u0003הקדימו\u0004 הלוי לכהן ונטל מעשר ראשון כאשר כבר נקצרה התבואה ונערמה \u0003בכרי נמי ניפטר\u0004 \u0005[גם כן ייפטר],\u0006 ולא יצטרך הלוי להפריש תרומה גדולה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב פפא בתשובה: \u0003עליך\u0004 (כנגד טענה זו) \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"מכל מעשרתיכם תרימו\u0004 את כל תבואת ה' (במדבר יח כט), ללמד שאת \"תרומת ה'\", התרומה הגדולה, צריך להרים מכל מתנה ומתנה.","ושאלו רב פפא: \u0003מה ראית\u0004 לחלק בצורה זו, ולומר \u0003לרבות את\u0004 הנותן מן \u0003הכרי\u0004 שהלוי חייב בכל התרומות, \u0003ולהוציא את השיבלין\u0004 שהוא חייב רק בתרומת מעשר? והשיבו אביי: \u0003מרבה אני את הכרי\u0004 — \u0003ש\u0004כן \u0003ישנו בכלל דיגון\u0004 (ששוב אינו עוד \"שבולת\" אלא \"דגן\"), ובתרומה נאמר במפורש \"ראשית דגנך\" (דברים יח, ד), \u0003ומוציא אני את השיבלין\u0004 — \u0003שאין\u0004 הן \u0003בכלל דיגון,\u0004 ולא חלה עליהן עדיין חובת תרומה.","ודנים עוד בשאלה זו. \u0003והרי\u0004 אפשר להביא ראיה מדין קידושי \u0003אלמנה לכהן גדול, דרחמנא אמר\u0004 \u0005[ש\u0006כן \u0005אמרה התורה]\u0006 \u0003\"אלמנה וגרושה\u0004 וחללה זונה את אלה \u0003לא יקח\u0004 כי אם בתולה מעמיו יקח אשה. ולא יחלל זרעו בעמיו כי אני ה' מקדשו\" (ויקרא כא, יד—טו), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 לענין קביעת יחוסו של ולד: \u0003כל מקום שיש קדושין\u0004 (שהקידושין תקפים, והאשה נחשבת נשואה על ידם) \u0003ויש עבירה\u0004 בנישואין אלה — יחוס \u0003הולד\u0004 הנולד מביאה זו \u0003הולך אחר\u0004 (נקבע על פי) \u0003הפגום\u0004 שבין בני הזוג. ומסבירה המשנה כדוגמא לדבר: \"זו אלמנה לכהן גדול\" — שהולד הריהו חלל ופסול לכהונה. והרי זו ראיה לשיטת אביי שמעשיו מועילים, שכן חלו הקידושין, וקשה לשיטת רבא!","ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005כאן],\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במפורש בדין הולד הנולד מביאת כהן גדול לאלמנה \u0003\"לא יחלל זרעו\",\u0004 לומר שהוא חלל משום שחלו הקידושין, ואינו ממזר (שהוא הנולד מקידושין שאינם חלים).","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 שבכל איסורי תורה אם עבר אדם מעשיו מועילים, מדוע נצרך כתוב זה? ומשיבים: אם רק לומר שחלו הקידושין ולכן הוא חלל, אם כן \u0003נימא קרא\u0004 \u0005[יאמר הכתוב]\u0006 \u0003\"לא יחל\", מאי\u0004 \u0005[מהו]\u0006 \u0003\"לא יחלל\"\u0004 — ללמדנו שיש שני חילולים בביאה זו: חילול \u0003אחד\u0004 — \u0003לו,\u0004 לולד שנולד מביאה זו. \u0003ו\u0004חילול \u0003אחד,\u0004 נוסף — \u0003לה,\u0004 לאשה, שמתחללת אף היא בביאה זו, והריהי מעתה \"זונה\" האסורה אף לכהן הדיוט.","ודנים עוד בשאלה זו. \u0003והרי\u0004 אפשר להביא ראיה ממי ש\u0003הקדיש\u0004 בהמות שהן \u0003בעלי מומין ל\u0004קרבן הקרב על ה\u0003מזבח, דרחמנא אמר\u0004 \u0005[שאמרה התורה]:\u0006 \u0003\"כל אשר בו מום לא תקריבו\u0004 כי לא לרצון יהיה לכם\" (ויקרא כב, כ), ובכלל איסור \"לא תקריבו\" אף עצם ההקדשה. \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדיש בעלי מומין לגבי מזבח, אף על פי שהוא\u0004 עובר \u0003בלא תעשה\u0004 — \u0003מה שעשה עשוי\u0004 ונתקדשו הבהמות. והרי זו איפוא ראיה לשיטת אביי שהועילו מעשיו של העובר, ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רבא\u0004 הסבור שלא הועילו מעשיו!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא\u0004 בתשובה: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במפורש \u0003\"ולנדר לא ירצה\"\u0004 (ויקרא כב, כג), ללמדנו כי לענין \u0003רצוי,\u0004 שיעלה לרצון על המזבח — \u0003הוא דלא\u0004 \u0005[שאינו]\u0006 \u0003מרצה, הא מיקדש\u0004 \u0005[אבל להתקדש]\u0006 — \u0003קדשי\u0004 \u0005[מתקדש].\u0006","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 מה צורך להשמיענו כתוב זה? ומשיבים: \u0003אי דלא אמר רחמנא\u0004 \u0005[אם שלא היתה אומרת התורה]\u0006 \u0003\"ולנדר לא ירצה\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 אמנם המקדיש הזה הריהו \u0003כעובר\u0004 על \u0003מצוה, ו\u0004אולם הקרבן עצמו \u0003כשר\u0004 להקרבה על אף שהוא בעל מום. לכן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שהוא פסול על אף שהתקדש.","ודנים עוד בשאלה זו. \u0003והרי\u0004 אפשר להביא ראיה מדין ה\u0003מקדיש תמימין לבדק הבית, דאמר רחמנא\u0004 \u0005[ש\u0006כן \u0005אמרה התורה]\u0006 ברשימת בעלי מומים והקדשתם:"],["\"ושור ושה שרוע וקלוט \u0003נדבה תעשה אותו\u0004 ולנדר לא ירצה\" (ויקרא כב, כג). וכתוב \u0003זה\u0004 (\"נדבה\") לכאורה אין מובנו קדשי מזבח, שהרי בעלי מומים הם ואינם יכולים לעלות על המזבח כקרבן, אלא \u0003קדשי בדק הבית.\u0004 ומכלל האמור בכתוב \"תעשה אותו\" למדנו כי דווקא בעלי מומים מקדיש אדם לבדק הבית, ואינו מקדיש תמימים. ומכאן שאסור מן התורה להקדיש תמימים לבדק הבית, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדיש תמימין לבדק הבית, אף על פי שהוא\u0004 עבר \u0003בלא תעשה\u0004 — \u0003מה שעשה עשוי,\u0004 שהתקדשו בכך. והרי זו איפוא ראיה לשיטת אביי הסבור שהועילו מעשיו, ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבא\u0004 הסבור שאין מעשיו מועילים!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא\u0004 בתשובה לכך: אין להביא ראיה מדין זה, שכן שם יש לימוד מיוחד שהועילו מעשיו של המקדיש תמימים לבדק הבית, שהרי \u0003מ\u0004אותו \u0003מקום\u0004 (פסוק) שלמדנו \u0003שנתרבו בעלי מומין לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח\u0004 (שאם עבר והקדיש בעלי מומים למזבח, הרי אלו מוקדשים) למדנו גם ש\u0003נתרבו תמימין לבדק הבית,\u0004 שאם עבר והקדיש תמימים לבדק הבית. וכיון ששתי הלכות אלה נלמדות מפסוק אחד, אף עניינן שווה: שמה שעשה עשוי, וכשם שהמקדיש בעלי מומים למזבח חלה עליהם קדושה, אף המקדיש תמימים לבדק הבית חלה עליהם קדושה.","ועוד באותה שאלה. \u0003והרי\u0004 אפשר להביא ראיה מדין \u0003גזל, דרחמנא אמר\u0004 \u0005[שאמרה התורה]\u0006 \u0003\"לא תגזל\"\u0004 (ויקרא יט, יג), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 בדין \u0003הגוזל עצים ועשאן כלים,\u0004 או שגזל גיזות \u0003צמר ועשאן בגדים\u0004 — \u0003משלם\u0004 לנגזל \u0003כ\u0004פי שהיה הדבר הנגזל שווה ב\u0003שעת הגזילה,\u0004 ואינו צריך להחזיר לבעלים את הכלים או את הבגדים שעשה מגזילתו, שעל ידי השינוי שעשה בהם קנאם. והרי זו איפוא ראיה לשיטת אביי שהעובר על איסור התורה (גזל) הועילו מעשיו, והם נשארים בידי הגזלן, ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רבא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא\u0004 בתשובה לכך: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"והשיב את הגזילה \u0003אשר גזל\"\u0004 (ויקרא ה, כג) — וכוונת הדברים: \u0003כמה שגזל,\u0004 לומר שאם נשתנתה הגזילה יכול הוא להשיב כעין הדבר שגזל (\"כמה שגזל\", וראה גרסות) והגזילה עצמה תישאר בידו, והרי זה לימוד מיוחד שהועיל מעשהו.","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 שבכל איסורי תורה העובר עליהם הועילו מעשיו, מה מלמדנו כתוב זה? ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"אשר גזל\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמדנו כי דווקא אם נשבע לשקר \u0003על גזילו שלו\u0004 הריהו \u0003מוסיף חומש,\u0004 ואולם \u0003על גזילו של אביו,\u0004 שירש מאביו חפץ שנטען אודותיו שהאב גזלו — \u0003אינו מוסיף חומש,\u0004 אפילו אם נשבע עליו לשקר.","ועוד באותה שאלה. אפשר להביא ראיה מדין \u0003משכון, דרחמנא אמר\u0004 \u0005[ש\u0006כן \u0005אמרה התורה]\u0006 \"כי תשה ברעך משאת מאומה \u0003לא תבא אל ביתו לעבט עבטו\"\u0004 (דברים כד, י), שאסור למלוה לבוא אל בית הלווה למשכנו על חובו שהגיע זמן פרעונו ולא נפרע, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה] שאם עבר ומשכן המלוה את הלווה לאחר שהגיע זמן פרעונו ולא נפרע, בשני כלים — הריהו נוטל כלי אחד, ומחזיר כלי אחד ללווה בשעה שהוא נזקק לו. וכגון אם משכן מהלווה כר ומחרישה — \u0003מחזיר את הכר ב\u0004כל \u0003לילה\u0004 (בערב), כדי שיוכל הלווה העני לישון, ומשאיר בידו את המחרישה בלילה. \u0003ו\u0004מחזיר ללווה \u0003את המחרישה ביום\u0004 (בבוקר), כדי שיוכל לעבוד בה, ומחזיק בידו את הכר. והרי זו איפוא ראיה לשיטת אביי, שהרי אף שהמלווה עבר על דין התורה, ונכנס לביתו של הלווה ומשכנו שלא ברשות בית דין, אין הוא מחזיר ללווה אלא את הכלי הנצרך לו, והכלי האחר נשאר כקנוי בידו. והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רבא\u0004 הסבור שלא הועילו מעשיו של העובר על איסור תורה!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא\u0004 בתשובה לכך: אין להביא ראיה מדין זה כי \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 בדינו של הממשכן שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ואם איש עני הוא לא תשכב בעבוטו. \u0003השב תשיב\u0004 לו את העבוט כבוא השמש....\" (דברים כד, י), שאסור למלוה לבוא אל בית הלווה למשכנו על חובו שהגיע זמן פרעונו ולא נ יב—יג). ולמדנו מכפל לשון זו \"השב תשיב\" — שישיב ויחזור וישיב, וכגון שישיב את הכר בלילה ואת המחרישה ביום, וחוזר חלילה. משמע שנשאר בידיו חפץ אחד.","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 שבכל איסורי תורה העובר עליהם הועילו מעשיו, מה מלמדנו כתוב זה? ומשיבים: \u0003אי לאו דאמר רחמנא\u0004 \u0005[אלמלא שאמרה התורה]\u0006 \u0003\"השב תשיב\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאם נכנס המלוה לביתו של הלווה ומשכנו, הרי \u0003איסורא עבד\u0004 \u0005[איסור עשה],\u0006 אך עתה, שהמשכון בידו, תלוי הדבר בו: \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003ניהדר\u0004 \u0005[יחזיר],\u0006 את המשכון ללווה, \u0003ואי בעי\u0004 \u0005[ואם רוצה]\u0006 — \u0003לא נהדר\u0004 \u0005[לא יחזיר].\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב \"השב תשיב\" — שחייב הוא להחזיר. \u0003(חסר לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006\u0003)\u0004 וראה בגרסות.","ודנים עוד באותה שאלה, \u0003והרי\u0004 אפשר להביא ראיה לענין זה מדין \u0003פאה\u0004 בשדה, \u0003דרחמנא אמר\u0004 \u0005[ש\u0006כן \u0005אמרה התורה]\u0006 \"ובקוצרכם את קציר ארצכם \u0003לא תכלה פאת שדך בקצרך\"\u0004 (ויקרא כג, כב), \u0003ותנן\u0004 \u0005[ושנינו]:\u0006 \u0003מצות פאה,\u0004 הריהי חובת בעל השדה \u0003להפריש\u0004 (להקצות) \u0003מן ה\u0004תבואה בהיותה ב\u0003קמה\u0004 (כלומר, כשלא נקצרה עדיין). \u0003לא הפריש מן הקמה\u0004 — \u0003יפריש מן העמרים\u0004 (קבוצת שבלים שנקצרו ונאגדו יחד). \u0003לא הפריש מן העמרים —\u0004 \u0003יפריש מן הכרי\u0004 (ערימת תבואה) \u0003עד שלא מירחו\u0004 (סידר ויישר אותו).","אבל אחר ש\u0003מירחו\u0004 ובכך חלה עליו מאז חובת מעשרות — \u0003מעשרו\u0004 את התבואה תחילה \u0003ו\u0004אחר כך \u0003נותן לו\u0004 לעני תבואה קצורה כשיעור הפאה, שאם לא יקדים ויביא את המעשרות על הכל, יפסיד העני, שיצטרך הוא עצמו להפריש מעשר ממה שקיבל. \u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמרו: אף\u0004 אם לא הפריש פאה בכל השלבים הללו, ועשה עיסה, הריהו \u0003מפריש מן העיסה\u0004 ונותן לעני. הרי זו איפוא ראיה לרבא (שהרי עבר על דין התורה, ולא הפריש הפאה מן הקמה וקצרה, לא הועילו מעשיו ועדיין חייב הוא בהפרשת פאה), ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003אביי\u0004 הסבור שהועילו מעשיו של העובר על איסור התורה!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך אביי\u0004 בתשובה: \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הדין \u0005שם]\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין הפאה \"ובקוצרכם את קציר ארצכם לא תכלה פאת שדך לקצור... לעני ולגר תעזוב אותם\" (ויקרא יט, ט—י). וחזר ואמר \"ובקוצרכם את קציר ארצכם לא תכלה פאת שדך בקוצרך... לעני ולגר תעזוב אותם\" (ויקרא כג, כב). ומעתה יש לומר כי כפל לשון זו \u0003\"תעזב\" \"תעזב\"\u0004 שהיא \u0003יתירא\u0004 \u0005[יתירה]\u0006 באה ללמדנו שיש עזיבה נוספת של פאה שאם לא עזב פאה בהיות התבואה בקמה, יתן כשיעורה הראוי בהיותה בעומרים, וכן הלאה.","ושואלים: \u0003ורבא\u0004 מה הוא למד מ\"תעזוב\" \"תעזוב\"? ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]:\u0006 \u0003לך\u0004 רבא כי מ\"תעזוב\" \"תעזוב\" למדים ש\u0003יש לך\u0004 מצות \u0003עזיבה אחרת שכזו, ואיזו\u0004 — \u0003זה המפקיר כרמו.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003המפקיר\u0004 את \u0003כרמו,\u0004 וההפקר פטור ממעשרות וממתנות עניים, \u0003והשכים לשחר\u0004 וזכה בו לפני שזכה בו אחר, \u0003ובצרו\u0004 — \u0003חייב בפרט ועוללות בשכחה ובפאה, ופטור\u0004 הוא \u0003מן המעשר\u0004 כיון שזכה בו מן ההפקר הפטור מן המעשר. וחובת נתינה זו נלמדת מלשון \"תעזוב\" יתירה זו, שמתנות עניים צריך לתת מכל מקום.","ולאחר שהובאו, לענין מחלוקתם של אביי ורבא בדין, כל הראיות הללו ונדחו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: והשתא דשנינן\u0004 \u0005[ועתה, שתירצנו]\u0006 את \u0003כל הני שינויי\u0004 \u0005[אלה התירוצים,\u0006 הדחיות\u0005],\u0006 שכל אחד מן המקרים שהובאו לראיה לאחד הצדדים נדחה כמקרה מיוחד שבו אין אביי ורבא חלוקים, ויש לשאול: \u0003אביי ורבא במאי פליגי\u0004 \u0005[במה\u0006 באיזה מקרה \u0005חולקים]?\u0006","השיבו רב אשי: \u0003ברבית קצוצה\u0004 (שקצץ, קצב המלוה עם הלווה בזמן ההלוואה), שנאסרה מן התורה, \u0003קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003וכ\u0004מחלוקת שנחלקו בה \u0003ר' אלעזר\u0004 ור' יוחנן. שכן \u0003אמר ר' אלעזר: רבית קצוצה\u0004 — \u0003יוצאה בדיינין,\u0004 שמי שנתן ריבית כזו, יכול לתבוע בבית הדין ולקבל בחזרה את הריבית ששילם."],["ואילו \u0003אבק רבית \u0004שאיסורה רק מדברי חכמים — \u0003אינה יוצאה בדיינין. ו\u0004אילו \u0003ר' יוחנן אמר: אפילו רבית קצוצה אינה יוצאה בדיינין. \u0004","ובדין זה של רבית קצוצה, שנחלקו בו ר' אלעזר ור' יוחנן, נחלקים אביי ורבא. שלשיטת אביי שמועילים מעשיו של העובר על איסור תורה, אף ברבית קצוצה הועילו מעשיו של המלוה שגבה אותה מהלוה למרות שעבר על איסור התורה, ואין הריבית יוצאת ממנו בבית דין. ולשיטת רבא שאין מועילים מעשיו, אף המלוה בריבית, לא הועילו מעשיו, ויוצאת ממנו הריבית שגבה בבית דין. \u0003אמר ליה \u0004\u0005[לו] \u0006רב אחא בנו של רבא לרב אשי: אין להעמיד את מחלוקתם של אביי ורבא בדין זה, שכן האם \u0003התם בסברא פליגי \u0004\u0005[שם, \u0006במחלוקת ר' אלעזר ור' יוחנן, \u0005בסברה \u0006הם \u0005חולקים]? \u0006והרי \u0003התם בקראי פליגי \u0004\u0005[שם ב\u0006דרשות העולות מ\u0005פסוקים \u0006הם \u0005חלוקים]! \u0006שכן \u0003אמר ר' יצחק: מאי טעמא \u0004\u0005[מה הטעם] \u0006של \u0003ר' יוחנן \u0004— שכן מה ש\u0003אמר קרא \u0004\u0005[הכתוב] \u0006\u0003\"בנשך נתן ותרבית לקח וחי לא יחיה \u0004את כל התועבות האלה עשה מות יומת דמיו בו יהיה\" (יחזקאל יח, יג), מלמדנו: עונש \u0003ל\u0004ענין ה\u0003חיים ניתן \u0004למלוה בריבית, שכן הוא נענש במיתה בידי שמים, \u0003ולא \u0004להישבון, שאין בית דין יכולים לחייבו להשיב את הכסף.","\u0003רב אחא בר אדא אמר \u0004ראיה אחרת לשיטת ר' יוחנן, \u0003מהכא \u0004\u0005[מכאן]: \u0006שכן אמר הכתוב באיסור הריבית \"אל תקח ממנו נשך ותרבית \u0003ויראת מאלהיך \u0004וחי אחיך עמך. את כספך לא תתן לו בנשך ובמרבית לא תתן אכלך. \u0003אני ה' \u0004אלהיכם\" (ויקרא כה, לו-לח), וללמדנו בא הכתוב כי \u0003למורא נתתיו, \u0004שהעובר על כך פרק מעליו מורא שמים, \u0003ולא להישבון \u0004בידי אדם.","\u0003רבא אמר \u0004ראיה אחרת לשיטת ר' יוחנן שאין ריבית קצוצה יוצאת בבית דין, \u0003מהכא \u0004\u0005[מכאן], \u0006מן האמור: \"בנשך נתן ותרבית לקח וחי לא יחיה את כל \u0003התועבות האל עשׂה מות יומת דמיו בו יהיה\" \u0004(יחזקאל שם), ונאמר לפני כן \u0003\"והוליד בן פריץ שפך דם\" \u0004(שם י), \u0003הוקשו \u0004(הושוו) בפסוקים אלה \u0003מלוי רבית לשופכי דמים. \u0004ומעתה נאמר: \u0003מה שופכי דמים \u0004— \u0003לא ניתנו להישבון, \u0004שהרי אי אפשר להשיב את הנהרג לחיים, \u0003אף מלוי רבית \u0004שהם כשופכי דם העני — \u0003לא ניתנו להישבון. \u0004","\u0003ו\u0004בענין דרשת הכתובים לשיטת ר' אלעזר שיוצאת הריבית הקצוצה בדיינים, \u0003אמר רב נחמן בר יצחק: מאי טעמא \u0004\u0005[מה הטעם] \u0006של \u0003ר' אלעזר? \u0004— שכן \u0003אמר קרא \u0004\u0005[הכתוב] \u0006באיסור הריבית: \"אל תקח מאתו נשך ותרבית ויראת מאלהיך \u0003וחי אחיך עמך\" \u0004(ויקרא כה, לו) — \u0003אהדר ליה, כי היכי דניחי \u0004\u0005[החזר לו, היאך \u0006כדי, \u0005שיחיה] \u0006\u0003עמך.\u0004","\u0003ואלא \u0004מעתה שהסקנו שאף בענין ריבית קצוצה אין ראיה שנחלקו בו אביי ורבא, יש לחזור ולשאול: \u0003במאי קמיפלגי \u0004\u0005[במה, \u0006באיזה מקרה \u0005הם חלוקים] \u0006\u0003אביי ורבא? \u0004ומשיבים: אף שלא נתפרש באופן פרטי מקרה מסויים בו נחלקו אביי ורבא הלכה למעשה, יש לומר שחלוקים הם בשאלה העקרונית האם \u0003שינוי \u0004ששינה אדם ועבר ועשה את שאסור לעשות מן התורה, \u0003קונה \u0004(פועל, חל). שלשיטת אביי הועילו מעשיו, ולשיטת רבא — לא הועילו מעשיו.","\u0003לישנא אחרינא \u0004\u0005[לשון אחרת] \u0006בתשובה לשאלה במה נחלקו אביי ורבא — \u0003בהני שינויי דשנינן \u0004\u0005[בתירוצים האלו שתירצנו]. \u0006שכך השיב לו רב אשי לרב אחא בנו של רבא בתשובה לשאלתו במה נחלקו אביי ורבא — \u0003ב\u0004דינה של \u0003רבית קצוצה, \u0004אם היא יוצאת בבית דין. ובזה נחלקו: \u0003ל\u0004דעת \u0003אביי \u0004— המלוה \u0003לא מהדר \u0004\u0005[אינו \u0006מתחייב בבית דין \u0005להחזיר] \u0006את ה\u0003רבית \u0004שלקח, שכן הועילו מעשיו, אף שעבר על איסור התורה. ואילו \u0003ל\u0004דעת \u0003רבא \u0004— לא הועילו מעשיו של המלוה בריבית, כיון שעבר על איסור תורה, ולכן \u0003מהדר \u0004\u0005[מחזיר] \u0006את ה\u0003רבית \u0004שלקח.","ושואלים: \u0003והא \u0004\u0005[והרי] \u0006\u0003אביי נמי סבר מפקינן \u0004\u0005[גם כן סבור \u0006ש\u0005מוציאים אנו] \u0006מהמלוה את ה\u0003ריבית \u0004ה\u0003קצוצה בדיינין \u0004(על ידי בית דין)! שכן \u0003אמר אביי: הדין דמסיק בחבריה \u0004\u0005[זה שנושה \u0006כספים של ריבית \u0005בחבירו \u0006שלווה ממנו\u0005] \u0006ותובע ממנו סכום של \u0003ארבע זוזי בריביתא \u0004\u0005[ארבעה זוזים בריבית], \u0006\u0003ויהביה ליה \u0004\u0005[ונתן לו] \u0006הלווה שהוא בעל חנות \u0003למלוה בחנותיה \u0004\u0005[בחנותו] \u0006בפרעון חובו \u0003גלימא דשוי חמשא \u0004\u0005[גלימה ששווה חמישה \u0006זוזים\u0005] \u0006כאילו היא שווה \u0003ארבעה \u0004זוזים — \u0003כי מפקינן מיניה \u0004\u0005[כאשר מוציאים אנו ממנו, \u0006מן המלוה\u0005] \u0006את הריבית — \u0003ארבעה \u0004זוזים \u0003מפקינן מיניה \u0004\u0005מוציאים אנו ממנו], \u0006\u0003ו\u0004אולם \u0003האי זוזא \u0004\u0005[זוז זה], \u0006החמישי שבשוויה של הגלימה שניתנה לו — אין אנו מוציאים ממנו, כי \u0003במתנה הוא דיהב ליה \u0004\u0005[שנתן לו] \u0006אותו, ולא כריבית. \u0003ורבא אמר: חמשא מפקינן מיניה \u0004\u0005[חמישה \u0006זוזים \u0005מוציאים אנו ממנו] \u0006כמלוא שוויה של הגלימה שניתנה לו, \u0003מאי טעמא \u0004\u0005[מה הטעם] \u0006— כל הגלימה \u0003כולה בתורת ריביתא קאתי לידיה \u0004\u0005[ריבית באה לידו]. \u0006הרי שאי אפשר לומר שאביי ורבא חלוקים בדין ריבית קצוצה, שהרי אף אביי סבור שריבית קצוצה יוצאת בבית דין!","\u0003אלא, \u0004יש לחזור מתירוץ זה, ולומר (כפי שנאמר למעלה) \u0003כי קא מיפלגי \u0004\u0005[כאשר נחלקו] \u0006\u0003אביי ורבא \u0004— הרי זה \u0003ב\u0004שאלה העקרונית האם \u0003שינוי קונה, \u0004וכמוסבר למעלה.","למעלה הובא עניינו של המקדיש בעלי מומים למזבח, ודנים עוד בדין זה. \u0003תנו רבנן \u0004\u0005[שנו חכמים]: \u0006נאמר בפרשת בעלי המומים הפסולים להקרבה (ויקרא כב, יז-כו) \u0003\"כל אשר בו מום לא תקריבו \u0004כי לא לרצון יהיה לכם\" (שם כ). ודנים בדבר: \u0003מה תלמוד לומר \u0004(בא ללמדנו) כתוב זה (\"לא תקריבו\")? \u0003אם \u0004להעמיד \u0003ב\u0004איסור \u0003\"לא תשחטו\" \u0004את בעלי המום שהוקדשו להקרבה על המזבח — \u0003הרי כבר אמור \u0004הדבר \u0003למטה \u0004(בהמשך) הפרשה, כאשר יתבאר להלן! \u0003אלא מה תלמוד לומר \"בל תקריבו\"? \u0004— \u0003בל תקדישו \u0004את בעלי המומים לקרבן. \u0003מכאן אמרו \u0004חכמים: \u0003המקדיש בעלי מומין לגבי מזבח, \u0004ולאחר מכן העלם על גבי המזבח כקרבן עולה — הרי זה \u0003עובר משום חמשה שמות \u0004(איסורים נפרדים), והריהם:","\u0003משום \"בל תקריבו\" \u0004שמשמעו הוא \"בל תקדישו אותו להקרבה\", ומשום \u0003\"בל תשחטו\", ומשום \"בל תזרקו \u0004את דמו על המזבח\", \u0003ומשום \"בל תקטירו כולו \u0004על המזבח\", שאם מעלה עולה למזבח הריהו עובר על כך. \u0003ומשום \"בל תקטירו מקצתו\", \u0004בשאר קרבנות שמעלה רק מקצתם (אימורים) למזבח. \u0003משום \u0004(בשם) \u0003ר' יוסי בר' יהודה אמרו \u0004חכמים שעובר על איסור נוסף: \u0003אף \u0004על \u0003קבלת הדם \u0004של קרבן זה.","ומעתה באים להסביר ברייתא זו. \u0003אמר מר \u0004\u0005[החכם] \u0006בברייתא: מה בא הכתוב \"לא תקריבו\" ללמדנו, ש\u0003אם \u0004בא ללמד את איסור \u0003\"בל תשחטו\" \u0004את בעל המום לקרבן — \u0003הרי \u0004דבר זה כבר \u0003אמור למטה \u0004(בהמשך). ומבררים: \u0003היכן \u0004איסור זה של שחיטה \u0003אמור \u0004בהמשך? — דתניא \u0005[ש\u0006כן \u0005שנויה \u0006ברייתא\u0005], \u0006בפרשת בעלי מומים לקרבן נאמר לשון איסור זה שלש פעמים: \"כל אשר בו מום לא תקריבו...\" (ויקרא כב, כ), \"עורת או שבור... לא תקריבו\" (שם כב), \"ומעוך וכתות... לא תקריבו\" (שם כד). ומאחר שלשון \"לא תקריבו\" היא לשון כללית שיש במשמעה כמה דברים, יש לשאול: \"לא תקריבו\" האמור בפעם השניה בפרשה, ברשימת המומים \u0003\"עורת או שבור או חרוץ או יבלת \u0004או גרב או ילפת \u0003לא תקריבו \u0004אלה לה' ואשה לא תתנו מהם על המזבח לה'\" (שם כב) \u0003מה תלמוד לומר \u0004(בא ללמדנו), מה משמעה? — \u0003אם \u0004להשמיענו איסור \u0003\"בל תקדישו\", \u0004שאסור להקדיש למזבח בעלי מומים — \u0003הרי כבר אמור \u0004הדבר \u0003למעלה \u0004(מקודם), בכתוב \"לא תקריבו\" (פסוק כ)! \u0003אלא מה תלמוד לומר \"בל תקריבו\" \u0004— \u0003בל תשחטו, \u0004שאסור לשחוט בעלי מומים אלו לשם קרבן.","ועוד נאמר בכתוב זה \u0003\"ואשה לא תתנו מהם\"\u0004 — \u0003אלו אשים,\u0004 שנאסרו איבריהם של קרבנות שיש בהם מום להיות מוקטרים על אש המזבח. ועדיין יש לשאול: \u0003אין לי\u0004 לכאורה מכתוב זה לאסור \u0003אלא\u0004 הקטרת \u0003כולן,\u0004 איסור הקטרת אף \u0003מקצתן מנין\u0004 לנו? — \u0003תלמוד לומר:\u0004 \"לא תקריבו \u0003מהם\",\u0004 שאף חלק מהם אין להקריב.","ועדיין יש לשאול: אין לי מכתוב זה אלא רק איסור ההקטרה של איברי הקרבן שהוא בעל מום, אבל איסור \u0003זריקת דמים\u0004 על המזבח של בעלי מומים \u0003מנין\u0004 לנו? — \u0003תלמוד לומר:\u0004 \"לא תתנו מהם \u0003על המזבח\"\u0004 — לאסור כל דרכי הנתינה של בעל המום על המזבח, בין איבריו ובין דמו. והאמור בסוף הפסוק \"לא תתנו מהם על המזבח \u0003לה'\"\u0004(ויקרא פסוק כב) מלמדנו — \u0003לרבות\u0004 לאיסור אף את המקדיש בעל מום ל\u0003שעיר המשתלח\u0004 ביום הכיפורים.","ושואלים על לימוד זה: \u0003ו\u0004האם שימוש הלשון \u0003\"לה'\" לרבות הוא\u0004 בא? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא], נאמר בעניינו של המקריב קדשים מחוץ למקדש: \"ואל פתח אהל מועד לא הביאו להקריב קרבן לה'\" (ויקרא יז,ד), ומן המילים \"להקריב קרבן לה'\" דרשו חכמים שבא למעט את השוחט חולין בפנים (המקדש), שאינו חייב משום שחיטת חוץ. ודנים: \u0003אי\u0004 \u0005[או]\u0006 שמא מן המלה \u0003\"קרבן\"\u0004 \u0003שומע אני\u0004 שדין שחיטת חוץ אמור \u0003אף\u0004 ב\u0003קדשי בדק הבית, ש\u0004הרי גם הם \u0003נקראו \"קרבן\", כענין שנאמר\u0004 בשלל מלחמת מדין \u0003\"ונקרב את קרבן ה'\u0004 איש אשר מצא כלי זהב אצעדה וצמיד טבעת עגיל וכומז\" (במדבר לא, נ), והם הרי בודאי קדשי בדק הבית, וקורא אותם הכתוב \"קרבן\"!","לכך \u0003תלמוד לומר\u0004 (מלמדנו) הכתוב בדין הקרבת חוץ: \u0003\"ואל פתח אהל מועד\u0004 לא הביאו\" — רק הקרבן \u0003הראוי ל\u0004בוא אל \u0003פתח אהל מועד\u0004 (להקריבו על המזבח) הוא ש\u0003חייבין עליו משום שוחטי חוץ.\u0004 ואילו הקרבן \u0003שאין ראוי לפתח אהל מועד,\u0004 כגון קדשי בדק הבית — \u0003אין חייבין עליו משום שוחטי חוץ.\u0004","ודנים עוד בדבר: \u0003אוציא אני\u0004 מכלל החייבים על שחיטת חוץ \u0003את אלו\u0004 (קדשי בדק הבית), \u0003ולא אוציא פרת חטאת\u0004 (פרה אדומה) \u0003ושעיר המשתלח,\u0004 שהשוחט את פרת החטאת מחוץ למקום הראוי לשחיטתה, וכן השוחט את השעיר המשתלח מחוץ למקדש, יתחייב, משום \u0003שהן ראויין לפתח אהל מועד\u0004 — \u0003תלמוד לומר\u0004 \"להקריב קרבן \u0003לה'\"\u0004— אין חייבים בהקרבת חוץ אלא ב\u0003מי שמיוחדין\u0004 אך ורק להקרבה \u0003לה', יצאו אלו\u0004 (פרה אדומה ושעיר המשתלח) \u0003שאין מיוחדין\u0004 להקרבה \u0003לה'.\u0004 הרי שמהמלה \"לה'\" דורשים למעט ולא לרבות!","\u0003אמר רבא\u0004 בתשובה: דרשת המלה \"לה'\", אם לרבות או למעט, אינו קבוע, ומשתנה מענין לענין. \u0003התם מעניינא דקרא\u0004 \u0005[שם,\u0006 בדין הקרבת חוץ, \u0005מענין הכתוב],\u0006 כיון שהכתוב הקודם \u0003\"ואל פתח\u0004 אהל מועד\" בא \u0003לרבות\u0004 (שכל הראויים לבוא אל פתח אהל מועד הריהם בכלל איסור הקרבת חוץ), בא הכתוב שאחריו \u0003\"לה'\"\u0004— \u0003להוציא\u0004 (למעט) מכלל אלה שהתרבו. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בעניינם של הקרבנות בעלי המום, כיון שהכתוב \"ו \u0003אשה\u0004 לא תתנו מהם על המזבח\" בא \u0003להוציא\u0004 (למעט), ומשמעו — שרק דבר העולה על אש המזבח חייב עליו אם הקדישו כשהוא בעל מום לקרבן, ואין חייב המקדיש בעל מום דבר שאינו עולה לאש המזבח. לכך בא הכתוב אחריו \u0003\"לה'\"\u0004— \u0003לרבות\u0004 באיסור אף את המקדיש בעל מום לשעיר המשתלח.","ומרחיבים דברים בענין זה. שנינו שבאה המלה \"לה'\" שבפרשת איסור הקדשת בעלי מום להקרבה להשמיענו שאף שעיר המשתלח בכלל זה. ודנים בדבר: מעתה אפשר לדייק ולומר: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאסור להקדיש בעל מום לשעיר המשתלח, הוא משום ש\u0003כתב קרא\u0004 \u0005[המקרא]\u0006 \u0003\"לה'\"\u0004ו\u0003הוא\u0004 המלמדנו \u0003דלא מייתי\u0004 \u0005[שאין מביאים]\u0006 בעל מום ל\u0003שעיר המשתלח, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא רבי קרא\u0004 \u0005[לא היה מרבה הכתוב]\u0006 במלה זו \u0003\"לה'\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003שעיר המשתלח בעל מום\u0004 — \u0003שפיר דמי\u0004 \u0005[נחשב ראוי]\u0006 להבאה. ומעתה \u0003מכדי\u0004 \u0005[והרי],\u0006 \u0003אין הגורל קבוע\u0004 (קובע) מי מבין שני השעירים העומדים לפני הכהן ישמש לה' (לעבודת יום הכיפורים במקדש) ומי ישולח לעזאזל, ומאחר וכך הוא אין לשעירים להיות \u0003אלא בדבר הראוי\u0004 להקרבה בבית המקדש, ולפיכך חייבים שניהם להיות תמימים, ומדוע אם כן יש צורך בלימוד מן הכתוב \"לה'\"?","\u0003אמר רב יוסף\u0004 בתשובה לשאלה זו: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003חנן המצרי היא,\u0004 ש\u0003אמר\u0004 ש\u0003אפילו\u0004 אם כבר נשחט שעיר יום הכיפורים, וה\u0003דם\u0004 שלו כבר נמצא \u0003ב\u0004תוך ה\u0003כוס,\u0004 ומת בן זוגו (השעיר המשתלח לעזאזל), ובאותה שעה לא ניתן לזרוק את הדם — אין הדם נדחה בכך, אלא \u0003מביא חבירו\u0004 (שעיר אחר) \u0003ומזווג\u0004 (ומצרף) ליה \u0005[לו]\u0006 שישמש כשעיר המשתלח לעזאזל. הרי שלדעת חנן המצרי, יש שעיר הנשלח לעזאזל בלא הגרלה, והיה מקום לחשוב ששעיר שכזה, יהיה מותר אף שהוא בעל מום.","ודוחים: אף לשיטתו זו של חנן המצרי, אין לומר כן, שהרי \u0003נהי דשמעת ליה\u0004 \u0005[\u0006אם \u0005אכן שמעת אותו]\u0006 את \u0003חנן המצרי\u0004 — רק ש\u0003לא הוי\u0004 \u0005[נהיה]\u0006 \u0003דיחוי,\u0004 שאין הדם של השעיר לה' נדחה מלשמש לעבודה אם מת השעיר לעזאזל הראשון, והובא אחר תחתיו שמעת אותו שאומר. אבל ש\u0003לא צריך הגרלה\u0004 שתיעשה שוב, \u0003מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]?\u0006 \u0003דילמא מייתי\u0004 \u0005[שמא\u0006 לדעת חנן המצרי \u0005מביא]\u0006 שני שעירים, \u0003ומגריל\u0004 על שניהם מי מהם יחליף את השעיר המת. ואם כן חוזרת איפוא השאלה מדוע יש צורך בלימוד מהכתוב \"לה'\".","\u0003אלא אמר רב יוסף: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]? — כשיטת\u0006 \u0003ר' שמעון היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מת אחד מהן\u0004 משני השעירים — \u0003מביא חבירו\u0004 במקומו \u0003בלא הגרלה,\u0004 אלו \u0003דברי ר' שמעון.\u0004","\u0003רבא אמר\u0004 תירוץ אחר בהסבר הברייתא: \u0003לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 דרשת המלה \"לה'\" לענין הקדשת בעל מום לשעיר המשתלח אלא למקרה \u0003כגון שהומם\u0004 (שנפל מום) בשעיר המשתלח \u0003בו ביום\u0004 (ביום הכיפורים), לאחר שהוגרלו שני השעירים, לה' ולעזאזל, ועמד הכהן \u0003וחיללו על חבירו,\u0004 על שעיר אחר שאף הוא בעל מום, ואין בחילול זה הגרלה. והשמיענו הכתוב \"לה'\" שאף בכגון זה עבר על איסור הקדשת בעל מום."],["ולכך נצרך כתוב מיוחד להשמיענו שאף זה בכלל איסור הקדשת בעלי מום, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003בשלמא\u0004 \u0005[נוח,\u0006 מובן\u0005]\u0006 דין זה שאין להקדיש בעל מום לשעיר המשתלח, \u0003מעיקרא\u0004 \u0005[בהתחלה],\u0006 רק לפני שהוגרלו שני השעירים, לה' ולעזאזל. שהרי עדיין \u0003לא ידענא אי האי מיקבע\u0004 \u0005[אין אני יודע אם\u0006 שעיר \u0005זה נקבע]\u0006 כשעיר \u0003לשם\u0004 (לה'), או כשעיר המשתלח. וייתכן איפוא שבעל מום זה יקבע לכך. לכן אין להקדיש בעל מום לשעיר המשתלח. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003כיון דאינכר\u0004 \u0005[ש\u0006כבר \u0005ניכר]\u0006 שהשעיר השני הוא ל\u0003שם\u0004 — אפשר היה לומר שהמקדיש בעל מום לשעיר המשתלח, לא עבר בכך, ו\u0003לא לקי\u0004 \u0005[אינו לוקה],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שאין לעשות כן.","ושבים לפירוש הברייתא שהובאה למעלה. \u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 כי \u0003משום\u0004 (בשם) \u0003ר' יוסי בר' יהודה\u0004 אמרו שהמקדיש בעלי מומים להקרבה במזבח, ושחטם, וזרק דמם, והקריבם על המזבח — הרי בנוסף לחמשה איסורים שמנו בו חכמים עובר הוא \u0003אף\u0004 באיסור שישי, משום \u0003קבלת הדם.\u0004 ומבארים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לשיטה זו של \u0003ר' יוסי בר' יהודה\u0004 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפירוט בעלי המומים האסורים להקרבה \u0003\"ומעוך וכתות ונתוק וכרות\u0004 לא תקריבו לה'\" (ויקרא כב, כד). והלשון \"לא תקריבו\" האמורה בפסוק זה, לכאורה היא מיותרת, שהרי כבר נאמר למעלה (\"כל אשר בו מום לא תקריבו\", ויקרא כ; \"עורת או שבור... לא תקריבו\", ויקרא כב) אלא ללמד באה: \u0003זו קבלת הדם\u0004 של קרבן בעל מום שאף היא אסורה מן התורה וזה \u0003שאמר ר' יוסי בר' יהודה\u0004 בה.","ושואלים: \u0003ולתנא קמא\u0004 \u0005[הראשון],\u0006 הסבור שהמקדיש בעלי מומים למזבח אינו עובר על אסור בקבלת הדם, \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"לא תקריבו\" למה לי,\u0004 מה מלמדנו? ומשיבים: פסוק זה \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004למד על איסור \u0003זריקת דמים\u0004 על המזבח שעובר עליו מקדיש זה והוא מן האיסורים שמנה תנא קמא. ושואלים: \u0003והא נפקא ליה\u0004 \u0005[והרי יוצא לו,\u0006 נלמד דבר זה\u0005]\u0006 \u0003מ\u0004הכתוב \"...ואשה לא תתנו מהם \u0003על המזבח\"\u0004 (ויקרא כ״ב:כ״ב)! ומשיבים: אין התנא הראשון לומד איסור זה מהכתוב \"על המזבח\", כי \u0003אורחיה דקרא דמשתעי הכי\u0004 \u0005[דרכו של הכתוב שמדבר כך],\u0006 ואין זה בא ללמד דבר.","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יוסי בר' יהודה,\u0004 הסבור כי מ\"לא תקריבו\" למדים על קבלת הדם, ומשמע שלדעתו זריקת הדם נלמדת מהכתוב \"על המזבח\", \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר כי \u0003אורחיה דקרא\u0004 \u0005[דרך הכתוב]\u0006 \u0003הוא,\u0004 ואין ללמוד ממנו! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן, כך\u0006 הוא \u0005גם כן],\u0006 ור' יוסי בר' יהודה אינו לומד דין זריקת הדמים מהכתוב \"על המזבח\" אלא מהכתוב \"לא תקריבו\" שבפסוק כד בפרשה זו. ומקשים: \u0003אלא\u0004 אם מ\"לא תקריבו\" הוא למד לזריקת הדם, איסור \u0003קבלת הדם\u0004 אם כן \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומתרצים: \u0003נפקא ליה מהא\u0004 \u0005[יוצא לו,\u0006 נלמד\u0005]\u0006 הדבר מהכתוב שלאחר מכן באותה פרשה. שמה שנאמר \u0003\"ומיד בן נכר לא תקריבו\"\u0004 (ויקרא כה) — \u0003זו היא קבלת הדם שאמר ר' יוסי בר' יהודה\u0004 שעוברים אף עליה.","וחוזרים ושואלים: \u0003ולתנא קמא\u0004 \u0005[הראשון]\u0006 הסבור שאין עוברים על איסור בקבלת הדם, \u0003האי\u0004 \u0005[\u0006מקרא \u0005זה]\u0006 \"ומיד בן נכר \u0003לא תקריבו\"\u0004 \u0003למה לי?\u0004 ומשיבים: \u0003מיבעי ליה להאי\u0004 \u0005[נצרך לו\u0006 הכתוב \u0005ל\u0006דבר \u0005זה]:\u0006 שאלמלא היה נאמר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ולא נצטוו\u0004 (נאסרו) \u0003בני נח\u0004 בהקרבת קרבנותיהם לה' \u0003אלא על\u0004 קרבן \u0003מחוסר אברים\u0004 (שנחסר ממנו איבר שלם), ולא נאסרו בהקרבת שאר בעלי מומים, אם כן, ינהג בהם דין זה בכל מקום שהם מקריבים, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם זה \u0003במזבח דידהו\u0004 \u0005[שלהם],\u0006 \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם זה \u0003במזבח דידן\u0004 \u0005[שלנו,\u0006 במקדש\u0005],\u0006 לכן הכתוב \"ומיד בן נכר לא תקריבו\" \u0003קא משמע לן\u0004 \u0005[\u0006\u0005משמיע לנו]\u0006 שאף בני נח אינם מביאים בעלי מומים למקדש.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בהסבר שיטות ר' יוסי בר' יהודה וחכמים. שנינו ש\u0003ר' יוסי בר' יהודה אומר:\u0004 המקדיש בעלי מומים למזבח הריהו עובר (מלבד החמישה איסורים שמנו חכמים) \u0003אף על קבלת הדם.\u0004 ומבארים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לשיטה זו של ר' יוסי בר' יהודה — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ומעוך וכתות... לא תקריבו\"\u0004 (ויקרא כד) — \u0003זו קבלת הדם. ו\u0004אולם את איסור ה\u0003זריקה\u0004 של הדם על המזבח — \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מ\u0004הכתוב \u0003\"על המזבח\"\u0004 (ויקרא כב).","ושואלים: \u0003ולרבנן\u0004 \u0005[ולחכמים,\u0006 התנא הראשון שבברייתא\u0005]\u0006 החולקים על ר' יוסי בר' יהודה, וסבורים שאין איסור בקבלת הדם, \u0003נמי תיפוק להו\u0004 \u0005[גם כן יצא,\u0006 יילמד \u0005להם]\u0006 דין ה\u0003זריקה מן \"על המזבח\",\u0004 ומשיבים: \u0003הכי נמי\u0004 \u0005[אכן כך\u0006 הוא \u0005גם כן],\u0006 שחכמים לומדים את איסור זריקת הדם מהכתוב \"על המזבח\" \u0003ואלא\u0004 באשר לשאלה: \u0003\"לא תקריבו\"\u0004 האמור ב\u0003מעוך למאי אתא\u0004 \u0005[למה בא,\u0006 מה הוא מלמדנו\u0005]? —\u0006 \u0003מפקינן\u0004 \u0005[מוציאים,\u0006 למדים \u0005אנו]\u0006 ממנו \u0003ל\u0004אסור הקרבת בעלי מומים אף ב\u0003במת יחיד\u0004 (בזמן \"היתר במות\").","ושואלים: \u0003ול\u0004שיטת \u0003ר' יוסי בר' יהודה\u0004 שלמד מכתוב זה איסור קבלת הדם, והרי \u0003האי מיבעי ליה\u0004 \u0005[\u0006כתוב \u0005זה נצרך לו]\u0006 \u0003ל\u0004איסור בעלי מומים ב\u0003במת יחיד?\u0004 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן כך\u0006 הוא \u0005גם כן]\u0006 אף לשיטת ר' יוסי בר' יהודה, ושואלים: \u0003אלא\u0004 אם כן, איסור \"לא \u0003תקריבו\"\u0004 לאסור \u0003קבלה\u0004 של דם בעל מום, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: לדעתו משמעות המילים \"לא תקריבו\" שנאמרו בכתוב \"ו \u0003מיד בן נכר לא תקריבו\"\u0004 (ויקרא פסוק כה) — \u0003זו קבלת הדם.\u0004","וחוזרים ושואלים: \u0003ו\u0004לשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שאין איסור בקבלת הדם, מה מלמדנו כתוב זה? ומשיבים: \u0003אצטריך\u0004 \u0005[נצרך]\u0006 הכתוב, שאלמלא נאמר \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]: הואיל ובני נח אין מצווין\u0006 (אין נאסרים) \u0003אלא על\u0004 קרבן ה\u0003מחוסר אבר\u0004 כאשר הוא קרב \u0003בבמה דלהון\u0004 \u0005[שלהם],\u0006 ובבעל מום שאינו מחוסר אבר הם מותרים, \u0003דלמא אנן נמי נקביל מינהון\u0004 \u0005[שמא אנחנו,\u0006 המקבלים קרבנות בני נח להקרבה במקדש, \u0005גם כן נקבל מהם]\u0006 בעלי מומים שאינם מחוסרי אבר? לכך נאמר \"ומיד בן נכר לא תקריבו את לחם אלהיכם מכל אלה כי משחתם בהם מום בם לא ירצו לכם\", ובהדגשה בכתוב זה \u0003קא משמע לן \"מכל אלה\" דלא מקבלינן\u0004 \u0005[השמיע לנו\u0006 הכתוב \u0005שאין אנו מקבלים]\u0006 מידיהם כלל קרבנות בעלי מום.","ושבים לבירור הברייתא. שנינו בה כי המקדיש בעלי מומים למזבח הריהו עובר בחמישה איסורים, ולדעת ר' יוסי בר' יהודה בשישה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ריש לקיש:\u0004 מכלל הדברים עולה שבכל אופני הקדשת בעלי מומים קיים איסור זה, ואולם יש לשאול, \u0003שמא לא שנינו\u0004 (נאמר דין זה) \u0003אלא ב\u0004בעל חיים שמתחילתו היה \u0003תם\u0004 (ללא מום) \u0003שנעשה\u0004 לאחר מכן \u0003בעל מום ו\u0004עמד זה והקדישו, שהריהו \u0003עובר\u0004 על איסור, שמאחר שהיה מעיקרו תם סבור היה המקדיש שניתן להקריבו. \u0003דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 מדובר אף בבעל חיים שהיה \u0003בעל מום מעיקרא\u0004 \u0005[מתחילה]\u0006 — אין זה מסתבר שייענש המקדיש על כך, שהרי כ\u0003דיקלא בעלמא\u0004 \u0005[דקל סתם]\u0006 \u0003הוא\u0004 זה, ובודאי לא העלה המקדיש על דעתו להקריבו, ומן הסתם הקדישו רק לדמיו, שימכר, והכסף שיתקבל עבורו ישמש לקרבן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר יוסף\u0004 לריש לקיש, בתשובה לשאלתו זו: אין לומר כדבריך, שהמדובר רק בבעל מום שהיה בתחילתו תם, שהרי \u0003\"שרוע וקלוט\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בפרשה\u0004 ברשימת בעלי המומים שאינם קרבים, \u0003והני\u0004 \u0005[ואלו]\u0006 \u0003בעלי מומין מעיקרא נינהו\u0004 \u0005[\u0006ש\u0005מתחילה הם].\u0006 שכן ירך הארוכה מחבירתה (\"שרוע\"), או פרסה מחוברת ואינה סדוקה (\"קלוט\"), הם מומים מלידה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש לר' חייא בר יוסף: \u0003שמא לא שנינו\u0004 (למדנו) מ\"שרוע וקלוט\" שיש איסור אף בהקדשת בעלי מומים מתחילתם \u0003אלא\u0004 רק כאשר מקדיש את בהמת החולין בעלת המום \u0003בתמורה\u0004 לבהמת הקדש, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה להלן במסכתנו\u0005]\u0006 \u0003חומר\u0004 (חומרה) יש \u0003ב\u0004דין ה\u0003תמורה\u0004 יותר \u0003מב\u0004 דין ה\u0003זבח\u0004 (קדשים) — \u0003שכן\u0004 בתמורה \u0003קדושה חלה עליה\u0004 בין על בהמת חולין תמה, ובין \u0003על בעל מום קבוע\u0004 (שאינו עובר). אבל המקדיש בעלי מומים למזבח ישירות שמא אין איסורו אלא במקדיש בעל חיים שהיה בתחילתו תם, ולא במקדיש בעל מום מתחילתו?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 בדחיית דבריו אלה: האם \u0003לא שמיע\u0004 \u0005[לא נשמעת,\u0006 נראית\u0005] לך הא\u0006 \u0005[\u0006דבר \u0005זה]\u0006 ש\u0003אמר ר' ינאי, בחבורה\u0004 (בכנס חכמים) \u0003נמנו\u0004 דעות החכמים השונות \u0003וגמרו\u0004 (וסיכמו) כך: \u0003המקדיש בעל מום ל\u0004הקרבה \u0003גבי\u0004 \u0005[אצל]\u0006 ה\u0003מזבח\u0004 — הרי זה \u0003עובר משום חמשה שמות. ואי\u0004 \u0005[ואם]\u0006 נעמיד את דברי הברייתא כשהקדיש את בעל המום \u0003ב\u0004דרך תמורה, יש להקשות: הרי עצם מעשה ה\u0003תמורה\u0004 הוא \u0003נמי\u0004 \u0005[גם כן],\u0006 איסור, ונמצא איפוא כי \u0003ששה\u0004 איסורים \u0003הוויין\u0004 \u0005[הריהן],\u0006 \u0003דאיכא נמי\u0004 \u0005[ש\u0006הרי \u0005ישנו גם כן]\u0006 ה\u0003לאו\u0004 של \u0003תמורה!\u0004 השיב ריש לקיש: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר, כי מדובר בברייתא \u0003ב\u0004מקדיש \u0003בעל מום מעיקרו,\u0004 אם כן יש לשאול: \u0003אמאי לקי\u0004 \u0005[מדוע לוקה]\u0006 על כך, והרי כ\u0003דיקלא בעלמא\u0004 \u0005[דקל סתם]\u0006 \u0003הוא,\u0004 שכן לא היתה כוונתו מלכתחילה שיוקרב!","אלא \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש בתשובה: עונש המלקות אינו משום שמקדיש דבר שאינו ראוי למזבח, כדקל, אלא מטעם אחר, ואין זה דומה למקדיש דקל, שכן במקדיש \u0003דיקלא\u0004 \u0005[דקל]\u0006 — \u0003לאו זילא מילתא\u0004 \u0005[אין מזולזל הדבר],\u0006 שהרי הדקל מכלל \u0003מין\u0004 ה\u0003עצים הוא,\u0004 עצים קרבים כקרבן על המזבח. ואילו המקדיש בעל חיים שהוא \u0003בעל מום מעיקרא\u0004 \u0005[מתחילה]\u0006 — \u0003זילא מילתא\u0004 \u0005[מזולזל הדבר],\u0006 \u0003כיון\u0004 שרואה אתה \u0003דשביק\u0004 \u0005[שעזב]\u0006 הוא מלהקדיש בעל חיים \u0003תמים, ואקדיש\u0004 \u0005[והקדיש]\u0006 \u0003בעלי מומין.\u0004 ומשום כך, הריהו \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 בעונש על הקדשה זו.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 שדומה המקדיש בעל מום מעיקרו כמקדיש דקל, מכל מקום הקדשת בעל מום מעיקרו \u0003בזיא מילתא\u0004 \u0005[בזוי הדבר],\u0006 משום שהמקדיש \u0003דקל,\u0004 כיון ש\u0003ליכא\u0004 \u0005[אין]\u0006 שייכת הקדשה לקרבן \u0003במינו\u0004 של הדקל — אין בהקדשה זו בזיון, ולכן \u0003לא לקי\u0004 \u0005[אינו לוקה]\u0006 המקדיש על כך, \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 המקדיש \u0003בעל מום, כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003במינו\u0004 בעלי חיים שאין בהם מום, הקרבים על המזבח, ואילו הוא הקדיש דווקא בעל מום — הרי זה ביזוי, ומשום כך \u0003לקי\u0004 \u0005[לוקה]\u0006 על כך.","בעקבות דבריו אלה של ר' יוחנן \u0003אמר רבא: השתא דאמור טעמא\u0004 \u0005[עכשיו שנאמר\u0006 מה \u0005הטעם]\u0006 במקדיש \u0003בעל מום דלקי\u0004 \u0005[שלוקה]\u0006 — \u0003משום דבזיא מילתייהו\u0004 \u0005[שבזויים דבריו],\u0006 אם כן \u0003אפילו למקדיש ליה\u0004 \u0005[אותו,\u0006 את בעל המום\u0005]\u0006 \u0003לדמי נסכים\u0004 (שבכסף שיתקבל במכירתו, ייקנו נסכים) — \u0003נמי לקי\u0004 \u0005[גם כן לוקה],\u0006 שהרי אף זה בזיון הוא.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 זו של \u0003רבא:\u0004"],["נאמר: \"ושור ושה שרוע וקלוט נדבה תעשה אותו ולנדר לא ירצה\" (ויקרא כב, כג). ודורשים: \u0003\"נדבה תעשה אתו\"\u0004 — \u0003זה קדשי בדק הבית.\u0004 שאין בעלי מומים אלה כשרים להקרבה על המזבח, אלא יימכרו ודמיהם ילכו לדברים הנצרכים לאחזקת בית המקדש. \u0003ו\u0004עדיין אומר ש\u0003אין לי\u0004 בדינם של בעלי מומים אלה שכשרים להקדשתם לצרכי בדק הבית \u0003אלא\u0004 באופן הקדשה של \u0003נדבה,\u0004 שבכגון זה אם אבדו — אינו צריך להביא אחרת תחתיהם, ואולם המקדיש בעלי מום לבדק הבית באופן הקדשה של \u0003נדר, מנין\u0004 לנו, שאף הם בכלל? — לכך \u0003תלמוד לומר\u0004 בהמשך הפסוק \u0003\"ולנדר\"\u0004 — ללמד שמקדיש בעל מום לצרכי בדק הבית אף בדרך נדר (שהמילים \"תעשה אותו\" מתפרשות לפניהן ולאחריהן: \"נדבה תעשה אותו\", \"תעשה אותו ולנדר\").","ומבררים עוד: \u0003יכול\u0004 הותר להקדיש בעלת מום \u0003אפילו\u0004 שלא לבדק הבית אלא ל\u0003קדשי מזבח?\u0004 — לכך \u0003תלמוד לומר \"ולנדר לא ירצה\"\u0004, וכתוב \u0003זה\u0004 כוונתו ל\u0003קדשי מזבח\u0004 (שיש בהם ריצוי, כפרה). \u0003ו\u0004מבררים עוד: \u0003אין לי\u0004 ללמוד מפסוק זה איסור על הקדשת בעלת מום למזבח \u0003אלא\u0004 כשמקדישה ב\u0003נדר,\u0004 ואולם כשמקדישה ב\u0003נדבה\u0004 (\"הרי זו\") \u0003מנין\u0004 לנו שאף היא בכלל איסור? — לכך \u0003תלמוד לומר\u0004 \u0003\"נדבה\".\u0004 \u0003רבי אומר\u0004 בכוונת הכתוב \u0003\"לא ירצה\"\u0004 : \u0003ב\u0004איסור ההקדשה של קרבן שעניינו \u0003הרצאת גופו\u0004 (הקרבתו למזבח, שבכך כפרתו) \u0003הכתוב מדבר,\u0004 ולא בהקדשה לדמיו, לבדק הבית.","ותוהים: דברי רבי אלו \u0003היינו\u0004 \u0005[זהו]\u0006 כדברי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 הסבור אף הוא שאי אפשר להקדיש בעלת מום למזבח, ובמה נחלקו? \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חולקים]\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 שלא רק המקדיש בעלי מומים להקרבה על המזבח עובר ולוקה על כך, אלא \u0003אפילו\u0004 רק \u0003אקדשיה\u0004 \u0005[הקדישו]\u0006 \u0003לדמי נסכים\u0004 — \u0003נמי לקי\u0004 \u0005[גם כן לוקה],\u0006 וכשיטת רבא. \u0003ו\u0004אילו \u0003רבי סבר\u0004 \u0005[סבור]:\u0006 אמנם המקדיש בעלת מום \u0003בהרצאת גופו\u0004 (להקרבה על המזבח) — \u0003נמי לקי\u0004 \u0005[גם כן לוקה],\u0006 \u0003אבל ב\u0004הקדשה ל\u0003דמי נסכים\u0004 — \u0003לא לקי\u0004 \u0005[אינו לוקה],\u0006 ושלא כשיטת רבא. ונמצא איפוא ששיטת רבא קשורה במחלוקת תנאים אלו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא.","ונפנים לבירור הנאמר עוד בברייתא. בברייתא נדרשו המילים \"נדבה תעשה\", \"ולנדר לא ירצה\" בכמה אופנים. \u0003ו\u0004מעתה יש לשאול: \u0003אלא\u0004 המלה \u0003\"אתו\"\u0004 שלא נדרשה בברייתא \u0003למה לי\u0004 (מה היא מלמדתנו)? ומשיבים: \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 במילים \u0003\"נדבה תעשה אתו\"\u0004 — בא הכתוב למעט: דווקא \u0003אותו\u0004 (בעל המום) \u0003תעשה\u0004 (תקדיש) \u0003נדבה\u0004 לבדק בית המקדש \u0003ו\u0004אולם \u0003אי\u0004 (אין) \u0003אתה עושה\u0004 (מקדיש) \u0003תמים\u0004 הראוי להעלותו למזבח כ\u0003נדבה ל\u0004צורך \u0003בדק הבית. מיכן\u0004 (מכאן) \u0003אמרו\u0004 חכמים: \u0003המקדיש תמימים לבדק הבית\u0004 — \u0003עובר בעשה\u0004 (אותו אתה עושה, ואין אתה עושה תמים).","\u0003ומנין\u0004 שהוא עובר \u0003אף ב\u0004איסור \u0003לא תעשה\u0004 — \u0003ש\u0004כן \u0003נאמר\u0004 בראש הפרשה \u0003\"וידבר ה' אל משה לאמר\"\u0004 (ויקרא כב, יז) — \u0003לימד\u0004 הכתוב מכאן \u0003על\u0004 כל האמור לאחר מכן בגוף \u0003הפרשה שהיא ב\u0004איסור \u0003לאו\u0004 (לא תעשה), אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי לבר קפרא: מאי משמע\u0004 \u0005[מה,\u0006 כיצד \u0005משתמע]\u0006 מהכתוב \"וידבר ה' אל משה לאמר\" שהפרשה כולה היא באיסור לאו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא לרבי בהסבר הדברים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפסוק \u0003\"לאמר\",\u0004 וכוונת הכתוב — הציווי \u0003\"לא\"\u0004 הוא ש\u0003נאמר בדברים\u0004 הבאים בפרשה, לומר שהעובר עליהם עובר בלא תעשה. ומביאים עוד בהסבר דברי ר' יהודה. \u0003בי רבי אמרי\u0004 \u0005[\u0006חכמי בית המדרש של \u0005רבי אומרים]\u0006 שכך דיבר ה' אל משה: \u0003\"לא\"\u0004 הוא ש\u0003אמור\u0004 לבני ישראל בענין הדברים האמורים בפרשה זו לומר שכל האמור בה בכלל לא תעשה.","בברייתא (בדף ו,ב) שנינו כי בכלל האיסורים שעובר המקדיש הם \"בל תקטירו כולו\" ו\"בל תקטירו מקצתו\". ודנים בדבר. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: \u0003המעלה אברי בעלי מומין לגבי\u0004 (על) ה\u0003מזבח\u0004 להקריבם, \u0003אמר רבא: עובר משום \"בל תקטירו כולו\" ומשום \"בל תקטירו מקצתו\". אמר אביי:\u0004 אינו לוקה על שניהם, שהרי כלל הוא ש\u0003אין לוקין על לאו שבכללות\u0004 (כתוב אחד בתורה שממנו נלמדים כמה איסורים), וכאן שני האיסורים זה שבהקטרת כולו וזה שבהקטרת מקצתו נלמדים מכתוב אחד (\"ואשה לא תתנו מהם\", ויקרא כב, כב).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת אביי ממה ששנינו בברייתא: \u0003המקדיש בעלי מומין לגבי מזבח\u0004 — \u0003עובר משום חמשה שמות\u0004 (איסורים), ובכלל חמשת האיסורים הללו שנויים הן הקטרת כולו והן הקטרת מקצתו, הרי שהעובר על שניהם — לוקה. והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת","\u0003אביי! אמר אביי\u0004 בדחיית הקושיה: \u0003בגברי קתני\u0004 \u0005[ב\u0006שני \u0005אנשים\u0006 נפרדים \u0005שנינו]\u0006 דברים אלה, שהאחד מקטיר את כולו, והאחר מקטיר את מקצתו. ואולם אדם אחד שהקטיר את כולו — אינו מתחייב מלקות אלא על אחד מהם. ומקשים על דבריו: אין לומר כן בברייתא, שהרי \u0003אי\u0004 \u0005[אם]\u0006 מדובר בה כדבריך \u0003בגברי\u0004 \u0005[ב\u0006שני \u0005אנשים]\u0006 נפרדים — לשון זה ששנינו בברייתא \u0003\"עובר\u0004 משום חמישה שמות...\" אינה מדוייקת, אלא \u0003\"עוברין\u0004 משום חמישה שמות\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שמדובר בברייתא \u0003בחד גברא\u0004 \u0005[באדם אחד]\u0006 שהקטיר את כולו, \u0003ו\u0004הרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת \u0003אביי!\u0004","\u0003אמר אביי\u0004 בתשובה: אכן בברייתא מדובר באדם אחד, והוא עובר על חמישה איסורים, ואולם אינו לוקה גם על הקטרת כולו וגם על הקטרת מקצתו, ובאשר לשאלה: אם כן אין כאן אלא ארבעה איסורים ולא חמישה, \u0003אפיק\u0004 \u0005[הוצא]\u0006 מן הברייתא את המילים \"ומשום \u0003הקטרת מקצתו\", ועייל\u0004 \u0005[והכנס]\u0006 במקומם את המילים \"ומשום \u0003קבלת הדם\".\u0004 שהוא האיסור החמישי שעובר עליו. ותוהים: כיצד אפשר לגרוס בדברי התנא הראשון שבברייתא שעובר המקדיש בעלי מומים למזבח אף על \u0003קבלת\u0004 ה\u0003דם?\u0004 הרי כיון ש\u0003לר' יוסי בר' יהודה\u0004 שבברייתא \u0003אית ליה\u0004 \u0005[יש לו,\u0006 סבור הוא\u0005]\u0006 שאף זה איסור שעובר עליו, ומוסיף אותו כאיסור שישי, ומשמע אם כן ש\u0003לתנא קמא לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור] כן? ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מן הברייתא לשיטת אביי.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בנוסח דחיית תירוצו של אביי שיש להוציא ממנין החמישה איסורים את הקטרת מקצתו ולהכניס תחתיה את קבלת הדם: \u0003והא מדסיפא\u0004 \u0005[והרי מ\u0006תוך \u0005שהסוף]\u0006 של הברייתא דברי \u0003ר' יוסי בר' יהודה היא,\u0004 הסבור שעובר אף על קבלת הדם, מכאן נסיק כי \u0003רישא רבנן\u0004 \u0005[תחילת\u0006 הברייתא היא כשיטת \u0005חכמים]\u0006 החולקים על ר' יוסי בר' יהודה בכך. והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003אביי!\u0004 ומסכמים: אכן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ונדחו דבריו.","\u0003הכהנים ממירין\u0004 \u0003ב\u0004קרבנות \u0003שלהן\u0004 (שהקדישו עבור עצמם), \u0003ו\u0004כן \u0003ישראל ממירין ב\u0004קרבנות \u0003שלהן.\u0004 אולם \u0003אין הכהנים ממירין לא ב\u0004קרבן \u0003חטאת, ולא ב\u0004קרבן \u0003אשם, ולא ב\u0004קרבן \u0003בכור\u0004 שקיבלו מאת הישראל להקריבם. שכן אין אלה רכושם, ואין אדם ממיר בדבר שאינו שלו. \u0003אמר ר' יוחנן בן נורי:\u0004 וכי \u0003מפני מה אין\u0004 הכהנים \u0003ממירין ב\u0004קרבן \u0003בכור\u0004 שניתן להם, והרי הוא כולו שלהם? \u0003אמר לו ר' עקיבא\u0004 בתשובה: ה\u0003חטאת ו\u0004ה\u0003אשם\u0004 — הריהם \u0003מתנה לכהן,\u0004 שהכהן מקבל רק את בשרם לאכילה, \u0003ו\u0004אף ה\u0003בכור\u0004 — הריהו \u0003מתנה לכהן.\u0004 וכיון שהושווה הבכור לחטאת ולאשם, לענין קנין הכהן, יש להשוותם אף לענין דין התמורה, ולומר: \u0003מה\u0004 בקרבן ה\u0003חטאת ו\u0004בקרבן ה\u0003אשם\u0004 — \u0003אין\u0004 הכהנים שקיבלוהו מידי הישראל \u0003ממירין בו, אף\u0004 ה\u0003בכור\u0004 שקיבלוהו מידי הישראל — \u0003אין\u0004 הכהנים \u0003ממירין בו.\u0004","\u0003אמר ר' יוחנן בן נורי\u0004 לר' עקיבא לדחות את דבריו אלה: \u0003מה\u0004 ראיה יש \u0003לו\u0004 מדין התמורה בחטאת ואשם לדין התמורה בבכור, שהרי \u0003אם\u0004 הכהן \u0003אינו ממיר בחטאת ואשם\u0004 — הרי זה משום \u0003שאין\u0004 הכהנים \u0003זכין\u0004 (זוכים) \u0003בהן\u0004 (בבשרם) \u0003בחייהן\u0004 של קרבנות אלו, אלא רק לאחר שהוקטרו אימוריהם על המזבח ואז לא שייך להמיר. \u0003תאמר\u0004 שכך יהיה דין התמורה אף \u0003ב\u0004קרבן ה\u0003בכור\u0004 — \u0003שזכין בו\u0004 הכהנים אף \u0003בחייו,\u0004 שאז יכולים הם להמיר והרי הוא איפוא שלהם?! \u0003אמר לו ר' עקיבא\u0004 לר' יוחנן בן נורי: \u0003והלא כבר נאמר\u0004 בתורה בפרשת התמורה: \"לא יחליפנו ולא ימיר אותו... ואם המר ימיר בהמה בבהמה \u0003והיה הוא ותמורתו יהיה קדש\"\u0004 (ויקרא כז, י), ומכאן, שהושוו קדושות שתי הבהמות הללו, זו של בהמת החולין (התמורה), וזו של בהמת ההקדש. וקדושת קרבן ההקדש \u0003היכן קדושה חלה עליו\u0004 (היכן התקדש) בשעתו? — \u0003בבית הבעלים\u0004 כשהקדישוהו לקרבן. ומכאן ש\u0003אף\u0004 קדושת בהמת ה\u0003תמורה\u0004 — אינה חלה אלא \u0003בבית הבעלים\u0004 של הקרבן. ואין הכהן יכול להמיר על הבכור שקיבל, שאינו בכלל הבעלים של קרבן זה.","מאחר ועסקנו במשנתנו בדין קרבן הבכור, דנים עוד בעניינו. \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה\u0005]:\u0006 ה\u0003בכור מוכרין אותו\u0004 באופן זה: בעודו \u0003תם\u0004 (בלי מום) — אינו נמכר אלא כשהוא \u0003חי.\u0004 ואולם לא בהיותו שחוט, שאז הוא אסור בהנאה. \u0003ו\u0004אילו בכור \u0003בעל מום\u0004 — נמכר בין שהוא \u0003חי ו\u0004בין שהוא \u0003שחוט. ומקדשין בו\u0004 הכהנים את \u0003האשה,\u0004 שכן הוא ממונם. ו\u0003אמר רב נחמן, אמר רבה בר אבוה\u0004 על משנה זו: \u0003לא שנו\u0004 במשנה שיכול הכהן למוכרו כשהוא חי \u0003אלא בזמן הזה,\u0004 שאין בית המקדש קיים, ש\u0003הואיל\u0004 ואין מקריבים את הבכורות \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לכהן זכייה בגוויה\u0004 \u0005[בו]\u0006 עוד בעודו חי \u0003(הואיל ויש לכהן שותפות בו).\u0004 שבזמן הזה שייכים הבכורות (אף התמימים) לכהנים. \u0003אבל בזמן שבית המקדש קיים\u0004 — \u0003כיון\u0004 שבכור \u0003תם להקרבה הוא דקאי\u0004 \u0005[שעומד]\u0006 — \u0003אין מוכרין אותו\u0004 כשהוא \u0003תמים\u0004 (וראוי להקרבה) \u0003חי.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 מדיוק לשון המשנה: \u0003\"מוכרין אותו תמים חי\"\u0004 ומכאן נדייק: כשהוא \u0003חי\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נמכר הבכור, ואילו כשהוא \u0003שחוט\u0004 — \u0003לא\u0004 נמכר. ומעתה נברר: \u0003אימת\u0004 \u0005[אימתי,\u0006 מתי\u0005]\u0006 לגבי איזה זמן נשנו דברים אלו, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בזמן הזה\u0004 שאין בית המקדש קיים — \u0003מי איכא\u0004 \u0005[האם יש]\u0006 בימינו \u0003תם שחוט?\u0004 והרי אסור לשחוט את הבכור, שהוא קדוש בקדושת קרבן, והשוחטו הריהו כמקריב קדשים מחוץ למקדש ואסור בהנאה! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003בזמן שבית המקדש קיים, וקתני נמי\u0004 \u0005[ושנינו גם כן]\u0006 במשנה (מעשר שני פ\"א מ\"ב) בענין הבכור ש\u0003מוכרין אותו תמים חי (אלמא אית ליה\u0004 \u0005[מכאן\u0006 נסיק ש\u0005יש לו]\u0006 \u0003לכהן זכייה בגוויה\u0004 \u0005[בו]\u0006 \u0003)\u0004 ויכול הוא למוכרו, ושלא כשיטתך?","ודחה רב נחמן: \u0003לא,\u0004 אין להביא מכאן ראיה כנגד שיטתי, שכן אפשר לומר כי \u0003לעולם\u0004 משנה זו עוסקת \u0003בזמן הזה,\u0004 ואולם \u0003מי קתני\u0004 \u0005[האם שנינו\u0006 בה\u0005],\u0006 בגוף דברי המשנה ש\u0003מוכרין אותו תמים חי\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שחוט\u0004 — \u0003לא,\u0004 אלא יש לומר שהמשנה מדברת בזמן הזה, ו\u0003הא גופא אתא לאשמועינן\u0004 \u0005[ו\u0006דין \u0005זה כשלעצמו באה להשמיענו]:\u0006 ש\u0003בזמן הזה נמי\u0004 \u0005[גם כן]\u0006 — \u0003מוכרין אותו\u0004 בהיותו תמים חי, ואין בו התייחסות לתם שחוט."],["\u0003איתיביה\u0004 \u0005[הקשה עליו]\u0006 עוד רבא על רב נחמן הסבור שבזמן שבית המקדש קיים, אין לכהן זכות בבכור תם כשהוא חי, ממה ששנינו בברייתא: אף ש\u0003בבכור\u0004 אין דין פדיון (שאין הוא יוצא מידי קדושתו על ידי פדיונו) וכפי ש\u0003נאמר\u0004 \"אך בכור שור או בכור כשב או בכור עז \u0003לא תפדה\u0004 קודש הם את דמם תזרוק על המזבח ואת חלבם תקטיר אשה לריח ניחוח לה'\" (במדבר יח, יז), \u0003ו\u0004מכל מקום \u0003נמכר הוא\u0004 על ידי הכהן לכהן אחר שאוכלו כדין בכור. ונדון: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה זמן, \u0005עוסקים אנו]\u0006 בברייתא זו? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר בה \u0003בזמן הזה\u0004 שלאחר חורבן המקדש — \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופו]\u0006 של אותו הכתוב \u0003\"ואת דמם תזרק על המזבח\",\u0004 וכי \u0003בזמן הזה\u0004 שלאחר חורבן הבית \u0003מי איכא\u0004 \u0005[האם יש]\u0006 \u0003מזבח?! אלא פשיטא\u0004 \u0005[פשוט] שמדובר\u0006 \u0003בזמן שבית המקדש קיים.\u0004","ועוד: \u0003ובמאי\u0004 \u0005[ובמה,\u0006 באיזה בכור\u0005]\u0006 מדובר בכתוב זה? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר \u0003ב\u0004בכור \u0003בעל מום\u0004 — ודאי אינו כן, שכן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופו]\u0006 של הפסוק \u0003\"ואת דמם תזרק על המזבח ואת חלבם תקטיר\",\u0004 ו\u0003מי חזי\u0004 \u0005[\u0006ו\u0005האם ראוי]\u0006 בכור בעל מום \u0003להקרבה\u0004 על המזבח?! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003ב\u0004בכור שהוא \u0003תם\u0004 (שאינו בעל מום), \u0003וקתני\u0004 \u0005[ושנינו]\u0006 בברייתא זו בדינו ש\u0003נמכר הוא. אלמא אית להו\u0004 \u0005[הרי\u0006 איפוא \u0005יש להם]\u0006 \u0003לכהן זכייה בגויה\u0004 \u0005[בו,\u0006 בבכור תם בעודו חי\u0005],\u0006 וקשה לשיטת רב נחמן!","ודחה רב נחמן: \u0003מידי איריא\u0004 \u0005[וכי הדברים מכוונים]\u0006 שכל חלקי הפסוק יהיה עניינם אחד?! אפשר לחלק ולומר כי \u0003רישא\u0004 \u0005[ההתחלה]\u0006 של הפסוק, ממנו למדנו שאין לבכור פדיון אבל יש לו מכירה — עוסקת \u0003ב\u0004בכור \u0003בעל מום,\u0004 שאינו ראוי להקרבה, ונמכר. ואילו \u0003סיפא\u0004 \u0005[סוף]\u0006 הפסוק שעניינו דיני הקרבת דמו וחלביו של הבכור — עוסק \u0003ב\u0004בכור שהוא \u0003תם\u0004 הראוי להקרבה, וזה אינו נמכר.","ומקשים עוד על שיטתו זו של רב נחמן. \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב משרשיא\u0004 ממה ששנינו במשנה: \u0003כהנת\u0004 (אשת כהן) \u0003שנתערבה ולדה\u0004 \u0003בולד שפחתה,\u0004 ואין ידוע מיהו בן הכהן ומיהו עבדו של הכהן. הרי כאשר \u0003הגדילו התערובות\u0004 הללו — \u0003משחררין\u0004 (כותבים שטר שחרור מעבדות) \u0003זה את זה.\u0004 וכל עוד לא שחררו זה את זה, אף שכל אחד מהם ספק, אם הוא כהן או עבד, מכל מקום \u0003שניהם אוכלין בתרומה,\u0004 שכן שניהם זכאים לאכול מן התרומה, שהרי אף עבדו של הכהן אוכל בתרומת אדוניו, \u0003ו\u0004\u0005כן נוהגים שניהם (מן הספק) בדיני הכהנים:\u0006 \u0003חולקין\u0004 (זכאים לקבל) רק \u0003חלק אחד\u0004 מן התרומה הניתנת לכהן \u0003על הגורן,\u0004 שהרי מבין שניהם רק אחד כהן הוא. ו\u0003בכורן\u0004 של כל אחד מהם, מה דינו? שהרי הבכור התם צריך להקריב את אמוריו, והכהן המקריבו זכאי לאכול את בשרו, שאין הבכור התם נאכל אלא לכהנים, ולא לישראל. ושני אלה, שאין ידוע מי מהם הוא הכהן — דינם של הבכורות הנולדים להם ש\u0003ירעו עד שיסתאבו\u0004 (יפול בהם מום), שכן משנפל בהם מום מותרים הם באכילה אף לישראל, \u0003ויאכלו\u0004 לשניהם \u0003במומן.\u0004","ויש לברר את דברי המשנה: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה זמן \u0003אנו עוסקים]\u0004 במשנה זו? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר \u0003בזמן הזה\u0004 שלאחר חורבן הבית — יש לשאול: \u0003מאי שנא דידן ומאי שנא דידהו\u0004 \u0005[מה שונה\u0006 דין הבכור \u0005שלנו,\u0006 הנולד לישראל ודאי, \u0005ומה שונה\u0006 דין הבכור \u0003שלהם]?\u0004 הרי בבכורות \u0003דידן נמי\u0004 \u0005[שלנו גם כן]\u0006 \u0003מומין בעינן\u0004 \u0005[צריכים אנו]\u0006 על מנת להתיר אכילתם. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נסיק שמדובר במשנה \u0003בזמן שבית המקדש\u0004 היה \u0003קיים.\u0004 ומשמיעתנו המשנה, שאף שבזמן המקדש בכור תם הנולד לישראל ניתן לכהן להקריבו ולאוכלו, מכל מקום במקרה זה של התערובת, אין הבכור של אחד מהם, ניתן לאחד מהם, שהרי יתכן ואינו כהן ואסור בעבודת הקרבנות ובאכילת הבכור. ומכאן נסיק: \u0003אי אמרת בשלמא אית להו\u0004 \u0005[זה נוח אם אתה אומר\u0006 ש\u0005יש להם]\u0006 \u0003לכהן זכייה בגוויה\u0004 \u0005[בתוכו,\u0006 בבכור\u0005]\u0006 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן דין זה\u0005]\u0006 שמחזיקים שני אלה בבכורות שנולדו להם, מכח הטענה שאולי הוא כהן, \u0003אלא אי אמרת לית ליה\u0004 \u0005[אם אתה אומר\u0006 ש\u0005אין לו]\u0006 לכהן זכות בבכור — מדוע מניחים אנו להם להשאיר בידיהם את הבכורות? \u0003ליתי\u0004 \u0005[שיבוא]\u0006 ה\u0003גזבר\u0004 של המקדש \u0003ולישקלא\u0004 \u0005[ויקחנו]\u0006 את הבכור מידיהם כדי להקריבו! והרי זו איפוא ראיה כנגד שיטת רב נחמן האומר שלכהן אין זכות בבכור התם, בזמן בית המקדש.","ודוחים: \u0003לעולם\u0004 נאמר שמדובר במשנה \u0003בזמן הזה, ודקא קשיא\u0004 \u0005[ו\u0006זה \u0005שהיה קשה]\u0006 \u0003לך מאי שנא דידן ומאי שנא דידהו\u0004 \u0005[מה שונה\u0006 דין בכור \u0005שלנו ומה שונה\u0006 דין בכור \u0005שלהם],\u0006 והרי אף אנו ממתינים עד שיפול בבכור מום כדי שיותר באכילה? — ההבדל הוא בכך, כי \u0003אנן\u0004 \u0005[אנחנו],\u0006 בדין בכור הרגיל — \u0003יהבינן ליה\u0004 \u0005[נותנים אנו\u0006 את הבכור \u0005לו]\u0006 \u0003לכהן במומייהו\u0004 \u0005[במומם],\u0006 שמשעה שנפל בו מום, אסור לנו לעכב את הבכור בידינו. שאף שהוא בעל מום ומותר לזרים — רכוש הכהן הוא, והמחזיק בבכור ואינו מוסרו לכהן — הריהו גוזל את הכהן. ואילו \u0003אינהו\u0004 \u0005[הם],\u0006 במקרה מסויים זה של תערובת הכהן והעבד — \u0003כיון דאיכא בהו\u0004 \u0005[שיש בהם,\u0006 בכל אחד מהם\u0005],\u0006 מצד הספק, \u0003מקצת כהן\u0004 — \u0003מפקע ליה\u0004 \u0005[מפקיע\u0006 כל אחד מהם \u0005אותו,\u0006 את הבכור שבידו\u0005]\u0006 מליתנו \u0003לכהנים,\u0004 שהרי הוא משיב לכל כהן הבא לתבוע ממנו את הבכור, שהוא עצמו כהן והוא שזכה בבכור.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בקושיית רב משרשיא על רב נחמן: אם תאמר שהמשנה עוסקת \u0003בזמן הזה\u0004 שאין בית המקדש קיים — יש לשאול: \u0003מאי איריא\u0004 \u0005[מדוע דווקא]\u0006 ב\u0003בכורות דהלין\u0004 \u0005[של אלו]\u0006 שני ה\u0003ספיקות\u0004 (המסופקים מיהם) השמיעתנו המשנה שדינם של הבכורות הנולדים להם שירעו עד שיפול בהם מום, והרי דין זה \u0003אפילו\u0004 בבכורות \u0003דידן נמי\u0004 \u0005[שלנו,\u0006 ישראלים רגילים, שאין בהם ספק כהן, \u0005גם כן]\u0006 הדין הוא ש\u0003ירעו\u0004 עד שיפול בהם מום! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שמדובר במשנה \u0003בזמן שבית המקדש קיים. ו\u0004מעתה נוסיף ונשאל: באיזה בכור עוסקת המשנה? \u0003אי\u0004 \u0005[ואם]\u0006 המדובר \u0003ב\u0004בכור \u0003בעל מום\u0004 — מה מקום יש לומר במשנה בענין הבכורות הללו \u0003\"ירעו עד שיסתאבו\"\u0004 (יפול בהם מום)? \u0003הא\u0004 \u0005[הרי]\u0006 הם \u0003מסואבין וקיימין\u0004 [ועומדים]! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שמדובר במשנה \u0003בתמין, והכי\u0004 \u0005[וכך]\u0006 \u0003הוא\u0004 דווקא דינם של אלה בני התערובת \u0003דלא מזבני\u0004 \u0005[ש\u0006הם \u0005אינם מוכרים]\u0006 את הבכורות שלהם, שהרי כל אחד מהם הוא ספק ישראל, ואפשר שחייב הוא מכח זה לתתו לכהן. ואולם אם היו אלה כהנים \u0003ודאי\u0004 — מותר היה להם למכור את הבכור שלהם, אף בזמן בית המקדש ואף שהוא תם חי. והרי זו איפוא ראיה נגד שיטת רב נחמן!","ומשיבים: \u0003לעולם\u0004 לשיטת רב נחמן יש לומר שהמשנה עוסקת \u0003בזמן הזה,\u0004 \u0003מאי קשיא\u0004 \u0005[מה\u0006 שהיה \u0005קשה]\u0006 \u0003לך,\u0004 שאם כן בזמן הזה \u0003אפילו\u0004 בכורות \u0003דילן נמי\u0004 \u0005[שלנו,\u0006 אצל ישראלים רגילים, \u0005גם כן]\u0006 דינם הוא ש\u0003ירעו\u0004 עד שיסתאבו ורק אז מותר למוכרם? התשובה לכך היא שיש הבדל בין דיננו לדינם של התערובות הללו. שכן אנחנו \u0003לא מצינו מדחית ליה\u0004 \u0005[איננו יכולים לדחות אותו]\u0006 את ה\u0003כהן\u0004 הבא לקחת את הבכור מידינו, משום ש\u0003לא אית\u0004 \u0005[שאין] כאן\u0006 אצלנו \u0003ספק כהונה,\u0004 ואין אנו יכולים לעכב את הבכור בידינו. ואילו \u0003הני\u0004 \u0005[אלו]\u0006 ה\u0003ספיקות\u0004 — \u0003מדחו\u0004 \u0005[\u0006יכולים \u0005לדחות]\u0006 את ה\u0003כהן\u0004 הבא לקחת מידיהם את הבכור, שכן \u0003כל חד וחד אמר ליה\u0004 \u0005[אחד ואחד\u0006 מהם \u0005אומר לו]\u0006 \u0003לכהן:\u0004 לא אתן לך, כיון \u0003דאנא\u0004 \u0005[שאני]\u0006 עצמי הריני \u0003כהן, ו\u0004כן השני אומר: לא אתן כי \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כהן.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על שיטת רב נחמן ממה ששנינו בדינה של עיר הנדחת, שממיתים את כל החיים בה, אדם ובהמה, ושורפים את כל הנמצא בה. \u0003ר' שמעון אומר:\u0004 לשון \u0003\"בהמתה\"\u0004 באה למעט: שלה ולא של גבוה, \u0003פרט לבהמת בכור ו\u0004לבהמת \u0003מעשר שבה,\u0004 שאינן נהרגות. וכן הלשון \u0003\"שללה\"\u0004 (שלה ולא של גבוה) באה לומר ששורפים את כל שלל העיר, \u0003פרט לכסף מעשר שני שבה,\u0004 ודנים בדבריו:","\u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים],\u0006 באיזו תקופה עוסקים דברי ר' שמעון אלה? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר \u0003בזמן הזה\u0004 לאחר חורבן הבית — \u0003מי איכא\u0004 \u0005[האם יש,\u0006 נוהג\u0005]\u0006 בימינו דין \u0003עיר הנדחת? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין עושין\u0004 (קובעים דינה) של \u0003עיר הנדחת אלא בבית דין של שבעים ואחד,\u0004 ואין בית דין שכזה לאחר החורבן! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003בזמן שבית המקדש קיים. ו\u0004נוסיף ונשאל עוד:","\u0003במאי\u0004 \u0005[במה,\u0006 באיזה בכור המדובר\u0005]?\u0006 \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שמדובר \u0003ב\u0004בכור \u0003בעל מום\u0004 שהוא רכוש הבעלים — מדוע אין ממיתים אף אותו בכלל בהמות אנשי העיר, והרי \u0003היינו\u0004 \u0005[זהו]\u0006 בכלל \u0003\"בהמתה\"\u0004 האמורה בפרשה זו, שהרי הוא רכוש הכהן ולא ממון גבוה! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שמדובר \u0003ב\u0004בכור \u0003תם\u0004 שעומד להקרבה. \u0003ו\u0004מעתה נדון בדבר: \u0003אי אמרת בשלמא אית ליה\u0004 \u0005[זה נוח אם אתה אומר\u0006 ש\u0005יש לו]\u0006 לכהן \u0003זכייה בגוייה\u0004 \u0005[בתוכו]\u0006 של הבכור התם בזמן שבית המקדש קיים — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן\u0005]\u0006 דינו של ר' שמעון, שאין בכור זה הנמצא בעיר הנדחת נחשב בכלל \"בהמתה\" של אנשי העיר, אף שהוא רכוש פרטי. \u0003אלא אי אמרת לית ליה\u0004 \u0005[אם אתה אומר\u0006 ש\u0005אין לו]\u0006 זכייה בבכור התם — \u0003למה לי\u0004 ללמוד \u0003מ\u0004כתוב זה שבענין ה\u0003בהמה\u0004 (\"בהמתה\"), \u0003תיפוק ליה\u0004 \u0005[תצא,\u0006 תילמד, \u0005לו]\u0006 שאין ממיתים את הבכור \u0003מ\u0004הכתוב \u0003\"שללה\",\u0004 שנדרש: דווקא שלל העיר הוא שנשרף, \u0003ולא שלל שמים.\u0004 נמצא שלכהן יש זכייה בבכור התם בזמן הבית, וקשה לשיטת רב נחמן!","ומשיבים: \u0003לעולם\u0004 מדובר בדברי ר' שמעון \u0003ב\u0004בכור \u0003בעל מום, ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 כי \u0003היינו\u0004 \u0005[זהו]\u0006 בכלל \u0003\"בהמתה\",\u0004 וראוי להיות מומת, כשאר בהמות אנשי העיר — על כך יש להשיב: אין בעל החיים הנהרג בעיר הנדחת אלא \u0003מי שנאכל בתורת \"בהמתה\",\u0004 באכילה רגילה של בהמת חולין, \u0003יצאו\u0004 מכלל הגדרה זו ה\u0003בכור ו\u0004ה\u0003מעשר\u0004 — \u0003שאינו בכלל\u0004 הנאכלים בתורת \u0003\"בהמתה\",\u0004 כלומר, באכילה רגילה אף בהיותם בעלי מום,","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל פסולי המוקדשין\u0004 (קדשים שנפל בהם מום, ונפסלו מהקרבה) והריהם נפדים, והרווח ממכירתם הריהו להקדש, ומשום כך, כדי שההקדש לא יפסיד, הריהם \u0003נמכרין באיטליז,\u0004 בבית המטבחיים שבמקום השוק, שם מרובים הקונים, ומחירם גבוה, ואין אומרים שיש בזה זלזול בקדשים. \u0003ו\u0004כן הריהם \u0003נשחטין באיטליז. ו\u0004כן כשמוכרים את בשרם, הריהם \u0003נשקלין בליטרא\u0004 (במשקל), כדרך ששוקלים בשר רגיל. \u0003חוץ מן הבכור ומן\u0004 בהמת \u0003המעשר,\u0004 שכשנפל בהם מום והותרו לשחיטה, אינם נמכרים ואינם נשחטים אלא בתוך ביתו, ואינם נשקלים בליטרא אלא באומד, כיון \u0003שהנאתן\u0004 אינה אלא \u0003לבעלים\u0004 (הבכור — לכהן, והמעשר — לבעליו) ולא להקדש, שהרי אין להם פדייה. והואיל ואין להקדש רווח בכך — אין נוהגים בהם מנהג חולין.","עוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רב נחמן ממה ששנינו בדין שבועת הפקדון, הכופר בפקדון, שטען חבירו שהפקיד בידו פקדון, וכפר בכך, ונשבע על כך לשקר, שצריך להוסיף חומש על הפקדון, ולהביא קרבן אשם. כאמור: \"נפש כי תחטא \u0003ומעלה מעל בה'\u0004 וכחש בעמיתו בפקדון או בתשומת יד.... ונשבע על שקר על אחת מכל אשר יעשה האדם לחטוא בהנה\" (ויקרא ה, כא—כב), שבאה לשון זו \"מעל בה'\", אף שענין הפרשה הוא בין אדם לחבירו (\"וכחש בעמיתו\") — \u0003לרבות\u0004 אף את הנשבע לשקר על פקדון \u0003קדשים קלים\u0004 שהפקיד חבירו בידו, \u0003ש\u0004כן קדשים קלים \u0003הן ממון בעלים,\u0004 אלו \u0003דברי ר' יוסי הגלילי.\u0004","\u0003בן עזאי אומר:\u0004 בא כתוב זה \u0003לרבות\u0004 רק את קרבן \u0003שלמים\u0004 שהפקיד חבירו בידו, ונשבע על כך לשקר. \u0003אבא יוסי בן דוסאי אומר: לא אמר בן עזאי\u0004 אלא כך: לא בכל הקדשים הקלים נוהגת שבועת הפקדון, \u0003אלא בבכור בלבד.\u0004","ויש לדון בדברי ברייתא זו: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזו תקופה \u0005עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בזמן הזה\u0004 שלאחר חורבן הבית — \u0003הא\u0004 \u0005[הרי]\u0006 את דין הקדשים הקלים והבכור לענין שבועת הפקדון \u0003דומיא\u0004 \u0005[בדומה,\u0006 בהקשר\u0005]\u0006 לדינם בקרבן ה\u0003שלמים קתני\u0004 \u0005[שנינו]\u0006 בברייתא, והרי בזמן הזה אין נוהגים השלמים! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר בברייתא זו \u0003בזמן שבית המקדש\u0004 היה \u0003קיים. ו\u0004נדון עוד:","\u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה בכור \u0005עוסקים אנו]\u0006 בברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר בה \u0003ב\u0004בכור \u0003בעל מום\u0004 — \u0003הא דומיא\u0004 \u0005[הרי בדומה]\u0006 ל\u0003שלמים קתני\u0004 \u0005[שנינו],\u0006 ובשלמים אין הבדל אם הם תמימים או בעלי מומים (שהרי בכל אופן הריהם של בעליהם)! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר שמדובר \u0003ב\u0004בכור \u0003תם, ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 — \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לכהן זכייה בגוויה\u0004 \u0005[בתוכו,\u0006 בבכור\u0005]\u0006 בעודו חי. וקשה לרב נחמן!"],["בדחיית קושיה זו לשיטת רב נחמן \u0003אמר אביי: לא,\u0004 מכאן אין להקשות, שכן אפשר לומר כי \u0003לעולם\u0004 מדובר בברייתא זו בזמן שבית המקדש היה קיים, ו\u0003ב\u0004בכור \u0003תם,\u0004 ואולם מדובר \u0003בבכור בחוצה לארץ.\u0004 שכיון שמן הסתם אינו עומד להקרבה זוכה בו הכהן, ואולם בבכור בארץ ישראל אין לו כל זכות. \u0003ו\u0004כשיטת \u0003ר' שמעון היא\u0004 ברייתא זו, ש\u0003אמר\u0004 ש\u0003אם באו\u0004 בכורות \u0003תמימין\u0004 מחוצה לארץ לבית המקדש — הרי אלו \u0003יקרבו\u0004 על המזבח. ומדבריו משמע שאין חובה להביאם להקרבה בבית המקדש, ומשום כך, סתם בכור בחוצה לארץ, גם בזמן המקדש, אינו עומד להקרבה, ויש לכהן זכייה בו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על שיטת רב נחמן ממה ששנינו במשנתנו בדין התמורה שעשו כהנים בבכור שקיבלו מישראל, שלדעת ר' עקיבא אין בכך כלום, שאין הכהן ממיר בבכור. ולמד את דינו זה מחטאת ואשם, שכשם שבחטאת ואשם אין הכהנים ממירים, אף בבכור אינם ממירים. ו\u0003אמר לו ר' יוחנן בן נורי\u0004 לר' עקיבא בדחיית ראייתו זו: \u0003מה לי\u0004 (במה זו) ראיה, שהרי \u0003אם\u0004 הכהן \u0003אינו מימר בחטאת ואשם\u0004 — \u0003הרי\u0004 זה משום ש\u0003אין\u0004 הכהנים \u0003זכין בהן\u0004 (בבשרם) \u0003בחייהן\u0004 של הקרבנות הללו, אלא רק לאחר שהוקטרו אימוריהם על המזבח, \u0003תאמר\u0004 שכן הדין אף \u0003ב\u0004קרבן ה\u0003בכור\u0004 — \u0003שזכין\u0004 בו הכהנים אף \u0003בחייו?!\u0004 ומעתה נדון בדברים הללו. \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה בכור, \u0005עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ב\u0004בכור \u0003בעל מום\u0004 — \u0003הא דומיא\u0004 \u0005[הרי בדומה]\u0006 ל\u0003חטאת ואשם קאמר\u0004 \u0005[הוא אמר,\u0006 נשנה במשנתנו\u0005],\u0006 וחטאת ואשם אלו הריהם תמימים, שהרי הכהנים אינם זוכים בהם אלא לאחר שנזרק דמם, ואין זה אלא בחטאת ואשם תמימים הראויים להקרבה. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן שמדובר \u0003ב\u0004בכור \u0003תם, וקתני\u0004 \u0005[ושנינו]\u0006 בו ש\u0003זכין בו\u0004 הכהנים \u0003בחייו.\u0004 והרי זה איפוא שלא כשיטת רב נחמן!","\u0003אמר רבינא: הא נמי\u0004 \u0005[\u0006משנתנו \u0005זו גם כן],\u0006 עוסקת \u0003בבכור בחוצה לארץ, ור' שמעון היא,\u0004 ש\u0003אמר: אם באו תמימים\u0004 — \u0003יקרבו.\u0004 וכמו שהעמדנו לפני כן את דברי הברייתא בדין שבועת הפקדון, וכאשר נתבאר מקודם.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 כי שיטת רב נחמן במחלוקת \u0005תנאים]\u0006 היא שנויה. שכן שנינו: \u0003בכור,\u0004 בהיותו \u0003בבית הבעלים\u0004 הישראליים, טרם שניתן לכהן — הרי הם \u0003עושין\u0004 בו \u0003תמורה,\u0004 ואולם בהיותו כבר \u0003בבית הכהן\u0004 — \u0003אין עושין\u0004 בו \u0003תמורה.\u0004 ואילו \u0003ר' שמעון בן אלעזר אומר: כיון שבא לידי כהן\u0004 — \u0003אין עושין תמורה.\u0004","ויש לשאול: הרי דעת ר' שמעון בן אלעזר \u0003היינו\u0004 \u0005[זוהי]\u0006 לכאורה דעת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שלכאורה אין הבדל ביניהם. \u0003מאי לאו הכי קאמר\u0004 \u0005[האם לא כך הוא,\u0006 התנא הראשון, \u0005אומר]:\u0006 משעה שנמצא הבכור \u0003בבית\u0004 ה\u0003כהן\u0004 — \u0003הוא\u0004 הכהן \u0003עושה תמורה, ואין\u0004 ה\u0003בעל\u0004 הישראלי \u0003עושה תמורה.\u0004 ואילו ר' שמעון בן אלעזר חולק ואומר שמשעה שהגיע הבכור לידי הכהן — שוב אין שניהם עושים בו תמורה, לא הבעלים הראשונים ואף לא הכהן. \u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 נוכל להסיק כי התנא קמא סבור כי \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לכהן זכייה בגוויה\u0004 \u0005[בתוכו,\u0006 בבכור\u0005],\u0006 ולכן הוא ממיר עליו, והרי זה שלא כדעת רב נחמן. ואילו ר' שמעון בן אלעזר סבור שאין לכהן זכייה בבכור, ולכן אינו ממיר עליו, וכדעת רב נחמן!","ודוחים: \u0003לא קשיא\u0004 \u0005[לא קשה]\u0006 מדעת התנא קמא שבברייתא זו על רב נחמן. כיון שמדובר בברייתא זו בבכור בחוצה לארץ, ובבכור זה ודאי שלכהן יש זכייה בו. ונחלקו בברייתא במחלוקת העקרונית של ר' יוחנן בן נורי ור' עקיבא במשנתנו, אם הכהנים ממירים בבכור. ומעתה נאמר: \u0003הא\u0004 \u0005[זה],\u0006 דעת התנא קמא שבברייתא זו, שהכהן ממיר בהיות הבכור בבית הכהן — הריהי כדעת \u0003ר' יוחנן בן נורי,\u0004 שהכהנים ממירים על הבכור. ואילו \u0003הא\u0004 \u0005[זה],\u0006 דעת ר' שמעון בן אלעזר, שאין הכהן ממיר אף בהיות הבכור בבית הכהן — הריהי כדעת \u0003ר' עקיבא.\u0004","שנינו למעלה (ז,ב) בתחילת הסוגיה כי \"בכור מוכרין אותו תם — חי, ובעל מום — חי ושחוט\", \u0003אמר רב חסדא: לא שנו\u0004 שמותר לכהן למכור את הבכור התם כשהוא חי, \u0003אלא\u0004 רק ב\u0003כהן\u0004 המוכר \u0003לכהן\u0004 אחר, \u0003אבל כהן לישראל\u0004 — \u0003אסור\u0004 למכור את הבכור. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — גזרו חכמים כן, בשל החשש \u0003דלמא אזיל\u0004 \u0005[שמא ילך]\u0006 ה\u0003ישראל\u0004 הקונה את הבכור מן הכהן, \u0003ושדי ביה מומא\u0004 \u0005[ויטיל בו,\u0006 בבכור \u0005מום],\u0006 המתירו מאיסור אכילת קדשים מחוץ למקומם, וממטי \u0005[ומביא]\u0006 אותו \u0003לחכם\u0004 (שאין מתירים לשחוט ולאכול את הבכור שנפל בו מום אלא על פי חכם המתיר בכורות), \u0003ואומר לו\u0004 הישראל לחכם: \u0003\"בכור זה נתן לי כהן\u0004 כשהוא \u0003במומו\".\u0004 ועל סמך דבריו אלה יתיר לו החכם את הבכור, שלא כדין.","ושואלים: \u0003ומי שרי\u0004 \u0005[והאם מתיר]\u0006 \u0003חכם הכי\u0004 \u0005[כך],\u0006 על סמך דבריו של הקונה הישראלי לבדו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב: אין\u0004 החכמים \u0003רואין בכור לישראל\u0004 לבודקו ולהתירו בשחיטה \u0003אלא אם כן\u0004 היה \u0003כהן עמו\u0004 שיקבל בכור זה, שמא ישחטנו הישראל ויקחנו לעצמו!","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 הסבר אחר בדברי רב חסדא, \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 שלכהן מותר למכור רק לכהן אחר, ואילו ל\u0003ישראל אסור\u0004 לו למכור — \u0003מפני שנראה\u0004 כהן זה המוכר לישראל, \u0003ככהן המסייע\u0004 לבעלים בעבודת התבואה בהיותה \u0003בבית הגרנות\u0004 (מקום זרייתה ברוח), כדי שעבור זה תינתנה לו התרומות מתבואה זו, דבר שאסרוהו חכמים. ואף הכהן המוכר את הבכור שברשותו לישראל (ובדרך כלל, מחירו של הבכור התם, הריהו נמוך ביותר, שהרי צריך הקונה להמתין עד שיפול בו מום, כדי שיוכל לאוכלו), נראה הדבר שמכר לו הכהן במחיר נמוך, על מנת שיתן לו להבא מבכורותיו.","ובענין זה של מכירת בכור לישראל, מסופר כי החכם \u0003מר זוטרא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב אשי. אמרו ליה\u0004 \u0005[לו]\u0006 בני הבית בהזמנה לסעודה: \u0003לטעום מר מידי\u0004 \u0005[יטעום אדוננו דבר].\u0006 \u0003אייתו לקמיה בישרא\u0004 \u0005[הביאו לפניו בשר].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליכול מר, דמיברי\u0004 \u0005[יאכל אדוננו, שמבריא],\u0006 בשר זה במיוחד, \u0003משום דבוכרא\u0004 \u0005[ש\u0006בשר \u0005בכור]\u0006 \u0003הוא!\u0004 שאל אותם מר זוטרא: \u0003מנא לכו הא\u0004 \u0005[מנין לכם\u0006 בשר \u0005זה],\u0006 שהרי הבכור של הכהן הוא! \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דזבן לן\u0004 \u0005[שמכר לנו]\u0006 \u0003פלוני כהן.\u0004","\u0003אמר להו\u0004 \u0005[להם]:\u0006 וכי \u0003לא סבירא לכו הא\u0004 \u0005[אין אתם סבורים\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 שאין הכהן רשאי למכור את הבכור לישראל, \u0003מפני שנראה\u0004 הדבר \u0003ככהן המסייע בבית הגרנות? אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא סבירא לן\u0004 \u0005[אין אנו סבורים]\u0006 כך, כי במקרה שלנו אין לחשוש, משום \u0003דאנן מיזבן קא זבנינן\u0004 \u0005[שאנו קנינו]\u0006 את הבכור י הכהן במחיר מלא, ולא קיבלנוהו במתנה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 מר זוטרא: \u0003ולא ;;;סבירא לכו\u0004 \u0005[ואין אתם סבורים]\u0006 \u0003הדתנן\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עד כמה ישראל חייב ליטפל בבכור\u0004 (לגדלו, קודם שימסרנו לכהן)? \u0003ב\u0004בהמה \u0003דקה\u0004 (כבשים ועזים) — \u0003שלשים\u0004 יום, \u0003וב\u0004בהמה \u0003גסה\u0004 (בקר) — \u0003חמשים יום. ואם אמר לו\u0004 הכהן לישראל בתוך זמן זה: \u0003\"תנהו לי בתוך זמנו\u0004 שאטפל בו אני\" — \u0003הרי זה לא יתננו לו. ואמר רב ששת\u0004 \u0003מה טעם\u0004 אין נותן את הבכור לכהן המבקש בתוך הזמן? — \u0003מפני שנראה ככהן המסייע בבית הגרנות!\u0004","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני ביתו של רב אשי למר זוטרא: \u0003התם\u0004 \u0005[שם,\u0006 בכהן המציע לקחת את הבכור בתוך תקופת הטיפול בו\u0005]\u0006 — אסור הדבר כי \u0003מוכחא מילתא\u0004 \u0005[מוכח הדבר],\u0006 שהרי בעצם לקיחתו את הבכור בתוך תקופת הטיפול בו — הריהו מסייע לבעלים, וניכר שעושה כן על מנת שיקבל את הבכור. ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 בקניית בכור מהכהן\u0005]\u0006 — אין זה נראה ככהן המסייע בבית הגרנות, שהרי \u0003מזבן קא זבנינן\u0004 \u0005[לקנות קנינו],\u0006 ושילמנו לכהן את מלוא דמיו.","\u0003לשון אחר\u0004 בדין ודברים שבין מר זוטרא ובני ביתו של רב אשי. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בתשובה: אין הדברים דומים שכן \u0003הכא\u0004 \u0005[כאן,\u0006 בכהן המציע לטפל בבכור\u0005]\u0006 — הבעלים הישראל \u0003לא יהיב דמי\u0004 \u0005[אינו נותן\u0006 לו על כך \u0005דמים,\u0006 כסף\u0005],\u0006 ולכן יש לחשוש שמא בתמורה לטירחת הכהן חושב הבעלים לתת לו את הבכור עצמו, ובכך דומה הדבר לכהן המסייע בבית הגרנות, ואולם \u0003הכא\u0004 \u0005[כאן,\u0006 במכירת בכור לישראל\u0005]\u0006 — הלא \u0003קא יהיב דמי\u0004 \u0005[הוא נותן דמים].\u0006 \u0003מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 טענה \u0003אמרת\u0004 \u0005[יש בידך לומר],\u0006 שיכול מר זוטרא לומר כי יש לחשוש שנראה המחיר הנמוך ששולם עבור הבכור כאילו \u0003מוזיל\u0004 ה\u0003כהן גביה\u0004 \u0005[אצלו,\u0006 לישראל\u0005],\u0006 משום \u0003דסבר\u0004 \u0005[שחושב]\u0006 ה\u0003כהן,\u0004 שכדאי לו להוזיל במחיר, \u0003דכי הוי ליה\u0004 \u0005[שכאשר יהיה לו,\u0006 לישראל זה\u0005]\u0006 \u0003בכור אחרינא\u0004 \u0005[אחר]\u0006 — \u0003יהיב ניהליה\u0004 \u0005[יתננו לו],\u0006 ולא לכהן אחר, והרי זה ככהן המסייע בבית הגרנות — על כך ישד להשיב: \u0003לא, דמסיק אדעתיה\u0004 \u0005[שמעלה\u0006 הכהן \u0005על דעתו]\u0006 שלא כדאי לו לוותר על דבר הנמצא בידו (הבכור), למען דבר שיכול להיות בעתיד (בכור אחר)."],["שהרי האמרה הרווחת בפי העם: \u0003בוצינא טב מקרא\u0004 \u0005[קישוא\u0006 שכבר בשל כעת, למרות קוטנו, \u0005טוב מדלעת\u0006 גדולה שתבשיל לאחר זמן\u0005].\u0006","נאמר בתורה בדין התמורה \"לא יחליפנו ולא ימיר אותו טוב ברע או רע בטוב ואם המר ימיר בהמה בבהמה והיה הוא ותמורתו יהיה קודש\" (ויקרא כז, י), ומפרטים עתה באלו בהמות של הקדש על אלו בהמות של חולין מתקיים דין זה. \u0003ממירין\u0004 מבהמת הקדש שהיא \u0003מן הצאן\u0004 (בהמה דקה, כגון כבשים ואילים) של קודש \u0003על\u0004 \u0003הבקר\u0004 (בהמה גסה, כגון שור ופרה) של חולין. \u0003ו\u0004כן ממירים \u0003מן הבקר על הצאן. ו\u0004ממירים אף בין הצאן עצמם \u0003מן הכבשים על העזים, ו\u0004כן \u0003מן העזים על הכבשים.\u0004 וממירים \u0003מן הזכרים על הנקבות, ו\u0004כן \u0003מן הנקבות על הזכרים.\u0004 שכל אלה בכלל \"בהמה\". וממירים \u0003מן\u0004 בהמות הקדש \u0003התמימים\u0004 (שאין בהם מום) \u0003על\u0004 בהמות חולין שהן \u0003בעלי מומין,\u0004 וכן ממירים \u0003מן בעלי מומין על התמימים.\u0004","וטעמה של הלכה זו — שכן אף \u0003שנאמר: \"לא יחליפנו ולא ימיר אתו טוב ברע או רע בטוב\"\u0004 — ובהמה שאין בה מום הריהי בכלל \"טוב\" וזו שיש בה מום הריהי בכלל \"רע\". ו\"טוב ברע\" הוא איפוא תמים של חולין בבעל מום של קודש, ו\"רע בטוב\" הוא בעל מום של חולין בתמים של קודש — מכל מקום נאמר בכתוב: \"והיה הוא ותמורתו יהיה קודש\". \u0003ו\u0004מגדירים: \u0003איזהו\u0004 (מיהו) בעל מום (\"רע\"). זה שנאמר בו \u0003\"טוב ברע\"\u0004 — אלו \u0003בעלי מומין שקדם הקדישן את מומן,\u0004 כלומר, שלאחר שהוקדשו נפל בהם מום. ורק בהמת הקדש בעלת מום שכזה, ממירים ממנה על בהמת חולין. ואולם בהמה בעלת מום שהוקדשה לאחר שנפל בה מום — אינה עושה תמורה. ואם המיר בה בהמת חולין — לא חל עליה דין תמורה.","שנינו במשנתנו אלו הן הבהמות (של ההקדש ושל החולין) שמתקיים בהן דין התמורה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים הללו]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בתורה \"ואם המר ימיר \u0003בהמה בבהמה\u0004 והיה הוא ותמורתו יהיה קודש\" (ויקרא כז, י) — \u0003מכאן שממירין מן הצאן על הבקר, ומן הבקר על הצאן.\u0004 וכן ממירים \u0003מן הכבשים על העזים, ומן העזים על הכבשים. ו\u0004כן \u0003מן הזכרים על הנקבות, ומן הנקבות על הזכרים. ומן בעלי מומין על התמימים, ומן התמימים על בעלי מומין\u0004 שכל אלה בכלל \"בהמה\".","ויש לברר: \u0003יכול\u0004 נוהג דין זה שממירים מבהמת הקדש בעלת מום \u0003אפילו\u0004 אם \u0003קדם\u0004 ה\u0003מום להקדישן,\u0004 ולא רק זו שנפל בה מום אחר כך? — \u0003תלמוד לומר\u0004 (משמיענו הכתוב) בפסוק זה: \u0003\"לא יחליפנו ולא ימיר אתו טוב ברע או רע בטוב\", ואיזהו\u0004 האופן בו מתקיים המרת \u0003\"טוב ברע\"?\u0004 — אלו \u0003בעלי מומין שקדם הקדישן את מומן.\u0004","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד,\u0006 כיצד נלמד הדבר מהכתוב\u0005]?\u0006 \u0003אמר אביי\u0004 בהסבר הדרשה: \u0003נימא קרא\u0004 \u0005[יאמר הכתוב]\u0006 \u0003\"לא יחליפנו ולא ימיר אתו טוב ברע או רע בו\",\u0004 ויובן הדבר שהכוונה להמרת רע בטוב, ומעתה יש לשאול: המלה \u0003\"בטוב\" אחרינא\u0004 \u0005[האחרת,\u0006 הנוספת\u0005]\u0006 \u0003למה לי\u0004 (מה היא מלמדת)? \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי לא כל קרבן שהוא בגדר \"טוב\" הריהו בכלל דין התמורה, אלא דווקא זה המוגדר כ\u0003טוב מעיקרו,\u0004 שלא היה בו מום מתחילתו, אלא שנפל בו לאחר שהקדישו — הוא זה ש\u0003עושה\u0004 בהמת חולין \u0003תמורה.\u0004 אבל קרבן המוגדר כ\u0003רע מעיקרו,\u0004 שהיה בו מום מתחילתו — \u0003אין עושה תמורה.\u0004","\u0003רבא אמר\u0004 הסבר אחר בדרשה זו: \u0003תרווייהו\u0004 \u0005[שניהם]\u0006 שתי המילים \u0003\"טוב\"\u0004 הכתובות בפסוק זה הריהן \u0003ייתורי מייתרי\u0004 \u0005[מיותרות],\u0006 וללמד באו. שהרי אם אין שני הכתובים הללו משמיעים חידוש דין, \u0003אם כן, נכתוב קרא\u0004 \u0005[\u0006די \u0005שתכתוב התורה]\u0006 \u0003\"לא יחליפנו ולא ימיר אותו ברע או רע בו\",\u0004 ויהיה מובן הדבר כי המלה \"אותו\" (שבכתוב \"אותו ברע\") הריהי ניגודו של הרע, וכן המלה \"בו\" (שבכתוב \"או רע בו\"). ו\u0003למה לי למכתב תרוייהו\u0004 \u0005[לכתוב\u0006 את \u0005שתי]\u0006 המילים \u0003\"טוב\"?\u0004 — להשמיענו שני דברים: \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 \u0003\"טוב\"\u0004 מלמדנו ש\u0003אפילו\u0004 זה הממיר טוב \u0003בטוב,\u0004 כלומר, בהמת קודש תמימה בבהמת חולין תמימה \u0003נמי\u0004 \u0005[גם כן],\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 הוא \u0003ממיר\u0004 — הריהו \u0003לקי\u0004 \u0005[לוקה]\u0006 על כך. \u0003ואידך\u0004 \u0005[והאחר,\u0006 ה\"טוב\" הנוסף\u0005]\u0006 מלמדנו כי דווקא קרבן שהוא \u0003טוב מעיקרו,\u0004 שלא היה בו מום בתחילתו, ורק לאחר הקדשו נפל בו מום — הוא זה ש\u0003עושה תמורה,\u0004 אבל זה שהוא \u0003רע מעיקרו\u0004 כשנולד בעל מום — \u0003אין עושה תמורה.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003אביי\u0004 שאין בכתוב זה אלא \"טוב\" אחד מיותר, המלמד לענין המרה מבעלת מום שלא היה המום בבהמה מתחילתה, מנין לו שגם הממיר טוב בטוב לוקה על כך? \u0003אמר\u0004 אביי: אין צורך לדרשת כתוב מיוחדת להשמיענו זאת, שהרי \u0003קל וחומר הוא\u0004 המלמדנו זאת. ובאופן זה: \u0003ומה\u0004 הממיר \u0003טוב ברע,\u0004 כלומר, בהמה תמימה של חולין (\"טוב\") במקום בהמה בעלת מום של קודש (\"רע\") \u0003דעלויי קא מעלי ליה\u0004 \u0005[שלהעלות הוא מעלה אותו],\u0006 שהרי את בהמת הקודש לא היה יכול להקריב ואילו את תמורתה כן — הריהו \u0003לקי\u0004 \u0005[לוקה]\u0006 על כך. זה הממיר \u0003טוב בטוב, דכי הדדי נינהו\u0004 \u0005[שכמו\u0006 שווים \u0005הם זה לזה],\u0006 שהרי שניהם טובים ואין תועלת כלשהי במעשהו — \u0003לא כל שכן דלקי\u0004 \u0005[שלוקה]\u0006 על כך!","וחוזרים ושואלים: \u0003ורבא\u0004 הסבור שיש כתוב מיוחד המלמדנו שלוקה הממיר טוב בטוב, מדוע לא נלמד הדבר מקל וחומר זה? ומשיבים: אין דינו של הממיר טוב בטוב יכול להילמד מקל וחומר, כי כלל הוא: \u0003אין עונשין מן הדין\u0004 (על סמך מידת קל וחומר בלבד), ועל מנת להענישו נדרש כתוב מיוחד. ושואלים: \u0003ואביי\u0004 שלמד שלוקה הממיר טוב בטוב מקל וחומר, מה הוא משיב לטענה זו? ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 אביי בתשובה: \u0003הא\u0004 \u0005[\u0006דין \u0005זה]\u0006 שלוקה הממיר טוב בטוב — \u0003לאו דינא\u0004 \u0005[לא\u0006 נלמד מן \u0005הדין,\u0006 מקל וחומר\u0005]\u0006 \u0003הוא.\u0004 אלא מן הסברה הפשוטה, שכן \u0003מי גרע\u0004 \u0005[האם גרוע]\u0006 הממיר \u0003טוב\u0004 של הקדש \u0003מ\u0004זה הממיר \u0003רע\u0004 של הקדש?! וכשם שלוקה הממיר מרע על הטוב, כן לוקה הממיר מטוב על טוב.","ועוד בדיני התמורה הנלמדים מפסוק זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"לא יחליפנו\"\u0004 — זו התמורה \u0003ב\u0004בהמתם \u0003של אחרים, \"ולא ימיר אתו\"\u0004 — זו התמורה \u0003ב\u0004בהמה \u0003של עצמו.\u0004 שבשני המקרים אסור לו להמיר, ואם המיר הרי זו תמורה. ושואלים: \u0003ולכתוב\u0004 \u0005[ותכתוב]\u0006 התורה רק \u0003\"לא יחליפנו\", ולא בעי\u0004 \u0005[ולא צריך]\u0006 לכתוב גם \"ו\u0003לא ימיר אתו\",\u0004 ואנו נדע שאף הממיר בשל עצמו לוקה, שהרי אין חמור זה הממיר בשל אחרים מזה הממיר בשל עצמו!","ומשיבים: \u0003אי כתב הכי\u0004 \u0005[אם היה כתוב כך,\u0006 \"לא יחליפנו\" בלבד\u0005]\u0006 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 כי רק זה הממיר באופן שאומר \u0003\"תצא זו\u0004 בהמת ההקדש מקדושתה לחולין \u0003ותכנס זו\u0004 בהמת החולין במקומה\" \u0003הוא דתילקי\u0004 \u0005[שלוקה]\u0006 על המרתו, כיון שהתכוון להוציא הקדש לחולין. \u0003אבל\u0004 זה ה\u0003ממיר\u0004 באופן שאומר \"זו תמורת זו\", \u0003דתרווייהו קא מקדיש להו\u0004 \u0005[ש\u0006בדרך זו את \u0005שתיהן הוא מקדיש אותן],\u0006 ולא התכוון להוציא את בהמת ההקדש לחולין — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא לקי\u0004 \u0005[אינו לוקה]\u0006 על כך. לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב \"ולא ימיר אותו\", שאף באופן זה הריהו לוקה.","ודנים עתה בגופם של דברים. מהכתוב \"לא יחליפנו\" למדים לענין התמורה בבהמתם של אחרים. ומבררים: \u0003האי\u0004 \u0005[\u0006מקרה \u0005זה]\u0006 של תמורה \u0003ב\u0004בהמתם \u0003של אחרים, היכי דמי\u0004 \u0005[כיצד בדיוק המדובר]?\u0006 \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שמדובר במקרה שה\u0003בהמה\u0004 של ה\u0003הקדש,\u0004 היא \u0003דידיה\u0004 \u0005[שלו]\u0006 של הממיר, \u0003ו\u0004בהמת ה\u0003חולין\u0004 בה הוא ממיר, היא \u0003דעלמא\u0004 \u0005[של העולם,\u0006 אנשים אחרים\u0005],\u0006 הרי נמצא שמקדיש בהמה של אחרים, ועל כך יש לתהות: \u0003מי מצי מקדיש\u0004 \u0005[האם יכול\u0006 הוא \u0005להקדיש],\u0006 והרי \u0003\"איש כי יקדש את ביתו קדש לה'\"\u0004(ויקרא כז, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ולמדנו מכתוב זה כלל לענין ההקדשות: \u0003מה ביתו\u0004 — הריהו \u0003ברשותו\u0004 של המקדיש, \u0003אף כל\u0004 דבר שהוא מקדיש — צריך להיות \u0003ברשותו,\u0004 ואין אדם מקדיש דבר שאינו ברשותו! \u0003ואלא\u0004 תאמר שמדובר במקרה שה\u0003בהמה\u0004 של ה\u0003הקדש\u0004 היא \u0003דעלמא\u0004 \u0005[של האחרים],\u0006 \u0003ו\u0004בהמת ה\u0003חולין\u0004 היא \u0003דידיה\u0004 \u0005[שלו]\u0006 — אף על כך יש לתהות: \u0003מי\u0004 \u0005[האם]\u0006 אדם \u0003מתפיס\u0004 (מחיל) קדושה לבהמת החולין שלו מ\u0003דבר שאינו שלו.\u0004","ומשיבים: \u0003לעולם\u0004 מדובר \u0003בבהמה\u0004 של ה\u0003הקדש\u0004 שהיא דעלמא \u0005[של האחרים],\u0006 \u0003ו\u0004בהמת ה\u0003חולין\u0004 שהיא \u0003דידיה\u0004 \u0005[שלו],\u0006 ואשר לשאלה כיצד הוא מתפיס מדבר שאינו שלו, יש להשיב כי מדובר \u0003כגון\u0004 ש\u0003אמר מריה\u0004 \u0005[הבעלים]\u0006 של ה\u0003בהמה\u0004 של ה\u0003הקדש\u0004 ש\u0003כל הרוצה להמיר בבהמתו\u0004 — \u0003יבא וימיר.\u0004 ובדרך זה, יכול אדם להתפיס אף בדבר שאינו שלו.","\u0003ממירין\u0004 בהמה \u0003אחד\u0004 של חולין \u0003בשנים\u0004 של הקדש, וכגון שאמר \"הרי בהמה זו תחת בהמות אלו\". \u0003ו\u0004כן \u0003שנים\u0004 של חולין ממירים \u0003באחד\u0004 של הקדש. וכן ממירים \u0003אחד\u0004 של חולין \u0003במאה\u0004 של הקדש, \u0003ו\u0004כן \u0003מאה\u0004 של חולין \u0003באחד\u0004 של הקדש. \u0003ר' שמעון אומר: אין ממירין אלא אחד\u0004 של חולין \u0003באחד\u0004 של הקדש, \u0003ש\u0004כן \u0003נאמר:\u0004 \"ואם המר ימיר בהמה בבהמה \u0003והיה הוא ותמורתו יהיה קדש\"\u0004 (ויקרא כז, י). ו\u0003מה\u0004 משמעו של לשון \u0003\"הוא\"\u0004 — זה ה\u0003מיוחד,\u0004 שדובר בבהמה אחת בלבד, \u0003אף היא\u0004 (בהמת התמורה) — \u0003מיוחדת,\u0004 ומכאן שאין ממירים אלא בהמה אחת בבהמה אחת.","לענין מחלוקתם של חכמים ור' שמעון שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים,\u0006 מהו מקור השיטות הללו\u0005]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]:\u0006 נאמר בדין התמורה \"ואם המר ימיר \u0003בהמה בבהמה\u0004 והיה הוא ותמורתו יהיה קודש\", ו\u0003מכאן\u0004 למדים אנו \u0003שממירין\u0004 אף \u0003אחד בשנים, ו\u0004כן \u0003שנים באחד,\u0004 ואפילו אחד במאה, ומאה באחד. שבכל דרך מועילה התמורה. \u0003ר' שמעון אומר: אין ממירין אלא אחד באחד, ש\u0004כן \u0003נאמר\u0004 בכתוב זה \u0003\"בהמה בבהמה\"\u0004 בלשון יחיד, לומר שאין ממירים אלא אחד באחד, \u0003ולא בהמה בבהמות, ולא בהמות בבהמה.\u0004","\u0003אמר לו\u0004 החולק עליו (חכמים): והרי \u0003מצינו\u0004 (מצאנו) במקרא ב\u0003בהמות\u0004 רבות \u0003ש\u0004אף הן \u0003קרויה \"בהמה\",\u0004 בלשון יחיד, \u0003ש\u0004כן \u0003נאמר \"ובהמה רבה\"\u0004 (יונה ד, יא)! ושואלים: \u0003ור' שמעון\u0004 שלמד מכתוב זה שאין הכוונה אלא לבהמה אחת, מה הוא משיב על טענה זו? ומשיבים: בהמות רבות — בלשון \u0003\"בהמה רבה\" איקרי\u0004 \u0005[נקראת],\u0006 אבל בלשון \u0003\"בהמה\" סתם\u0004 — \u0003לא איקרי\u0004 \u0005[אינה נקראת].\u0006","ושואלים: \u0003ו\u0004האם \u0003טעמא\u0004 \u0005[הטעם,\u0006 המקור לשיטתו\u0005]\u0006 של \u0003ר' שמעון משום\u0004 שנאמר \u0003\"בהמה\"\u0004 בלשון יחיד \u0003הוא? והא טעמא\u0004 \u0005[והרי הטעם]\u0006 של \u0003ר' שמעון משום\u0004 הנאמר בכתוב זה \"והיה \u0003הוא\u0004 ותמורתו\", שדרש בו: \u0003מה הוא\u0004 בהמת ההקדש — \u0003מיוחד, אף\u0004 בהמת ה\u0003תמורה מיוחדת!\u0004","ומשיבים: \u0003מעיקרא\u0004 \u0005[מלכתחילה]\u0006 \u0003אמר להן ר' שמעון\u0004 לחכמים שמקור שיטתו הוא \u0003מן\u0004 הכתוב \u0003\"והיה הוא ותמורתו\"\u0004 (כמובא במשנתנו), \u0003ו\u0004אולם \u0003כי חזא דדרשי רבנן\u0004 \u0005[כאשר ראה שדורשים חכמים]\u0006 החולקים עליו את דינם \u0003מ\u0004הכתוב \u0003\"בהמה בבהמה\"\u0004 (כמובא בברייתא זו) \u0003אמר להם איהו\u0004 \u0005[הוא]:\u0006 \u0003מהתם נמי מצינן למילף טעמא דידי\u0004 \u0005[משם,\u0006 מהכתוב \"בהמה בבהמה\", \u0005גם כן יכולים אנו ללמוד\u0006 את \u0005הטעם שלי,\u0006 המקור לשיטתי\u0005].\u0006","\u0003אמר ריש לקיש:\u0004 אף שאין ממירים לדעת ר' שמעון אלא בהמה אחת של חולין בבהמה אחת של הקדש, מכל מקום \u0003מודה ר' שמעון שממירין\u0004 בהמת חולין על בהמה אחת של הקדש, \u0003וחוזרין וממירין\u0004 שוב בהמה אחרת של חולין על אותה בהמה של הקדש, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — שכן \u0003קדושה ראשונה\u0004 של בהמת ה\u0003הקדש להיכן הלכה?!\u0004 שהרי אף שהמירו עליה בפעם הראשונה וחלה קדושה על בהמת החולין, קדושת בהמת ההקדש במקומה עומדת, ולכן אפשר שוב להמיר עליה. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 בשיטת ר' שמעון ש\u0003כשם שאין ממירין שנים באחד\u0004 — \u0003כן אין ממירין וחוזרין וממירין\u0004 על אותה בהמת הקדש.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא אחת \u0005כשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא אחרת \u0005כשיטתו]\u0006 של \u0003ריש לקיש.\u0004 ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: כשם שאין ממירין אחד בשנים\u0004 — \u0003כך אין ממירין וחוזרין וממירין\u0004 על אותה בהמת הקדש. \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא אחרת \u0005כשיטתו]\u0006 של \u0003ריש לקיש: יכול כשם שאמר ר' שמעון שאין ממירין שנים באחד, כך\u0004 סבור הוא שאף \u0003אין ממירין וחוזרין וממירין\u0004 על אותה בהמת הקדש — \u0003תלמוד לומר: \"והיה הוא ותמורתו\"\u0004 — \u0003אפילו במאה\u0004 של בהמות חולין, בכל פעם המיר אחת באחת.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבין: לדברי\u0004 ר' יוחנן \u0003האומר\u0004 בשיטת ר' שמעון ש\u0003אין ממירין וחוזרין וממירין\u0004 על אותה בהמת הקדש, אם \u0003הפריש\u0004 אדם בהמה לקרבן \u0003אשם\u0004 כדי \u0003להתכפר בו ו\u0004לאחר מכן \u0003המיר בו\u0004 בהמת חולין,"],["\u0003ו\u0004לאחר מכן \u0003הומם\u0004 (נפל בו מום) בקרבן הראשון, \u0003וחללו על\u0004 \u0003אחר\u0004 (בהמה אחרת). ולאחר מכן אבד אותו קרבן שני, \u0003ו\u0004עמד ו\u0003נתכפר ב\u0004קרבן \u0003אשם אחר\u0004 (שלישי) שהביא במקום זה שאבד, ואחר כך נמצא הקרבן שאבד (השני). ומכיון שכבר התכפרו הבעלים, מעתה דינו של הקרבן השני שהוא \u0003ניתק\u0004 (נעתק) \u0003ל\u0004היות כקרבן \u0003עולה,\u0004 כדין אשם שנתכפרו בעליו שמוקרב כעולת נדבה. ויש לשאול: קרבן זה, \u0003מהו\u0004 לענין \u0003שימיר בו\u0004 בהמת חולין, האם כיון שקדושתו באה מכח הקרבן הראשון, אם כן הוא בכלל דין \"אין ממירים וחוזרים וממירים\" ולא ימירו בו, או שמא כיון שקרבן זה הריהו אחר, הן משום שהוא בהמה אחרת, והן משום שהוא קדוש בקדושה אחרת (שהראשון היה אשם, והשני עולה) — ממירים בו.","\u0003אמר אביי: מאי קא מיבעיא ליה\u0004 \u0005[מה\u0006 עיקרה של השאלה ש\u0005נשאלה לו,\u0006 לר' אבין\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 עיקר השאלה הוא כאשר יש \u0003שני גופים\u0004 (שתי בהמות הקדש, הקרבן המקורי שנפל בו המום, וזה שהתחלל עליו) \u0003וקדושה אחת\u0004 (ששניהם אשם, שלפני שנתכפר בשלישי לשני דין אשם כמו לראשון) — \u0003תיבעי ליה\u0004 \u0005[תישאל לו]\u0006 שאלתו אף \u0003בלא\u0004 אופן מורכב זה שאבד הקרבן השני, והפריש קרבן שלישי שבו הוא \u0003מתכפר\u0004 ולאחר מכן נמצא השני. אלא באופן פשוט: שלא אבד הקרבן השני, והשאלה היא האם ממירים עליו משום שגוף נפרד הוא מהראשון, או שאין ממירים עליו משום שקדושה אחת לו ולקרבן הראשון.","ומצד שני \u0003אי\u0004 \u0005[אם]\u0006 עיקר השאלה הוא משום שיש \u0003שתי קדושות\u0004 (שבתחילה היה אשם ועכשיו הריהו עולה), \u0003ו\u0004אף ששתי הקדושות הללו הן ב\u0003גוף אחד\u0004 (באותה בהמה) — \u0003תיבעי ליה\u0004 \u0005[תישאל לו]\u0006 לר' אבין שאלתו אף \u0003בלא\u0004 אופן זה ש\u0003הומם\u0004 הקרבן הראשון, וחיללו עליו את זה השני, ובאופן פשוט יותר: שאבד הקרבן הראשון (לאחר שהמיר בו), והקריבו תחתיו קרבן אחר לאשם, ולאחר מכן נמצא הקרבן הראשון, שדינו שהוא ניתק לעולה. והשאלה היא: האם ממירים על הקרבן הראשון (שנשתנתה קדושתו), או שאין ממירים עליו (משום שהריהו אותה בהמה).","\u0003ו\u0004משיבים: שאלה זו של \u0003ר' אבין,\u0004 שתי שאלות הבאות כ\u0003חדא מגו חדא\u0004 \u0005[אחת מתוך אחת],\u0006 כלומר, בעיה אחת העולה מתוך בעיה אחרת, שפתרון הבעיה הראשונה מעלה בעיה אחרת \u0003קמיבעיא ליה\u0004 \u0005[היא\u0006 ש\u0005נשאלה לו].\u0006 ובאופן זה: תחילה אכן שאל האם נוהג דין תמורה במקרה זה של שני גופים וקדושה אחת (כהצעתו הראשונה של אביי), \u0003ו\u0004חזר ואמר: גם \u0003אם תימצי\u0004 (תמצא) \u0003לומר\u0004 במקרה זה של \u0003שני גופין וקדושה אחת\u0004 ש\u0003לא\u0004 נוהג דין תמורה בקרבן השני — יש מקום לומר שהרי זה \u0003משום דבההיא\u0004 \u0005[שבאותה]\u0006 סוג \u0003קדושה הא איתמר\u0004 \u0005[הרי\u0006 כבר \u0005הומרה]\u0006 \u0003בה חדא זימנא\u0004 \u0005[פעם אחת,\u0006 בקרבן האשם הראשון\u0005],\u0006 ואולם עדיין יש מקום לשאול במקרה של \u0003שני גופין ושתי קדושות\u0004 (היא בעיית ר' אבין) \u0003מהו\u0004 הדין? ומסכמים: לא נפתרה השאלה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בהצעת סוגיה זו. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבין: ל\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 שלדברי ר' שמעון \u0003אין ממירין וחוזרין וממירין,\u0004 אם \u0003הפריש\u0004 קרבן \u0003אשם\u0004 על מנת \u0003להתכפר בו, ו\u0004לאחר מכן \u0003המיר בו, ו\u0004לאחר שהמיר בו \u0003הומם\u0004 (נפל בו, בראשון, מום), \u0003וחללו על אחר, מהו\u0004 הדין לענין \u0003שיחזור וימיר\u0004 בקרבן האחר? וצדדי השאלה: מצד אחד הרי הוא גוף אחר מהקרבן הראשון, ויש מקום לומר שבזה ממירים. ומצד שני, הרי זו קדושה אחת, ששניהם קרבן אשם — וכשם שבראשון אין ממירים, אף בו אין ממירים.","ובעיה נוספת: הפריש קרבן לאשם, ואבד הקרבן, והפריש קרבן אחר לאשם, ו\u0003נתכפר באשם\u0004 ה\u0003אחר,\u0004 ולאחר מכן נמצא הקרבן הראשון \u0003ו\u0004הרי \u0003ניתק\u0004 (נעתק) \u0003זה\u0004 (הראשון שאבד ונמצא) \u0003לעולה,\u0004 ושאלה היא: \u0003מהו\u0004 דינו לענין \u0003שיחזיר\u0004 (יחזור) \u0003וימיר\u0004 בו. שכן מצד אחד הרי זה גוף אחד — ואין חוזרים וממירים בו. ומצד שני הרי זו קדושה אחרת (שבתחילה היה אשם, ועכשיו הריהו עולה) — וחוזרים וממירים בו.","\u0003אמר אביי: הי קא מיבעיא ליה\u0004 \u0005[איזה\u0006 חלק בבעייתו של ר' אבין הוא ש\u0005נשאל לו,\u0006 הוא עיקר השאלה\u0005]?\u0006 אם הבעיה העיקרית היא זו בענין \u0003קדושה אחרת באותו הגוף\u0004 (שבתחילה היה אשם ועכשיו הוא עולה) — \u0003לא ניבעי\u0004 \u0005[לא תישאל]\u0006 אחריה הבעיה שבה \u0003הומם\u0004 הראשון \u0003וחללו באחר,\u0004 שהיא מקרה שונה, של גוף אחר וקדושה אחת. ו\u0003אי\u0004 \u0005[אם]\u0006 בעיקרה נשאלה הבעיה במקרה זה של \u0003גוף אחד\u0004 (אחר) \u0003באותה קדושה\u0004 — \u0003לא ניבעי\u0004 \u0005[לא תישאל]\u0006 הבעיה במקרה זה של \u0003נתכפר באשם אחר,\u0004 שעניינה גוף אחד וקדושה אחרת!","\u0003ו\u0004משיבים: שאלה זו של \u0003ר' אבין,\u0004 הריהי שתי שאלות, הבאות כ\u0003חדא מגו חדא\u0004 \u0005[אחת מתוך אחת],\u0006 כלומר, בדרך של פתרון בעיה אחת המעלה בעיה אחרת \u0003קא מיבעיא ליה\u0004 \u0005[היא\u0006 ש\u0005נשאלה לו],\u0006 ובאופן זה: תחילה שאל: \u0003הומם\u0004 הראשון \u0003וחללו על אחר, מהו\u0004 דינו לענין זה \u0003שיחזור וימיר\u0004 על אותו אשם שני? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי דווקא \u0003באשם ראשון הוא\u0004 ש\u0003אין חוזר וממיר, אבל\u0004 זה הקרבן השני, הקדושה שבו \u0003בגוף אחד\u0004 (לעצמו) היא, ומשום כך, \u0003אף על גב דקדיש\u0004 \u0005[אף על פי ש\u0006הוא \u0005קדוש]\u0006 ב\u0003אותה קדושה\u0004 (אשם) כקדושת הקרבן הראשון — דינו ש\u0003חוזר וממיר\u0004 בו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי ב\u0003כל\u0004 אופן הרי הקרבן השני עומד \u0003באותה קדושה,\u0004 \u0005ומשום כך, דינו ש\u0006\u0003אין חוזר וממיר\u0004 בו?","ומתוך בעיה זו, עולה הבעיה הבאה, ובאופן זה: \u0003ו\u0004אף \u0003אם תימצא לומר\u0004 כי \u0003הדין\u0004 \u0005[זה]\u0006 הקרבן השני, אף שהוא \u0003גוף אחד\u0004 (אחר) לעצמו, \u0003כיון\u0004 ש\u0003באותה קדושה\u0004 הוא \u0003קאים\u0004 \u0005[עומד]\u0006 — לכן דינו ש\u0003אין חוזר וממיר\u0004 בו, \u0003אלא\u0004 מעתה נשאל במקרה אחר: מי שהפריש קרבן לאשם, ואבד הקרבן, ו\u0003נתכפר באשם\u0004 ה\u0003אחר, ו\u0004לאחר מכן נמצא קרבן האשם הראשון, ודינו ש\u0003ניתק\u0004 (נעתק) \u0003זה\u0004 הקרבן ה\u0003ראשון ל\u0004היות מוקרב כקרבן \u0003עולה, מהו\u0004 דינו לענין זה \u0003שיחזיר וימיר בו?\u0004","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 נאמר דין זה ש\u0003אין ממיר וחוזר וממיר\u0004 — הרי \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 נאמרו דווקא במקרה של \u0003אותו הגוף\u0004 (הקרבן) ו\u0003באותה קדושה, אבל\u0004 במקרה של \u0003אותו הגוף,\u0004 אבל \u0003בקדושה אחרת\u0004 (כגון זה הקרבן הראשון, שבתחילה היה בקדושת אשם ועתה הוא בקדושת עולה) — דינו ש\u0003חוזר וממיר. או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003אף\u0004 שיש בקרבן זה \u0003קדושה אחרת,\u0004 מכל מקום \u0003כיון\u0004 ש\u0003אותו הגוף הוא\u0004 — לכן דינו ש\u0003אין חוזר וממיר?\u0004 ומסכמים: לא נפתרה הבעיה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","בענין דומה, מובאת בעייה של ר' אבין וקושיית אביי כעין זו שנאמרה למעלה. נושא הדברים הריהו מה ש\u0003אמר ר' יהושע בן לוי:\u0004 הפודה בהמה שהיא \u0003הקדש ראשון\u0004 (כגון, בהמה שהוקדשה לקרבן, ונפל בה מום, שפודים אותה וקונים בדמיה קרבן אחר) — משלם את ערכה של הבהמה, ו\u0003מוסיף\u0004 על כך עוד \u0003חומש\u0004 (חמישית). \u0003ואין\u0004 הפודה בהמה שהיא \u0003הקדש שני\u0004 (כגון, שנפל מום גם בבהמה השניה שעליה חיללו את הקרבן הראשון שנפל בו המום. וכן כגון בהמת חולין שהומרה בבהמת הקדש) \u0003מוסיף חומש,\u0004 והריהו משלם רק את ערכה.","ו\u0003אמר רב פפא\u0004 בהסבר הדברים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לשיטתו זו של \u0003ר' יהושע בן לוי\u0004 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואם המקדיש יגאל את ביתו ויסף חמישית\u0004 כסף ערכך עליו\" (ויקרא כז, טו) — והרי זה בא לדייק: דווקא ה\u0003מקדיש\u0004 (הפודה הקדש ראשון), הוא המוסיף חמישית, \u0003ולא\u0004 זה \u0003המתפיס\u0004 (הפודה את מה שהותפסה בו קדושה, בחילול עליו או בתמורה).","ובדין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבין:\u0004 מי ש\u0003הפריש\u0004 בהמה לקרבן \u0003אשם\u0004 כדי \u0003להתכפר בו,\u0004 \u0003והומם\u0004 (נפל בו מום), ועמד וחיללו, כדינו, על כסף, \u0003והוסיף עליו חומש,\u0004 כדינו של הפודה הקדש ראשון, \u0003וחללו\u0004 לאותו הכסף ב\u0003חבירו\u0004 (בבהמה אחרת, שתוקרב לאשם). ולאחר מכן אבד הקרבן השני, ועמד והפריש בהמה אחרת לאשמו, וקרב אשם זה, \u0003ונתכפר\u0004 הבעלים \u0003באשם\u0004 ה\u0003אחר\u0004 (השלישי). ולאחר מכן נמצא הקרבן השני, \u0003ו\u0004הרי דינו ש\u0003ניתק\u0004 (נעתק) \u0003זה\u0004 הקרבן השני \u0003לעולה,\u0004 ונפל אף בו מום. ומעתה יש לשאול: \u0003מהו\u0004 דינו לענין זה \u0003שיוסיף\u0004 הפודה אותו \u0003עליו\u0004 (בנוסף לערכו) \u0003חומש,\u0004 האם הוא כהקדש ראשון או כהקדש שני?","\u0003אמר אביי:\u0004 במקרה זה, יש לפנינו שני גופים (אשם ראשון, ואשם שני), ושתי קדושות (אשם, ועולה). ואולם יש לברר: \u0003מאי קא מיבעיא ליה\u0004 \u0005[מה היא\u0006 עיקר השאלה ש\u0005נשאלת לו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 בגלל שיש לפנינו \u0003שני גופין, ו\u0004אף שיש לשני הקרבנות הללו \u0003קדושה אחת קא מיבעיא ליה\u0004 \u0005[היא\u0006 עיקר השאלה ש\u0005נשאלה לו]\u0006 — אם כן \u0003תיבעי ליה\u0004 \u0005[תישאל לו]\u0006 שאלתו זו אף \u0003בלא נתכפר\u0004 בקרבן אשם שלישי. כאשר יש לפנינו שני קרבנות (הראשון שנפל בו מום, והשני שבו חולל הראשון), ולשניהם קדושה אחת (אשם).","ו\u0003אי\u0004 \u0005[אם]\u0006 משום שיש לפנינו \u0003שתי קדושות\u0004 (אשם ועולה), \u0003ו\u0004אף ששתיהן ב\u0003גוף אחד\u0004 (בקרבן הראשון) \u0003קא מיבעיא ליה\u0004 \u0005[היא\u0006 עיקר השאלה ש\u0005נשאלה לו]\u0006 — \u0003תיבעי\u0004 \u0005[תישאל\u0006 לו\u0005]\u0006 אם כן אף \u0003ב\u0004מקרה ש\u0003לא הומם\u0004 הקרבן הראשון, אלא שאבד והפרישו אחר תחתיו וקרב השני לאשמו, ולאחר מכן נמצא הראשון, ונעתק לעולה. ולא נצרך ר' אבין להציג את בעייתו באופן מורכב זה של שני גופים ושתי קדושות!","\u0003ו\u0004משיבים: שאלה זו של \u0003ר' אבין,\u0004 הריהי כשתי שאלות הבאות \u0003חדא מגו חדא קמיבעיא ליה\u0004 \u0005[\u0006בעיה \u0005אחת\u0006 העולה \u0005מתוך\u0006 בעיה \u0005אחת נשאלה לו],\u0006 ובאופן זה: תחילה שאל במקרה של שני גופים וקדושה אחת, וחזר ואמר: אף \u0003אם תימצא לומר\u0004 בבעיה זו של \u0003שני גופין וקדושה אחת\u0004 ש\u0003לא\u0004 מוסיף הפודה את הקרבן השני חומש — יש לומר בטעם הדבר \u0003משום דבההיא\u0004 \u0005[שבאותה]\u0006 \u0003קדושה\u0004 כבר \u0003איתוסף\u0004 \u0005[נוסף]\u0006 \u0003בה חדא זימנא\u0004 \u0005[פעם אחת]\u0006 \u0003חומש\u0004 כאשר פדה את הקרבן הראשון שנפל בו מום. אבל במקרה מורכב זה של \u0003שני גופין ושתי קדושות,\u0004 יש לשאול \u0003מאי\u0004 \u0005[מה]\u0006 יהא דינו (של הקרבן השני) לענין תוספת החומש. שהרי מן הצד האחד, הריהו בא מכוחו של הקרבן הראשון, והרי הוא איפוא בכלל \"הקדש שני\" שאין מוסיפים בו חומש. ואולם מן הצד האחר, כיון שהוא גוף אחר ובקדושה אחרת, יש מקום לומר שהוא בכלל \"הקדש ראשון\", והפודה אותו מוסיף חומש. ומסכמים: לא נמצא פתרון לשאלה זו, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 בלא פתרון.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בהצעת מהלך סוגיה זו, ובאופן זה: בשיטת ר' יהושע בן לוי שהפודה הקדש ראשון מוסיף חומש, והפודה הקדש שני אינו מוסיף חומש, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבין\u0004 אם \u0003הפריש\u0004 בהמה לקרבן \u0003אשם\u0004 על מנת \u0003להתכפר בו,\u0004 \u0003והומם\u0004 (נפל בו מום), \u0003וחללו על\u0004 קרבן \u0003אחר, והוסיף חומש,\u0004 כדין, ואבד הקרבן השני, ועמד והפריש קרבן שלישי לאשם, ו\u0003נתכפרו\u0004 הבעלים \u0003באשם\u0004 ה\u0003אחר\u0004 (השלישי). ולאחר מכן נמצא הקרבן השני, \u0003וניתק זה\u0004 הקרבן \u0003לעולה,\u0004 ולאחר מכן נפל בו מום, ובא לפדותו. \u0003מהו\u0004 דינו לענין זה \u0003שיוסיף עליו חומש?\u0004","\u0003אמר אביי: הדין\u0004 \u0005[איזה]\u0006 חלק בבעייתו של ר' אבין \u0003קא מיבעיא ליה\u0004 \u0005[הוא\u0006 ש\u0005נשאל לו\u0006\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 משום שיש כאן \u0003קדושה אחרת באותו הגוף\u0004 (בקרבן השני שהיה בתחילה אשם ועתה הוא עולה) \u0003קא מיבעיא ליה\u0004 \u0005[היא\u0006 ש\u0005נשאלה לו]\u0006 — \u0003לא ניבעי ליה\u0004 \u0005[לא תישאל לו]\u0006 השאלה באופן זה ש\u0003הומם\u0004 הקרבן הראשון וחיללו באחר, שהרי אף במקרה שאבד הראשון והוקרב תחתיו קרבן אחר, ולאחר מכן נמצא, ונעתק כדין מקדושת אשם לקדושת עולה, הרי זה שתי קדושות בגוף אחד! ו\u0003אי\u0004 \u0005[אם]\u0006 עיקר בעייתו היא במקרה של \u0003גוף אחד באותה קדושה\u0004 — אם כן יש לשאול בעיה זו אף בלא שנתכפרו הבעלים בקרבן שלישי!","ומשיבים: ר' אבין שאל שתי שאלות, והאחת נובעת מקודמתה. שבתחילה שאל במקרה שנפל מום בקרבן הראשון, \u0003וחללו על אחר,\u0004 והומם השני ורוצה לפדותו, והשאלה היתה \u0003מהו\u0004 דינו לענין זה \u0003שיוסיף עליו חומש?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי דווקא \u0003באשם קמא\u0004 \u0005[הראשון]\u0006 \u0003הוא\u0004 [שאין (ראה עיונים)] \u0003מוסיף\u0004 חומש, אם יחזור ויחלל עליו, משום שהוא גוף אחד בקדושה אחת, וכבר הוסיף בה חומש בפדיונה. \u0003אבל ב\u0004קרבן השני, שהריהו \u0003גוף אחד\u0004 (לעצמו), \u0003אף על גב דקאים\u0004 \u0005[אף על פי שעומד]\u0006 הוא \u0003באותה קדושה\u0004 של הקרבן הראשון — \u0003[אין\u0004 (ראה עיונים)\u0003]\u0004 הדין כן, אלא שהפודה אותו \u0003מוסיף חומש,\u0004"],["\u0003או דילמא\u0004 \u0005[שמא] יש לומר כי ב\u0006\u0003כל\u0004 אופן הרי זה הקרבן השני ב\u0003אותה קדושה\u0004 כקדושת הראשון הוא עומד, והריהו איפוא כ\"הקדש שני\", ולכן \u0003אינו מוסיף\u0004 בפדיונו \u0003חומש.\u0004","ומתוך הבעיה הזו עולה הבעיה הבאה: \u0003ו\u0004אף \u0003אם תימצא לומר\u0004 כי \u0003הדין\u0004 \u0005[זה],\u0006 הקרבן השני, אף שהוא \u0003גוף אחד\u0004 (אחר) לעצמו, \u0003כיון\u0004 ש\u0003באותה קדושה\u0004 כקדושת הראשון הוא \u0003קאים\u0004 \u0005[עומד]\u0006 — לכן דינו של הפודה אותו [שאין] \u0003מוסיף חומש, אלא\u0004 מעתה יש לשאול במקרה שאבד השני, ו\u0003נתכפר באחר\u0004 (בשלישי), ולאחר מכן נמצא השני \u0003ו\u0004דינו ש\u0003ניתק זה ל\u0004היות מוקרב כקרבן \u0003עולה\u0004 ונפל בו מום ורוצה לפדותו. ומעתה יש לשאול: \u0003מהו\u0004 דינו לענין תוספת החומש בפדיונו? וצדדי השאלה: האם אומרים אנו: \u0003כי\u0004 \u0005[כאשר]\u0006 נאמר דין זה שהקדש שני [אינו] \u0003מוסיף חומש\u0004 — הרי זה רק \u0003ב\u0004מקרה של \u0003אותו הגוף\u0004 (הבהמה) והוא גם קדוש \u0003באותה קדושה. אבל\u0004 במקרה שהוא אותו הגוף, ועתה הוא קדוש \u0003בקדושה אחרת\u0004 (כגון קרבן זה שבתחילה היה אשם, ועתה הוא עולה) — \u0003לא\u0004 מוסיפים חומש בפדיונו. \u0003או דילמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003כיון\u0004 ש\u0003אותו הגוף הוא\u0004 — הרי דינו ש\u0003מוסיף חומש\u0004 בפדיונו? ומסכמים: לא נפתרה הבעיה ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 כפי שהיא.","ועוד בדין החומש של הפודה קרבן שנפל בו מום. למדנו שאם הבעלים עצמם פודים את ההקדש — הריהם מוסיפים חומש על ערכו, ואם אחרים הם הפודים את ההקדש — אינם מוסיפים חומש. ומעתה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 במקרה שאדם הקדיש קרבן לכפרת חבירו, ונפל בקרבן זה מום, מי משני אלה נחשב כבעל הקרבן, שדינו שמוסיף חומש בפדיונו, האם ה\u0003מקדיש\u0004 ולכן הוא זה ש\u0003מוסיף\u0004 את ה\u0003חומש\u0004 בעת הפדיון, \u0003או\u0004 זה שעליו הקרבן \u0003מכפר\u0004 ולכן הוא זה ש\u0003מוסיף\u0004 את ה\u0003חומש? אמר רבא\u0004 בפתרון בעיה זו: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת פדיון הקדשים: \u0003\"ואם המקדיש יגאל את ביתו\u0004 ויסף חמישית כסף ערכך עליו והיה לו\" (ויקרא כז, טו) — והרי זה בא להורות: דווקא ה\u0003מקדיש\u0004 הוא המוסיף חומש בפדיון ההקדש, \u0003ולא\u0004 ה\u0003מתכפר.\u0004","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא\u0004 בענין דומה. למדנו שאין אדם עושה תמורה אלא בקרבן שלו. והשאלה היא במי שמקדיש קרבן לכפרת חבירו, מי מהם הוא הנחשב לבעלי הקרבן לענין תמורה. האם ה\u0003מקדיש\u0004 הוא ה\u0003עושה\u0004 בו \u0003תמורה, או\u0004 ה\u0003מתכפר\u0004 הוא ה\u0003עושה\u0004 בו \u0003תמורה? אמר רבא\u0004 בפתרון בעיה זו: מן הסברה יש לומר שהמתכפר הוא זה שעושה תמורה. שהרי אם נאמר שהמקדיש הוא העושה בו תמורה, \u0003אם כן, מצינו\u0004 (מצאנו) אופן שבו אף ה\u0003ציבור ו\u0004כן ה\u0003שותפין עושין תמורה,\u0004 ו\u0003כגון דשוו\u0004 \u0005[שעשו,\u0006 שמינו\u0005]\u0006 הציבור או השותפים, אדם שישמש עבורם כ\u0003שליח לאקדושי\u0004 \u0005[להקדיש]\u0006 קרבן לכפרתם. שהרי שנינו במשנה בסוף פרקנו שאין הציבור והשותפים עושים תמורה. ואם נאמר שהמקדיש הוא שעושה תמורה ולא המתכפר, הרי אותו שליח המקדיש הוא יחיד, ויחיד יכול לעשות תמורה!","\u0003ועוד\u0004 הוכחה לדבר, שהרי \u0003אמר רב נחמן,\u0004 \u0003אמר רב הונא, תנא\u0004 \u0005[שנינו]\u0006 ברייתא על האמור בסוף פרשת הנזיר, נאמר: \"זאת תורת הנזיר אשר ידור \u0003קרבנו לה' על נזרו מלבד אשר תשיג ידו\u0004 כפי נדרו אשר ידור\" (במדבר ו, כא). ויש לשאול על הנאמר בכתוב זה: \u0003וכי נזיר נידון בהשג יד\u0004 (בדין \"קרבן עולה ויורד\", הבא על פי יכולתו הכספית של המקריב)? והלא קרבנו קבוע! \u0003הא\u0004 \u0005[הרי]\u0006 כיצד יובן הכתוב? אלא יש לומר כי חלק הפסוק האומר \"אשר ידור \u0003קרבנו לה' על נזרו\"\u0004 — עניינו בקרבן הנזיר \u0003שהפריש משלו.\u0004 ואילו חלק הפסוק האומר \u0003\"מלבד אשר תשיג ידו\"\u0004 — עניינו בקרבן הנזיר \u0003שהפרישו לו אחרים.\u0004","ומעתה יש לברר: \u0003למאי הילכתא\u0004 \u0005[למה,\u0006 ללמדנו איזו \u0005הלכה]\u0006 נשנו דברים אלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לענין\u0004 ה\u0003כפרה,\u0004 שהנזיר מתכפר בקרבן שהפרישו עבורו אחרים — אין צורך להשמיענו זאת, שהרי \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור ומובן\u0005]\u0006 ש\u0003מכפר ליה\u0004 \u0005[לו]\u0006 קרבן זה, שהרי ניתן לו קרבן זה במתנה לשם כך! \u0003אלא\u0004 ודאי \u0003לענין\u0004 דין ה\u0003תמורה\u0004 בא כתוב זה ללמדנו, \u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003אף כשהפרישו לו אחרים\u0004 קרבן משלהם— נחשב הוא כבעל הקרבן והוא ה\u0003עושה תמורה,\u0004 ולא הם. ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי לענין תמורה \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מתכפר אזלינן\u0004 \u0005[אנו הולכים],\u0006 והרי זו תשובה לבעייתו זו של רמי בר חמא!","ודוחים: \u0003לא,\u0004 אין להביא ראיה מברייתא זו \u0003לענין\u0004 דין ה\u0003תמורה\u0004 שכן הברייתא עוסקת בדין כפרה. \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 שאין צורך בכתוב להשמיענו שמתכפר בקרבן שהפרישו עבורו אחרים, שכן \u0003מתנה\u0004 היא זו \u0003דקא יהבין ליה\u0004 \u0005[שאנו נותנים לו]\u0006 — אפשר להשיב על כך: \u0003אי לאו דרבי רחמנא\u0004 \u0005[אלמלא שריבתה התורה]\u0006 בכתוב \u0003\"מלבד אשר תשיג ידו\"\u0004 ללמד שמתכפר בקרבן שהופרש עבורו על ידי אחרים, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003גזירת הכתוב הוא\u0004 שלשון \u0003קרבנו\u0004 שהיא לשון מיעוט באה ללמד שרק קרבן הבא \u0003מדידיה\u0004 \u0005[משלו]\u0006 \u0003הוא\u0004 ש\u0003מכפר\u0004 עליו, ואולם הבא \u0003מ\u0004של \u0003אחרים\u0004 — \u0003לא\u0004 מכפר עליו. לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \"מלבד אשר תשיג ידו\", \u0005משמיע לנו]\u0006 שאף בזה הריהו מתכפר.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 כיצד נפתרה הבעיה\u0005]\u0006 של רמי בר חמא? ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע\u0006 פתרון\u0005]\u0006 לדבר ממה שאמר ר' אבהו, \u0003אמר ר' יוחנן\u0004 בדיניו של המקדיש קרבן עבור חבירו: בפדיון קרבן זה — ה\u0003מקדיש\u0004 הוא ש\u0003מוסיף חומש\u0004 בפדיונו, ולא המתכפר. \u0003ו\u0004הלכה נוספת: ה\u0003מתכפר\u0004 הוא ה\u0003עושה תמורה\u0004 בקרבן זה, ולא המקדיש.","והלכה נוספת בענין דומה: התורם מתבואה \u0003שלו על\u0004 תבואתם \u0003של אחרים\u0004 — \u0003טובת הנאה\u0004 (הרווח אותו הוא עשוי לקבל מן המקבל בשל העדפתו אותו) הריהי \u0003שלו.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 להלכה זו שטובת ההנאה היא של הנותן? — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כי תכלה לעשר \u0003את כל מעשר תבואתך... ונתת\u0004 ללוי לגר ליתום ולאלמנה\" (דברים כו, יב), הרי איפוא שזה המוציא מביתו את כל התרומות והמעשרות (ואף אלו שהפריש עבור אחרים), הוא הבוחר למי הן תינתנה. ואם יש לו רווח מזה, הריהו שלו.","\u0003אין ממירין\u0004 (אין דין תמורה חל) \u0003לא\u0004 ב\u0003אברין\u0004 של חולין המומרים \u0003בעוברין\u0004 של הקדש. שהאומר על אבר מסויים של בהמת חולין שלו שיהיה תמורת עובר שבמעיה של בהמת הקדש — לא חלה עליו קדושה. \u0003ו\u0004כן \u0003לא\u0004 חל דין תמורה בממיר \u0003עוברין\u0004 של בהמת חולין \u0003באברים\u0004 של בהמת הקדש. שהאומר על עובר שבמעי בהמת חולין שלו שיהיה תמורת אבריה של בהמת הקדש — לא חלה קדושה על העובר. \u0003ולא\u0004 חל דין תמורה בממיר \u0003עוברין\u0004 של בהמת חולין \u0003ו\u0004כן בממיר \u0003אברים\u0004 של בהמת חולין \u0003ב\u0004בעלי חיים של הקדש \u0003שלימים. ו\u0004כמו כן \u0003לא\u0004 חל דין תמורה בממיר בעלי חיים \u0003שלימים\u0004 של חולין \u0003בהן,\u0004 באברים או בעוברים של הקדש.","\u0003ר' יוסי אומר: ממירין אברים\u0004 של חולין \u0003בשלימים\u0004 של הקדש, \u0003אבל לא\u0004 ממירים \u0003שלימים\u0004 של חולין \u0003בהן,\u0004 באברים של הקדש. \u0003אמר ר' יוסי\u0004 טעם לדבריו: \u0003והלא במוקדשין\u0004 (באדם המקדיש בהמת חולין לקרבן), \u0003האומר \"רגלה של\u0004 בהמה \u0003זו עולה\"\u0004 — הדין הוא שנתפשטה קדושה הבאה עם ההקדשה, וכל הבהמה \u0003כולה\u0004 הריהי \u0003עולה.\u0004 ונלמד מכאן ש\u0003אף כשיאמר\u0004 אדם \u0003\"רגלה של זו תחת זו\"\u0004 — תתפשט הקדושה הבאה עם התמורה, ו\u0003תהא\u0004 כל בהמת החולין \u0003כולה תמורה תחתיה.\u0004","שנינו במשנתנו את דינם של עוברים לענין תמורה. ובענין דומה \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדינו של המקדיש עוברים של בהמת חולין להקרבה על המזבח. \u0003בר פדא אמר: אין קדושה חלה על עוברין, ור' יוחנן אמר: קדושה חלה על עוברין.\u0004 ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן\u0004 בשיטתו זו \u0003לטעמיה\u0004 \u0005[לטעמו],\u0006 שכן \u0003אמר ר' יוחנן:\u0004 אדם ש\u0003הקדיש\u0004 בהמה לקרבן \u0003חטאת\u0004 והיתה אותה בהמה \u0003מעוברת, וילדה\u0004 וולד — הרי היא ועוברה בקדושת חטאת, והדבר תלוי בו במי משניהם יתכפר. שאם \u0003רצה\u0004 להתכפר באם — \u0003בה\u0004 הוא \u0003מתכפר,\u0004 ואם \u0003רצה\u0004 להתכפר \u0003בוולדה\u0004 — בו הוא \u0003מתכפר. ו\u0004על השאלה מדוע נצרך ר' יוחנן להשמיענו שקדושה חלה אף על עוברים שתי פעמים, יש להשיב:","\u0003צריכא\u0004 \u0005[נצרך]\u0006 הדבר. משום \u0003דאי אשמעינן בהך קמייתא\u0004 \u0005[שאם היה משמיענו\u0006 רק \u0005בזו הראשונה,\u0006 במקדיש עובר לבדו\u0005]\u0006 — הייתי אומר שדווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שחלה קדושה על העובר, משום \u0003דאקדשיה\u0004 \u0005[שהקדישו]\u0006"],["\u0003לעוברה גופיה\u0004 \u0005[כשלעצמו,\u0006 בלא שהוקדשה אמו\u0005],\u0006 ומשום כך יש מקום לומר שהתקדש העובר בכך, \u0003אבל הכא, דאקדשיה לאימיה\u0004 \u0005[כאן,\u0006 במקרה זה \u0005שהקדישה את אמו\u0006 המעוברת, ולא את העובר עצמו\u0005]\u0006 — היה מקום לומר כי \u0003הא\u0004 \u0005[זה]\u0006 העובר \u0003בכלל אימיה\u0004 \u0005[אמו]\u0006 \u0003לא קדוש\u0004 \u0005[התקדש].\u0006","\u0003ו\u0004מצד שני \u0003אי אשמעינן בתרייתא\u0004 \u0005[אם היה משמיענו\u0006 ר' יוחנן רק את ההלכה \u0005האחרונה,\u0006 במקדיש את האם המעוברת\u0005]\u0006 — הייתי אומר כי דווקא \u0003התם\u0004 \u0005[שם]\u0006 כך \u0003הוא\u0004 שמתקדש העובר שבמעיה, משום \u0003דאקדיש לה\u0004 \u0005[ש\u0006המקדיש \u0005הקדיש אותה]\u0006 \u0003ו\u0004את \u0003כל דאית\u0004 \u0005[שיש]\u0006 \u0003בה,\u0004 ובכלל זה העובר. \u0003אבל הכא, דאקדשיה ליה\u0004 \u0005[כאן, שהקדיש אותו\u0006 כשלעצמו\u0005],\u0006 \u0003כיון דליתיה אבראי\u0004 \u0005[ש\u0006העובר \u0005אינו\u0006 נמצא \u0005מבחוץ\u0006 למעי אמו, שטרם נולד\u0005],\u0006 יש מקום לומר שהעובר \u0003לא קדיש\u0004 \u0005[התקדש].\u0006 לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמרנה שתי הלכותיו אלה של ר' יוחנן.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 ודיון בדברי ר' יוחנן שהמקדיש בהמה מעוברת לחטאת, וילדה, אם רצה — מתכפר בה, ואם רצה — מתכפר בולדה. שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה,\u0006 איזה חידוש דין, \u0005הוא משמיע לנו]\u0006 בדבריו אלו, ש\u0003אם\u0004 \u0003שיירו\u0004 הבעלים לעובר, וכגון שאמר על בהמה מעוברת: \"הרי זו לחטאת ועוברה חולין\" — הריהו אכן \u0003משוייר\u0004 מן הקדושה, \u0003ו\u0004טעם הדבר: משום ש\u0003עובר לאו\u0004 \u0005[לא]\u0006 כ\u0003ירך\u0004 (חלק מגוף) \u0003אמו הוא\u0004 נחשב, אלא כגוף לעצמו. \u0003ו\u0004אולם עדיין יש לשאול: \u0003תרתי\u0004 \u0005[שתיים,\u0006 פעמיים\u0005]\u0006 \u0003למה לי,\u0004 מדוע נצרך ר' יוחנן להשמיע דבר זה, הן במקדיש בהמה מעוברת והן במקדיש עוברים (שקדושה חלה עליהם, כיון שגוף לעצמם הם)?","ומשיבים: \u0003צריכא\u0004 \u0005[צריך].\u0006 שתיאמרנה שתי ההלכות הללו. משום \u0003דאי אתמר בהא\u0004 \u0005[שאם היה נאמר\u0006 רק \u0005בזה,\u0006 במקדיש בהמה מעוברת\u0005]\u0006 — הייתי אומר בהסבר הדבר שהעובר מתקדש \u0003משום דאימיה חזיא לגופיה\u0004 \u0005[שאמו ראויה\u0006 להתקדש \u0005לגופה,\u0006 כשלעצמה\u0005],\u0006 ו\u0003מגו דנחתא\u0004 \u0005[מתוך שירדה,\u0006 שחלה\u0005]\u0006 \u0003קדושה לה\u0004 — \u0003נחתא נמי\u0004 \u0005[ירדה,\u0006 חלה \u0005גם כן]\u0006 \u0003לולד. אבל אידך\u0004 \u0005[\u0006במקרה \u0005האחר,\u0006 במקדיש עוברים עצמם\u0005]\u0006 — \u0003לא\u0004 יתקדשו. לכן \u0003קא משמע לן הדא\u0004 \u0005[הוא משמיע לנו\u0006 גם את \u0005זאת,\u0006 את דין המקדיש עוברים\u0005].\u0006","\u0003ו\u0004מצד שני, \u0003אי אתמר בהא\u0004 \u0005[אם היה נאמר\u0006 רק \u0005בזה,\u0006 במקדיש עוברים\u0005]\u0006 — הייתי אומר בטעם הדבר \u0003משום דקא\u0004 \u0005[שהוא,\u0006 המקדיש\u0005]\u0006 \u0003מפרש\u0004 (אומר במפורש) שתחול \u0003קדושה על הולד,\u0004 ולכן הוא מתקדש. \u0003אבל\u0004 ההלכה \u0003ההיא\u0004 (במקדיש בהמה מעוברת\u0005],\u0006 שלא אמר במפורש שתחול קדושה על העובר — \u0003לא\u0004 יתקדש העובר. לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","ומסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' זירא וקאמר להא שמעתא\u0004 \u0005[והיה אומר את השמועה,\u0006 המחלוקת \u0005הזו\u0006 שבין בר פדא לר' יוחנן בדין המקדיש עוברים\u0005].\u0006 \u0003איתיביה\u0004 \u0005[הקשה עליו]\u0006 \u0003ר' ירמיה לר' זירא\u0004 ממה ששנינו במשנה (לקמן כד,ב): \u0003כיצד מערימין\u0004 \u0003על\u0004 קרבן \u0003הבכור\u0004 להימנע מלתיתו לכהן? — בעוד שהבהמה \u0003המבכרת\u0004 (שטרם ילדה, והולד שיוולד לה אמור להתקדש בקדושת בכור) כל זמן \u0003שהיתה\u0004 עדיין \u0003מעוברת, אומר\u0004 הבעלים: \u0003\"מה שבמעיה של זו,\u0004 אם הוא זכר — הריהו מוקדש לקרבן \u0003עולה\".\u0004 ומעתה אם אכן \u0003ילדה\u0004 \u0003זכר\u0004 — \u0003הרי זו,\u0004 הולד, מוקדש ל\u0003עולה,\u0004 ואינו קדוש בקדושת בכור. \u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 נסיק מכאן ש\u0003קדוש\u0004 \u0005[מתקדש]\u0006 \u0003עובר,\u0004 והרי זו איפוא ראיה לשיטת ר' יוחנן וקושיה על שיטת בר פדא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה: אין ממשנה זו קושיה על שיטת בר פדא, שלשיטתו יש לומר: \u0003כי מתניא ההיא\u0004 \u0005[כאשר נשנתה אותה\u0006 משנה\u0005]\u0006 — הרי זה דווקא במקדיש את העובר של המבכרת \u0003בקדושת דמים\u0004 (שימכר הולד, ויביאו בדמיו קרבן עולה), ובאופן זה אכן חלה הקדושה על העובר, אבל קדושת הגוף (שהוא עצמו יקרב עולה) אינה חלה במקדיש את העובר. חזר ושאל ר' ירמיה את ר' זירא: \u0003מי אלימא\u0004 \u0005[האם\u0006 כה \u0005חזקה]\u0006 היא \u0003קדושת דמים דקא מפקעא ליה\u0004 \u0005[שהיא מפקיעה אותו,\u0006 את העובר\u0005]\u0006 \u0003מן הבכורה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 כמו כן במשנה\u0005]:\u0006 \u0003כל\u0004 ה\u0003קדשים שקדם מום קבוע להקדישן,\u0004 שהקדישם בהיותם בעלי מום, ומתחילה לא נתקדשו כקרבן, אלא כדי למוכרם ולהביא בדמיהם קרבן (הקדוש רק קדושת דמים), \u0003ונפדו\u0004 — הריהם \u0003חייבין בבכורה\u0004 אם היו נקבות וילדו בכור כדין בהמות חולין, \u0003ובמתנות\u0004 (זרוע לחיים וקיבה), כפי שנותנים לכהן מכל בהמת חולין שנשחטה. ונדייק בדברים: \u0003טעמא\u0004 \u0005[\u0006כל \u0005הטעם]\u0006 הוא משום שמדובר \u0003לאחר שנפדו,\u0004 ויצאו לגמרי לחולין, ולכן הם \u0003חייבין\u0004 בבכורה ובמתנות, \u0003אבל קודם שנפדו\u0004 אף שאינם קדושים אלא בקדושת דמים — \u0003פטורין\u0004 מן הבכורה ומן המתנות. \u0003[אלמא\u0004 \u0005[מכאן]\u0006\u0003] דאלימא\u0004 \u0005[שחזקה]\u0006 היא \u0003קדושת דמים, דמפקע ליה\u0004 \u0005[שמפקיעה אותו]\u0006 \u0003מבכורה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה עליו]\u0006 עוד ר' ירמיה לר' זירא ממה ששנינו בברייתא: \u0003ה\u0004בעלים ה\u0003אומר\u0004 על הבהמה המעוברת העומדת לפניו \u0003\"מה שבמעיה של זו\u0004 יהיה קדוש בקדושת \u0003עולה\"\u0004 — בהמה זו (האם) \u0003מותרת בגיזה\u0004 של צמרה, כשאר בהמות חולין, \u0003ו\u0004אולם \u0003אסורה בעבודה,\u0004 וטעם הדבר — \u0003משום\u0004 שבעבודה בה נגרם \u0003כחוש\u0004 (החלשה, הפחתת ערך) ל\u0003עובר שבה.\u0004 הרי שהעובר קדוש ומקדישים עוברים, ושלא כשיטת בר פדא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא בתשובה: \u0003הא נמי\u0004 \u0005[זו\u0006 הברייתא \u0005גם כן]\u0006 מדברת במקדיש את העובר ב\u0003קדושת דמים\u0004 (שבדמי העובר ייקנה קרבן עולה), ובכגון זה מודה בר פדא שחלה קדושה על העובר, שאל עוד ר' ירמיה את ר' זירא:","\u0003ומי אלימא\u0004 \u0005[והאם\u0006 כה \u0005חזקה]\u0006 היא \u0003קדושת דמים\u0004 של העובר \u0003דאסירא ליה\u0004 \u0005[שאוסרת\u0006 היא \u0005אותה,\u0006 את האם\u0005]\u0006 \u0003בעבודה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 כמו כן במשנה\u0005]\u0006 כי כל הקדשים שקדם מום קבוע להקדשם, ונפדו — הריהם \u0003יוצאין לחולין,\u0004 הן לענין שמותרים \u0003ליגזז\u0004 את צמרם, \u0003ו\u0004הן לענין שמותרים \u0003ליעבד\u0004 (לעבוד) בהם. ויש לדייק בלשון המשנה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 להלכה זו — הריהו דווקא \u0003משום\u0004 ש\u0003נפדו,\u0004 ופקעה קדושתם, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נלמד, ש\u0003קודם שנפדו\u0004 ועדיין הם בקדושתם — הריהם \u0003אסורין בעבודה, אלמא\u0004 \u0005[הרי איפוא]\u0006 ש\u0003קדושת דמים אסורין ליה\u0004 \u0005[אוסרת אותו]\u0006 \u0003בעבודה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה עליו]\u0006 עוד ר' ירמיה לר' זירא, ממה ששנינו במשנתנו: \u0003אין ממירין לא אברין\u0004 של חולין \u0003בעוברין\u0004 של הקדש, \u0003ולא\u0004 בממיר \u0003עוברין\u0004 של חולין \u0003באברין\u0004 של הקדש. ולא עוברים ואברים בשלימים, ולא שלימים בעוברים. ונדייק מכאן: דווקא הקדשה באופן מסויים זה של \u0003אימורי\u0004 \u0005[תמורה]\u0006 מעוברים של הקדש לשלימים של חולין \u0003הוא דלא מימר\u0004 \u0005[שאין ממירים],\u0006 שכן אמרה התורה בדין התמורה \"ואם המר ימיר בהמה בבהמה\" (ויקרא כז, י), ואין העובר בכלל ההגדרה \"בהמה\". \u0003הא מיקדש\u0004 \u0005[הרי\u0006 נלמד כי לענין \u0005להקדיש]\u0006 עוברים במישרין שלא בדרך תמורה — הריהם \u0003קדשי\u0004 \u0005[מתקדשים],\u0006 וקשה אם כן על שיטת בר פדא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא בדחיית דבריו: אין להביא ראיה כנגד שיטת בר פדא ממשנתנו זו, משום ש\u0003בולדי קדשים הוא\u0004 שמדובר כאן, וכגון שהתעברה הבהמה לאחר שהוקדשה, \u0003דקדישי וקיימי\u0004 \u0005[שקדושים ועומדים\u0006 הם הולדות בקדושתם\u0005]\u0006 מכח אמם, ולא שהקדיש את העוברים.","על תירוץ זה של ר' זירא מקשה ר' ירמיה: \u0003אי\u0004 \u0005[אם]\u0006 המדובר במשנתנו ב\u0003ולד קדשים,\u0004 ולמדתנו המשנה כי אין ממירים בהם, שכן אין הם בכלל \"בהמה\", מכאן יש לדייק: דווקא בהיותם \u0003במעי אמן הוא דלא עבדין\u0004 \u0005[שאין עושים]\u0006 בהם תמורה, \u0003הא אבראי\u0004 \u0005[הרי\u0006 שבהיותם \u0005מחוץ\u0006 למעי אמן, לכשיוולדו\u0005]\u0006 — \u0003עבדין\u0004 \u0005[עושים]\u0006 תמורה, \u0003ו\u0004אולם אין לומר כך, שכן \u0003הא תניא\u0004 \u0005[הרי שנויה\u0006 הלכה במשנה הבאה\u0005]\u0006 ש\u0003אין הולד\u0004 של בהמת הקדש \u0003עושה תמורה\u0004 על בהמת חולין! ומתרץ ר' זירא: משנתנו זו אכן עוסקת בולדות קדשים, ואמנם יש לדייק ממנה כי בהיות הולדות מחוץ למעי אמם הריהם עושים תמורה.","ואולם אשר לשאלה מן השנוי במשנה הבאה שאין ולד בהמת הקדש עושה תמורה על בהמת חולין — אין להקשות, ויש לומר כי \u0003הא מני\u0004 \u0005[זו\u0006 משנתנו, כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 שחולק על חכמים במשנה הבאה, והוא \u0003אמר\u0004 כי \u0003הולד עושה תמורה.\u0004","הקשה ר' ירמיה על תירוצו זה של ר' זירא: \u0003אי\u0004 \u0005[אם]\u0006 משנתנו זו כשיטת \u0003ר' יהודה\u0004 היא, והרי אפשר לדייק ממשנתנו כי דווקא \u0003תמורה הוא דלא עבדי\u0004 \u0005[שאין עושים]\u0006 אברים של הקדש, \u0003הא מקדש\u0004 \u0005[הרי שלהתקדש]\u0006 — \u0003קדשי\u0004 \u0005[מתקדשים],\u0006 ואולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יהודה\u0004 ש\u0003אברין לא קדשי\u0004 \u0005[אינם מתקדשים],\u0006 ואי אפשר איפוא להעמיד את משנתנו כשיטתו! \u0003אמר\u0004 לו ר' זירא בדחיית דבריו: לא אמר ר' יהודה את שיטתו זו, שאין איברים מתקדשים, אלא באיברים שאין הנשמה תלויה בהם, אבל באיברים שהנשמה תלויה בהם — אף ר' יהודה סובר שמתקדשים, ו\u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנתנו זו, \u0005במה אנו עוסקים]\u0006 — \u0003ב\u0004מקדיש \u0003אבר שהנשמה תלויה בו.\u0004","\u0003איתיביה\u0004 \u0005[הקשה עליו]\u0006 עוד ר' ירמיה לר' זירא ממה ששנינו במשנה בפרק הבא בדברים שיש בדיני הקדשים חומרה שאין בדיני התמורה, ובכלל הדברים אף ש\u0003מקדישין אברין ו\u0004מקדישים \u0003עוברין, אבל לא ממירין\u0004 אברים ועוברים. הרי איפוא שנינו במפורש כי מקדישים עוברים, ושלא כשיטת בר פדא! ותירץ ר' זירא: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אין המדובר בהקדשת עוברים במישרין, אלא \u0003בולדי קדשים,\u0004 שהקדיש בהמה מעוברת וילדה.","שאל אותו ר' ירמיה על תירוצו זה: \u0003אי\u0004 \u0005[אם]\u0006 המדובר במשנה זו \u0003בולדי קדשים, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הלשון \u0003\"מקדישין\u0004 עוברין\", \u0003הא קדישי וקיימי\u0004 \u0005[והרי מקודשים ועומדים\u0006 הם\u0005]\u0006 מכח קדושת אמם!"],["דחה ר' זירא את קושיתו זו של ר' ירמיה: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונת לשון המשנה\u0005]\u0006 באומרה \"מקדישין אברין ועוברין, אבל לא ממירין\" — \u0003מקדישין איברין\u0004 מסויימים בבהמה, וכיון שאין הקדושה חלה באותם אברים בלבד אלא מתפשטת בכל הבהמה, הרי זה כאילו הקדיש את הבהמה כולה, \u0003ו\u0004משום כך \u0003ממירין בהן\u0004 בבהמות הללו (אף שמתחילה רק אברים מסויימים הוקדשו בהן). \u0003אבל לא ממירין\u0004 אברים של בהמת חולין \u0003בהן\u0004 (בבהמות הקדש הללו) לא בשלמות וכל שכן שלא באבר מאיבריהן. לפי שאין הקדושה מתפשטת מן האבר לכל הבהמה בקדושה הבאה על ידי תמורה. \u0003ו\u0004באשר ל\u0003עוברים,\u0004 אותם \u0003שקדשו במעי אמן\u0004 (מכח קדושת אמם) — \u0003אין ממירין בהן\u0004 כל זמן שהם במעי אמם.","חזר ושאל ר' ירמיה את ר' זירא: אם המדובר במשנתנו \u0003בולדי קדשים,\u0004 נוכל לדייק מכאן: דווקא בהיותם \u0003במעי אמן\u0004 — הוא דלא עבדין \u0005[שאין עושים]\u0006 \u0003תמורה, הא אבראי\u0004 \u0005[הרי,\u0006 נלמד מכאן שבהיותם \u0005בחוץ,\u0006 משנולדו\u0005]\u0006 — הריהם \u0003עבדי\u0004 \u0005[עושים]\u0006 תמורה? \u0003ו\u0004אולם הרי זה קשה, שכן \u0003הא תנן\u0004 \u0005[הרי שנינו]\u0006 במפורש במשנה הבאה ש\u0003אין הוולדות\u0004 של בהמת הקדש \u0003עושין תמורה!\u0004 והשיב ר' זירא: \u0003הא מני\u0004 \u0005[זו\u0006 המשנה כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא\u0004 החולק על חכמים, וסובר שהולדות עושים תמורה.","חזר ושאל ר' ירמיה את ר' זירא על כך: \u0003אי\u0004 \u0005[אם]\u0006 המשנה היא כשיטת \u0003ר' יהודה,\u0004 יש לשאול: \u0003אברין מי קדשי\u0004 \u0005[האם מתקדשים],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ל\u0004דעת \u0003ר' יהודה\u0004 הוא הרי \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 בדינו של \u0003האומר \"רגלה של זו\u0004 תהא \u0003עולה\"\u0004 שמתפשטת הקדושה בכולה ו\u0003כולה עולה,\u0004 והרי שלדעתו אין משמעות כלשהי בהקדשת אבר אחד!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה בתשובה לשאלתו זו: משנתנו אכן כשיטת ר' יהודה היא, ואולם לא אמר ר' יהודה את שיטתו שהמקדיש אבר אין הקדושה מתפשטת בכל הבהמה אלא באבר כזה שאין נטילתו מהבהמה עושה אותה בכך ל\"טריפה\" (העומדת למות תוך פרק זמן של שנים עשר חודש), אבל באבר שנטילתו מהבהמה עושה אותה לטריפה — אף ר' יהודה סבור שבמקדיש אבר כזה הקדושה מתפשטת בכל הבהמה, ואף \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנה זו, \u0005במה אנו עוסקים]\u0006 — \u0003בדבר העושה אותה\u0004 בנטילתו ל\u0003טרפה.\u0004 ונמצא איפוא שלא נדחתה שיטת בר פדא.","ושבים למחלוקתם של בר פדא ור' יוחנן, בדין המקדיש את העוברים, ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 שמחלוקתם הריהי \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 בענין אחר. ששנינו במקרה זה של \u0003השוחט את\u0004 הבהמה \u0003ה\u0004דקה המעוברת, שהוקדשה ל\u0003חטאת,\u0004 וזמן העיבור (עד ללידה) של הבהמה הדקה הריהו חמישה חודשים, \u0003ומצא בה\u0004 עובר נקיבה שהוא \u0003בן ארבע\u0004 חודשים, שאף שטרם הסתיים משך עיבורו, הריהו \u0003חי.\u0004 ונחלקו בדינו של עובר זה שתי ברייתות, \u0003קתני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 עובר זה נוהגים בו כבדיני החטאת, ש\u0003אינה נאכלת אלא לזכרי כהונה, ואינה נאכלת אלא\u0004 במקדש \u0003לפנים מן הקלעים\u0004 (בתוך חצר המקדש), \u0003ואינה נאכלת\u0004 \u0003אלא ליום\u0004 ולילה \u0003אחד.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 האומרת בדינה של נקיבה זו שנוהגים בה כבהמת חולין, ולכן הריהי \u0003נאכלת לכל אדם\u0004 ולא רק לכהנים, \u0003ונאכלין בכל מקום\u0004 מחוץ למקדש, \u0003ו\u0004אולם \u0003אינן נאכלין בעזרה,\u0004 שאסור לאוכלה בעזרה, כדין החולין. \u0003מאי לאו תנאי\u0004 \u0005[האם לא\u0006 נאמר כי מחלוקת בר פדא ור' יוחנן כמחלוקת \u0005תנאים]\u0006 זו \u0003היא? דמר סבר\u0004 \u0005[שחכם זה,\u0006 הברייתא הראשונה שהובאה, \u0005סבור]\u0006 ש\u0003קדושה חלה על עוברין,\u0004 וכדעת ר' יוחנן. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 הברייתא השניה, \u0005סבור]\u0006 ש\u0003אין קדושה חלה על עוברין,\u0004 כדעת בר פדא!","ודוחים: \u0003לא\u0004 בכך נחלקו שתי הברייתות הללו, אלא \u0003הני תנאי, בהא קא מיפלגי\u0004 \u0005[תנאים אלו, בזה הם נחלקים],\u0006 בשאלה מתי מתקדשים ולדות הקדשים, האם רק בלידתם הם מתקדשים, או כבר בהיותם במעי אמן הם מתקדשים. \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 הברייתא השניה, \u0005סבור]\u0006 כי \u0003ולדות קדשים\u0004 — רק \u0003בהוייתן\u0004 בלידתם, בהיותם הם לעצמם \u0003הן קדושים,\u0004 וכיון שעובר זה שנמצא במעי אמו לא נולד — אין הוא קדוש. ומר סבר \u0005[חכם זה,\u0006 הברייתא הראשונה, \u0005סבור]\u0006 כי \u0003ולדי קדשים\u0004 — כבר בהיותם \u0003במעי אמן הן קדושים,\u0004 ולכן חלים כל דיני החטאת על עובר זה אף שלא נולד.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאין הברייתות חלוקות ו\u0003חד תנא\u0004 \u0005[תנא אחד]\u0006 \u0003הוא\u0004 ששנה את שתיהן, ולשיטת ר' יוחנן הסבור כי חלה קדושה על עוברים, אלא \u0003חדא מהלין מתנייתא\u0004 \u0005[אחת מאלו הברייתות,\u0006 הברייתא השניה\u0005]\u0006 — עוסקת \u0003ב\u0004מקרה של \u0003מקדיש בהמה\u0004 לחטאת, \u0003ו\u0004רק \u0003אחר כך נתעברה,\u0004 ושחטה בהיות העובר בן ארבעה חודשים, וכיון שלא הוקדש העובר עצמו, וגם אינו יכול להיות קדוש מקדושת אמו, וגם לא נולד — אין הוא קדוש. \u0003וחדא מנהון\u0004 \u0005[ואחת מהן,\u0006 הברייתא הראשונה\u0005]\u0006 — עוסקת במקרה \u0003שהקדישה\u0004 את הבהמה כשהיא כבר \u0003מעוברת,\u0004 ומשום כך, אף העובר שבמעיה קדוש מכח קדושתה.","ודנים עוד בשיטות בר פדא ור' יוחנן. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 ה\u0003כלאים\u0004 (בעל החיים הנולד מזיווגם של שתי בהמות ממינים שונים), \u0003ו\u0004ה\u0003טרפה\u0004 (בעל חיים שכתוצאה מפגיעה חיצונית או ממחלה אינו עתיד לחיות שנים עשר חודש), \u0003ויוצא דופן\u0004 (הנולד שלא דרך הרחם, ומוצא בניתוח), וה\u0003טומטום\u0004 (זה שסימני המין שלו מכוסים, ומשום כך אין הוא מוגדר למינו), \u0003ואנדרוגינוס\u0004 (שיש בו איברי זכר ונקיבה כאחד) — \u0003לא קדושין ולא מקדישין. ואמר שמואל\u0004 בפירוש דבריו אלה של ר' אליעזר: כוונת אומרו \u0003לא קדושין\u0004 — שאין הם מתקדשים \u0003ב\u0004דרך ה\u0003תמורה,\u0004 כלומר, שאם היו פסולי הקרבה אלה של חולין, והמיר בהמת הקדש בהם — לא חלה קדושה עליהם. \u0003ו\u0004כוונת אומרו \u0003לא מקדישין\u0004 — \u0003לעשות תמורה\u0004 על ידם, שאם היו פסולי ההקרבה אלה של הקדש, והמיר אותם בבהמת חולין — לא חלה עליה קדושה.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא אחרת\u0005]\u0006 הדנה בדברי ר' אליעזר אלו, \u0003אמר ר' מאיר:\u0004 למה לו לר' אליעזר לומר שאין פסולים אלו מקדישים בתמורה, והרי \u0003מאחר ש\u0004אמר בראשית דבריו שהם \u0003אינן קדושין\u0004 (מתקדשים) על ידי תמורה, \u0003היאך\u0004 (באיזה אופן) ישנה אפשרות לומר שהם \u0003מקדישין\u0004 את האחרים בתמורה? ויש להשיב כי \u0003אי\u0004 (אין) \u0003אתה מוצא\u0004 אפשרות זו שיהיו פסולי ההקרבה הללו מתקדשים, \u0003אלא ב\u0004מקרים מסויימים: טריפה — במקרה של אדם ה\u0003מקדיש בהמה ואחר כך\u0004 היא \u0003נטרפה.\u0004 יוצא דופן — \u0003ב\u0004מקרה של אדם ה\u0003מקדיש ולד, ויצא [דרך] דופן. אלמא\u0004 \u0005[הרי איפוא]\u0006 עולה מדברי ר' מאיר אלה ש\u0003קדיש\u0004 \u0005[מתקדש]\u0006 \u0003ולד,\u0004 והרי זה שלא כשיטת בר פדא!","\u0003אמרי\u0004 \u0005[אומרים\u0006 בתשובה\u0005]:\u0006 יש להגדיר אחרת את מחלוקת בר פדא ור' יוחנן בדין המקדיש את העובר, שכן \u0003ב\u0004עובר שהוא \u0003תם\u0004 (שאינו בעל מום) הנמצא \u0003במעי\u0004 בהמה שהיא \u0003תמימה\u0004 — \u0003אפילו בר פדא נמי מודי דקדיש\u0004 \u0005[גם כן מודה שמתקדש]\u0006 העובר. ו\u0003לא נחלקו\u0004 בר פדא ור' יוחנן \u0003אלא ב\u0004אדם המקדיש את העובר ה\u0003תם\u0004 הנמצא \u0003במעי בעלת מום.\u0004 ובזאת נחלקו: \u0003בר פדא סבר\u0004 \u0005[סבור],\u0006 \u0003כיון דאימיה\u0004 \u0005[ש\u0006את \u0005אמו]\u0006 \u0003לא מקדישין קדושת הגוף,\u0004 שהרי בעלת מום היא — \u0003הוא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קדיש\u0004 \u0005[מתקדש]\u0006 בקדושת הגוף. \u0003ו\u0004אילו \u0003ר' יוחנן סבר\u0004 \u0005[סבור]\u0006 כי \u0003הני\u0004 \u0005[\u0006שני \u0005אלו,\u0006 האם ועוברה\u0005]\u0006 — \u0003כשתי בהמות\u0004 נפרדות \u0003נינהו\u0004 \u0005[הן],\u0006 ועל כן יש גם להפריד בדינן: \u0003אימיה\u0004 \u0005[אמו]\u0006 — \u0003היא\u0004 זו ש\u0003לא מיקדשא\u0004 \u0005[מתקדשת],\u0006 \u0003אבל הוא\u0004 העובר — \u0003קדוש\u0004 \u0005[מתקדש].\u0006","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 בהצעת הראיה מדינם של פסולי ההקרבה. למדנו למעלה שדברי ר' אליעזר שפסולי ההקרבה אין מקדשים בהמת חולין בתמורה (אף שהם עצמם קדושים) מתקיימים בטריפה וביוצא דופן. \u0003אבל\u0004 ה\u0003כלאים ו\u0004ה\u0003טומטום ו\u0004ה\u0003אנדרוגינוס\u0004 של חולין שהמיר בהמת קודש בהם — \u0003אי\u0004 (אין) \u0003אתה מוצא\u0004 אפשרות זו שיתקדשו \u0003אלא בולדי קדשים,\u0004 בבהמה שהוקדשה ולאחר מכן התעברה מבעל חיים אחר שאינו בן מינה, או שעוברה טומטום או אנדרוגינוס.","\u0003ו\u0004סבור ר' אליעזר \u0003כ\u0004שיטת \u0003ר' יהודה, שהיה אומר: הולד\u0004 הנולד לבהמת הקדש \u0003עושה תמורה,\u0004 ובא ר' אליעזר ללמד שולדות פסולי הקרבה אלה, אינם עושים תמורה. ומכאן נדייק לענייננו: דווקא \u0003הלין\u0004 \u0005[אלו,\u0006 פסולי הקרבה\u0005]\u0006 \u0003הוא\u0004 שאין עושים תמורה, וסיבת הדבר: משום ש\u0003לא קדשי גופייהו\u0004 \u0005[התקדש גופם,\u0006 שהרי הם פסולי הקרבה\u0005],\u0006 \u0003אבל\u0004 ולדות שאינם פסולי הקרבה וכן \u0003עוברין אחרים,\u0004 שאינם פסולים — הריהם \u0003קדושין,\u0004 והרי זה איפוא שלא כשיטת בר פדא!","\u0003אמר אביי\u0004 בתשובה: יש להגדיר אחרת את מחלוקת בר פדא ור' יוחנן, ולומר שבמקרה של עובר \u0003תם במעי תמימה\u0004 — ל\u0003דברי הכל קדיש גופיה\u0004 \u0005[מתקדש גופו],\u0006 \u0003אלא כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 בר פדא ור' יוחנן — הרי זה במקדיש עובר תם הנמצא \u0003במעי בעלת מום.\u0004 ובזאת נחלקו: ש\u0003בר פדא סבר\u0004 \u0005[סבור]\u0006 כי \u0003כיון דאימיה נמי לא קדיש גופה\u0004 \u0005[שאמו גם כן אינה מתקדשת בעצמה],\u0006 אלא לדמיה, שהרי היא בעלת מום — \u0003איהו נמי לא קדיש\u0004 \u0005[הוא גם כן אינו מתקדש]\u0006 \u0003אלא לדמי\u0004 \u0005[ל\u0006קדושת \u0005דמים,\u0006 ולא לקדושת הגוף\u0005].\u0006 ואילו \u0003ר' יוחנן סבר\u0004 \u0005[סבור]\u0006 כי \u0003עובר לאו\u0004 \u0005[לא]\u0006 כ\u0003ירך\u0004 (חלק מגוף) \u0003אמו הוא\u0004 נחשב, אלא הריהו יצור לעצמו, \u0003ו\u0004משום כך, \u0003אף על גב דאימיה לא קדשה\u0004 \u0005[אף על פי שאמו אינה מתקדשת]\u0006 \u0003ל\u0004קדושת \u0003גופה,\u0004 אלא רק לקדושת דמים — ה\u0003ולד מיהא קדיש לגופיה\u0004 \u0005[לפחות מתקדש ל\u0006קדושת \u0005גופו].\u0006","ושבים לבירור הנאמר במשנתנו. שנינו בה שנחלקו חכמים בדין הממיר אברים של בהמות חולין בבהמות שלמות של הקדש, שלדעת חכמים אין התמורה חלה, ואילו לדעת ר' יוסי חלה התמורה בדרך זו, שכשאומר \"הרי רגל בהמה זו תמורת בהמת הקדש זו\" — חלה קדושת תמורה על הרגל, ומתפשטת ממנה על כל בהמת החולין. ו\u0003אמר ר' יוסי\u0004 בהסבר שיטתו זו: \u0003והלא במוקדשין\u0004 (באדם המקדיש בהמה) \u0003האומר \"רגלה של זו\u0004 עולה\" — כולה עולה, והוא הדין אם כן בתמורה."],["ועוד במחלוקת תנאים זו בדין הממיר אברים של חולין בשלמים של קודש. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול\u0004 יהיה הדין במקרה של \u0003האומר \"רגלה של זו עולה\",\u0004 שתתפשט הקדושה מהרגל על כל הבהמה, ו\u0003תהא כולה עולה?\u0004 — לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב): \"ואם בהמה אשר יקריבו ממנה קרבן לה' \u0003כל אשר יתן ממנו לה' יהיה קדש\"\u0004 (ויקרא כז, ט), והרי זה בא לדייק: כל אבר שניתן \u0003ממנו\u0004 (מבעל החיים) \u0003לה'\u0004 הוא שיהיה קודש, \u0003ולא\u0004 בעל החיים \u0003כולו\u0004 יהיה קודש \u0003לה'.\u0004","ומבררים עוד, \u0003יכול\u0004 יהיה הדין במקרה זה שתיפדה הבהמה ו\u0003תצא לחולין?\u0004 — לכך \u0003תלמוד לומר\u0004 בכתוב זה \u0003\"יהיה קדש\",\u0004 ללמדנו שאותו אבר שהוקדש, הריהו עומד בקדושתו, ואינו נפדה. ומעתה יש לשאול: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ינהג בבהמה זו? — \u0003תמכר\u0004 הבהמה \u0003לצרכי\u0004 (לנצרכי, לטובת אלו החייבים) להקריב \u0003עולות, ודמיה\u0004 הריהם \u0003חולין, חוץ מדמי\u0004 (ממחיר) אותו \u0003אבר שבה\u0004 שהוקדש. אלו \u0003דברי ר' מאיר ור' יהודה. ו\u0004אילו","\u0003ר' יוסי ו\u0004כן \u0003ר' שמעון אומר: מנין לאומר \"רגלה של זו עולה\", ש\u0004התפשטה הקדושה בכל הבהמה, ו\u0003כולה\u0004 עומדת בקדושת \u0003עולה?\u0004 — שכן כיון \u0003שנאמר \"כל אשר יתן ממנו לה'\",\u0004 היה איפוא די בכתוב זה ללמד שאותו אבר הריהו קדוש (\"כל אשר יתן ממנו — לה'\". \u0003כשהוא\u0004 הפסוק ממשיך ו\u0003אומר \"יהיה קדש\"\u0004 — הרי זה בא ללמד: \u0003לרבות את כולה,\u0004 שמתפשטת הקדושה בכולה.","ודנים עתה בברייתא זו. \u0003אמר מר\u0004 \u0005[החכם,\u0006 ר' מאיר ור' יהודה\u0005]:\u0006 \u0003תמכר\u0004 הבהמה \u0003לצרכי עולות,\u0004 ושואלים: \u0003והא קמייתי\u0004 \u0005[והרי\u0006 הקונה את הבהמה הזו \u0005מביא]\u0006 בעולתו \u0003בהמה\u0004 שאינה כולה עולתו, שהרי היא \u0003מחוסרת\u0004 אותו \u0003אבר\u0004 שהוקדש על ידי בעליה הקודמים של בהמה זו, ואותו אבר קרב לעולתו של זה המקדיש! \u0003אמר רבא:\u0004 לא אמרו ר' מאיר ור' יהודה שתימכר בהמה זו לכל אדם שחייב להביא קרבן עולה, אלא רק \u0003ב\u0004אדם ה\u0003אומר \"הרי עלי\u0004 להביא קרבן \u0003עולה בחייה\u0004 (בכל האברים שבהם תלויים חייה של הבהמה\". ורגל אינה בכלל אברים אלה. ומשום כן, אף שרגלה של בהמה זו נחשבת לעולתו של המקדיש הראשון, אינה נחשבת כמחוסרת אבר לקונה המביא את העולה. ובהגדרת שיטתם של ר' מאיר ור' יהודה נחלקו חכמים.","\u0003אמר רב חסדא:\u0004 אף שר' מאיר ור' יהודה סבורים שבמקדיש אבר של בהמה, לא פשטה קדושה בכולה, מכל מקום \u0003מודה ר' יהודה\u0004 ור' מאיר, \u0003ב\u0004מקדיש \u0003דבר\u0004 (אבר) \u0003ש\u0004אם יינטל מהבהמה הריהו \u0003עושה אותה\u0004 בכך ל\u0003טרפה\u0004 (מי שאינה חיה שנים עשר חודש, ואסורה באכילה), שפשטה הקדושה בכל הבהמה. ואילו \u0003רבא אמר:\u0004 אף במקדיש אבר שבהינטלו עושה את הבהמה טריפה סבורים ר' מאיר ור' יהודה שלא פשטה בכך הקדושה בכל הבהמה, ואולם הריהם מודים שפשטה קדושה בכל הבהמה \u0003בדבר שעושה אותה\u0004 בהילקחו ל\u0003נבילה\u0004 (שאינה יכולה לחיות כלל ואסורה באכילה משום נבילה). \u0003ו\u0004אילו \u0003רב ששת אמר:\u0004 אין ר' יהודה ור' מאיר מודים שפשטה הקדושה בכל הבהמה אלא רק \u0003ב\u0004מקדיש \u0003דבר ש\u0004אם יינטל מהבהמה \u0003היא\u0004 מייד \u0003מתה.\u0004 ומבררים את הדעות הללו.","\u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין\u0004 הסברו של \u0003רב חסדא ל\u0004הסברו של \u0003רבא?\u0004 ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 בשאלה האם בהמה המוגדרת כ\u0003טרפה, חיה\u0004 (יכולה לחיות). ש\u0003רב חסדא סבר לה כמאן דאמר\u0004 \u0005[הריהו סבור כמי שאומר]\u0006 \u0003טרפה אינה חיה,\u0004 אלא ברור שתמות בקרוב, ולכן, המקדיש אבר בגוף הבהמה שאם יינטל ממנה הריהי טרפה, אף ר' יהודה ור' מאיר מודים שפשטה קדושה בכל הבהמה. \u0003ו\u0004אילו \u0003רבא סבר לה כמאן דאמר\u0004 \u0005[הריהו סבור כמי שאומר]\u0006 \u0003טרפה חיה\u0004 (יכולה לחיות), ולכן במקדיש אבר שבהינטלו הריהי נעשית טריפה אין הקדושה מתפשטת בכל הבהמה, אלא רק במקדיש אבר שבהינטלו היא נקראת נבילה.","\u0003ומאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל מעשי \u0005יש]\u0006 \u0003בין\u0004 הסברו של \u0003רבא ל\u0004הסברו של \u0003רב ששת?\u0004 ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 במקרה שהקדיש את הירך והחלל של הבהמה ובדינו של \u0003ר' אלעזר\u0004 בכגון זה. שכן \u0003אמר ר' אלעזר: ניטלה\u0004 ה\u0003ירך ו\u0004ה\u0003חלל שלה\u0004 — בהמה זו נחשבת כ\u0003נבילה.\u0004 ש\u0003רבא סבר לה\u0004 \u0005[הריהו סבור]\u0006 \u0003כר' אלעזר,\u0004 ולכן לדעתו גם במקדיש ירך וחלל — הכל אומרים שפשטה קדושה בכולה. ואילו \u0003רב ששת לא סבר לה\u0004 \u0005[אינו סבור]\u0006 \u0003כר' אלעזר,\u0004 ולכן הוא סבור שאף ר' מאיר ור' יהודה מודים שבמקדיש ירך וחלל שלה — לא פשטה קדושה בכולה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דבריהם של חכמים אלה ממה ששנינו, \u0003אמר רבי:\u0004 במחלוקת ר' יהודה ור' יוסי \u0003נראין\u0004 (מסתברים, מתקבלים) \u0003דברי ר' יהודה\u0004 שאין הקדושה מתפשטת בכל הבהמה — \u0003ב\u0004מקדיש \u0003דבר שאין הנשמה תלויה בו, ו\u0004אילו \u0003דבריו ר' יוסי,\u0004 שהקדושה מתפשטת בכל הבהמה, נראים — \u0003ב\u0004מקדיש \u0003דבר שהנשמה תלויה בו.\u0004 ונדייק בדברי רבי: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מכלל\u0004 הדברים נסיק \u0003דפליג עליה\u0004 \u0005[ש\u0006ר' יוסי \u0005חולק עליו]\u0006 על \u0003ר' יהודה\u0004 באבר שהנשמה תלויה בו ובאבר שאין הנשמה תלויה בו, ובא רבי והכריע בכל מקרה לגופו.","ויש לשאול: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 מה שהכריע רבי במחלוקתם ואמר ש\u0003נראין דברי ר' יהודה בדבר שאין הנשמה תלויה בו\u0004 — \u0003מכלל\u0004 הדברים נסיק \u0003דפליג עליה\u0004 \u0005[ש\u0006ר' יהודה \u0005חולק עליו\u0006\u0005]\u0006 על \u0003ר' יוסי\u0004 הסבור שאף במקרה זה הקדושה מתפשטת בכל הגוף. \u0003אלא\u0004 מה שהכריע רבי ואמר ש\u0003נראין דברי ר' יוסי בדבר שהנשמה תלויה בו, לאו\u0004 \u0005[האם לא]\u0006 \u0003מכלל\u0004 הדברים נסיק \u0003דפליג עליה\u0004 \u0005[ש\u0006ר' יוסי \u0005חולק עליו]\u0006 על \u0003ר' יהודה,\u0004 הסבור איפוא שאף במקרה זה לא פשטה הקדושה בכל הבהמה. \u0003ו\u0004הרי זו \u0003תיובתא דכולהו\u0004 \u0005[קושיה חמורה על כולם,\u0006 רב חסדא ורבא ורב ששת\u0005]\u0006 הסבורים כולם שבמקדיש אבר שהנשמה תלויה בו, מודה ר' יהודה שפשטה הקדושה בכל הבהמה!","ומשיבים: \u0003לא,\u0004 אין להקשות מדברי רבי על החכמים הללו, משום שאין אלו דברי רבי המדוייקים, שכן \u0003חסורי מיחסרא\u0004 \u0005[חסרים]\u0006 דברים בתוך דברי רבי, \u0003והכי קתני\u0004 \u0005[וכך הוא,\u0006 הנוסח השלם \u0005שנוי]:\u0006 \u0003נראין דברי ר' יוסי\u0004 שהקדושה מתפשטת בכל הבהמה \u0003לר' יהודה בדבר שהנשמה תלויה בו, ש\u0004כן \u0003אף ר' יהודה לא נחלק עליו אלא בדבר שאין הנשמה תלויה בו, אבל בדבר שהנשמה תלויה בו\u0004 — \u0003מודי ליה\u0004 \u0005[מודה\u0006 ר' יהודה \u0005לו,\u0006 לר' יוסי\u0005].\u0006","ובשיטת ר' יוסי שבמקדיש אבר אחד בבהמה, הקדושה מתפשטת בכל הבהמה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: בעוף\u0004 הראוי להקרבה \u0003מהו\u0004 הדין לשיטה זו? וצדדי השאלה: האם דווקא במקדיש אבר בבהמה אמר כך ר' יוסי, לפי שלמד זאת ר' יוסי מן הכתוב \"ואם בהמה אשר יקריבו ממנה קרבן לה' כל אשר יתן ממנו לה' יהיה קודש\", כמובא לעיל, והרי בראש פסוק זה \u0003\"בהמה\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והא לאו\u0004 \u0005[וזה,\u0006 עוף, \u0005לא]\u0006 בכלל \u0003\"בהמה\" היא.\u0004 \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי באותו כתוב \u0003\"קרבן\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 — \u0003והאי נמי\u0004 \u0005[וזה\u0006 העוף, \u0005גם כן]\u0006 בכלל \u0003\"קרבן\" הוא?\u0004 ומסכמים: לא נמצא פתרון לשאלה זו, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 בשיטת ר' יוסי: אם \u0003הקדיש אבר\u0004 בגוף הבהמה \u0003ל\u0004קדושת \u0003דמיו\u0004 (שתימכר הבהמה, ויביאו בדמי אותו אבר, עולה), \u0003מהו\u0004 דינו לענין זה \u0003דתיחות ליה\u0004 \u0005[שתרד לו,\u0006 שתחול על הבהמה כולה\u0005]\u0006 \u0003קדושת הגוף?\u0004 וצדדי השאלה: \u0003מי אמר\u0004 \u0005[האם אומרים]\u0006 כי \u0003כיון דנחתא ליה\u0004 \u0005[שירדה לה,\u0006 חלה\u0005]\u0006 \u0003קדושת דמים\u0004 על אותו אבר — מתוך כך \u0003נחתא ליה נמי\u0004 \u0005[ירדה לה\u0006 \u0005גם כן]\u0006 \u0003קדושת הגוף\u0004 על אותו אבר, \u0003ומדאקדשיה לחד אבר\u0004 \u0005[ומ\u0006תוך \u0005שהקדישו לאבר אחד] —\u0006 \u0003אקדשיה\u0004 \u0005[הקדישה]\u0006 \u0003לכולה\u0004 ותהיה כולה קדושה בקדושת הגוף. \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003חד מגו\u0004 \u0005[אחד \"מתוך\"]\u0006 — \u0003אמר\u0004 \u0005[אומרים],\u0006 שמתוך שחלה קדושת דמים על אותו אבר, חלה גם קדושת הגוף עליו. אבל להוסיף על כך עוד \"מגו\" שמתוך שחלה על אבר אחד קדושת הגוף, תחול על כל הגוף כולו, והרי אלה \u0003תרי מגו\u0004 \u0005[שני \"מתוך\"]\u0006 — \u0003לא אמר\u0004 \u0005[אין אומרים].\u0006","ומשיבים על דברי רבא: \u0003תפשוט ליה מדידיה\u0004 \u0005[תיפתר לו,\u0006 לרבא שאלתו זו, \u0005משלו],\u0006 ממה שהוא עצמו אמר, שכן \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבא: הקדיש\u0004 איל \u0003זכר לדמיו,\u0004 שימכר ויביאו בדמיו עולה — כיון שהוא עצמו ראוי להיקרב לעולה (שהרי זכר הוא), הריהו \u0003קדוש קדושת הגוף\u0004 אף שמעיקרו הוקדש רק לדמיו, ואף כאן כיון שחלה הקדושה על האבר הריהי חלה בכל הבהמה, ומתוך שחלה בכולה קדושת דמים, תחול עליה אף קדושת הגוף!","ודוחים: אין להביא ראיה משם, כי \u0003התם\u0004 \u0005[שם]\u0006 — התקדש בקדושת הגוף, משום \u0003דאקדשיה לכוליה\u0004 \u0005[שהקדיש את כולו],\u0006 ואין זה אלא \"מתוך\" אחד (מתוך שחלה עליו קדושת דמים, חלה עליו קדושת הגוף), ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בבעייתו של רבא \u0003דאקדשיה חד אבר\u0004 \u0005[שהקדיש אבר אחד],\u0006 שנדרשים אנו לשני \"מיגו\" כדי שיקדש כולו בקדושת הגוף, יש מקום לשאול: \u0003מאי\u0004 \u0005[מה]\u0006 הדין? ומסכמים: לא נפתרה השאלה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ומביאים שאלה בבירור שיטת ר' יהודה. \u0003בעי מיניה\u0004 \u0005[שאל\u0006 אחד החכמים \u0005ממנו]\u0006 \u0003מרבא\u0004 שאלה זו: אם \u0003הקדיש\u0004 בקדושת הגוף \u0003חד אבר\u0004 \u0005[אבר אחד]\u0006 בבהמה, מהו דינו של אותו אבר \u0003ב\u0004איסור \u0003גיזה\u0004 של הצמר שעליו? והשיב לו: \u0003תפשוט\u0004 (תפתור) \u0003לך\u0004 שאלתך זו \u0003מהא דתניא\u0004 \u0005[מ\u0006ברייתא \u0005זו ששנינו]\u0006 על הכתוב באיסור גיזה בבכור \"ו \u0003לא תגז בכור צאנך\"\u0004 (דברים טו, יט): לשון \"צאנך\" שהיא לשון מיעוט באה ללמדנו שאיסור גיזה נוהג דווקא בדבר שהוא כולו של הבעלים, \u0003אבל אתה גוזז\u0004 (מותר בגזיזה) \u0003ב\u0004בכור שהוא בשותפות \u0003שלך ושל אחרים\u0004 (גויים). ואף כאן, הרי בהמה זו היא בשותפות הקדש וחולין, ותהיה כולה (ואף אותו אבר שהוקדש) איפוא מותרת בגיזה.","השיב אותו חכם לרבא: אין להביא ראיה משם, שכן \u0003התם\u0004 \u0005[שם,\u0006 בבכור שהוא בשותפות גוי\u0005],\u0006 כיון שיש לגוי שותפות בו \u0003לא נחתא ליה\u0004 \u0005[ירדה לה,\u0006 חלה\u0005]\u0006 עליו \u0003קדושה כלל,\u0004 אף לא לחלקו של הישראלי. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 — הרי \u0003נחתא ליה\u0004 \u0005[ירדה לה,\u0006 חלה\u0005]\u0006 \u0003קדושה\u0004 על אותו האבר שהוקדש, ושמא יש מקום לאסור גיזה בו. \u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בדחיית הראיה מהיתר הגיזה בבכור ששותף בו גוי, שכן \u0003התם\u0004 \u0005[שם]\u0006 בבכור שהוא בשותפות עם גוי — אף אם ירצה הישראלי, \u0003אין בידו להקדישו\u0004 את חלקו בבכור, מחמת השותפות של הגוי בבכור זה, ולכן לא שייך איסור גיזה בחלק הישראלי. אבל \u0003הכא\u0004 \u0005[כאן],\u0006 במקדיש אבר אחד — יש \u0003בידו\u0004 של הבעלים \u0003להקדישו\u0004 לאבר אחד, וחלה עליו קדושה. ולכן יש מקום לשאול מה דינו של אותו אבר לגיזת צמרו. ודנים עוד באיסור עבודה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבא:\u0004 מי ש\u0003הקדיש\u0004 את \u0003עורה\u0004 של הבהמה בלבד, \u0003מהו\u0004 דינה של בהמה זו \u0003בעבודה?\u0004 השיב לו רבא: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו: \u0003האומר\u0004 על בהמה מעוברת \u0003\"מה שבמעיה של\u0004 בהמה \u0003זו\u0004 הריהו לקרבן \u0003עולה\"\u0004 — \u0003מותרת\u0004 הבהמה \u0003בגיזה, ואסורה בעבודה.\u0004 וטעם הדבר: מותרת בגיזה — מפני שאין העובר שבמעיה נחסר בכך, ואסורה בעבודה — \u0003מפני כחוש\u0004 (החלשת) ה\u0003עובר שבה.\u0004 ונלמד מכאן, שאף בהמה שהוקדשה לעורה בלבד אסורה בעבודה משום הפגיעה בערך העור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרבא: אין להביא ראיה מברייתא זו, שכן \u0003כי קתני\u0004 \u0005[כאשר שנו]\u0006 בברייתא זו שהבהמה המעוברת \u0003אסורה בעבודה\u0004 — הכוונה היא שאסורה \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 בלבד, ואני שאלתי ביחס לאיסור עבודה מדין תורה. אמר לו רבא: אם הברייתא עוסקת באיסור מדברי חכמים בלבד, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מדוע נאסרה רק העבודה, \u0003אפילו בגיזה נמי תיתסר\u0004 \u0005[גם כן תיאסר]\u0006 הבהמה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי בתשובה: יש להבדיל בין עבודה וגיזה, שכן דווקא ב\u0003עבודה, דמיכחשא\u0004 \u0005[שמכחישה,\u0006 מרזה ומחלישה את הבהמה\u0005] —\u0006 \u0003גזרי\u0004 \u0005[גזרו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים],\u0006 אבל \u0003גיזה\u0004 — שאינה מכחישה את הבהמה \u0003לא גזרי\u0004 \u0005[גזרו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים].\u0006 ונשארה איפוא שאלתו של אביי ללא פתרון.","ועוד \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרב יוסף:\u0004 הקדיש אדם בהמה מעוברת לקרבן שלמים חוץ מעוברה, ונמצא ש\u0003היא,\u0004 הבהמה המעוברת, קדושה ל\u0003שלמים ו\u0004אולם \u0003ולדה\u0004 הוא \u0003חולין, ושחטה בפנים\u0004 (בעזרה במקדש, כדין שחיטת השלמים), \u0003מהו\u0004 הדין? ומסביר אביי את שאלתו: \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003ולדי קדשים\u0004 רק \u0003ב\u0004שעת \u0003הוייתן\u0004 (בהיותם הם עצמם, בלידתם) \u0003הן קדושין,\u0004 אם כן ולדות אלה שבמעי אמם, שטרם נולדו, לא התקדשו עדיין, ועדיין יש לשאול: \u0003מי הוי\u0004 \u0005[האם הריהם]\u0006 בכלל איסור שחיטת \u0003חולין בעזרה\u0004 (שכן הם חולין), \u0003או לא\u0004 (שהרי הם עצמם לא נשחטו)?"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי בפתרון שאלתו זו: אין בשחיטה זו משום איסור שחיטת חולין בעזרה, שהרי \u0003מי קרינא ביה\u0004 \u0005[האם קוראים אנו בו,\u0006 מתקיים במקרה זה\u0005]\u0006 הכתוב \u0003\"כי ירחק ממך המקום\u0004 אשר יבחר ה' אלהיך לשים שמו שם \u0003וזבחת\"\u0004 (דברים יב, כא), שממנו נלמד איסור שחיטת חולין בעזרה? שדרשו חכמים: דווקא בריחוק מקום מהמקדש אתה שוחט חולין, ואין אתה שוחט חולין במקדש. שלא אסרה תורה שחיטת חולין בעזרה אלא בדבר שיכול היה להישחט מחוץ לעזרה, ואולם במקרה זה, הרי חייב הוא לשחוט את האם (המעוברת) בעזרה, בהיותה קרבן שלמים.","ועוד \u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרב יוסף\u0004 שאלה הפוכה מזו הקודמת: לשיטת ר' יוחנן האומר שמקדישים עוברים, אם הקדיש את העובר שבמעי אמו לשלמים, ונמצא ש\u0003היא\u0004 (הבהמה המעוברת) הינה \u0003חולין וולדה\u0004 הינו \u0003שלמים. ושחטה בחוץ\u0004 (למקדש, כשחיטת חולין רגילים), \u0003מהו\u0004 דינו, \u0003מי מחייב עליה\u0004 \u0005[האם מתחייב עליו],\u0006 על עובר זה \u0003משום\u0004 איסור \u0003שחוטי חוץ, או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי בתשובה לשאלתו זו: \u0003מי קרינא ביה\u0004 \u0005[האם קוראים אנו בו,\u0006 מתקיים במקרה זה\u0005]\u0006 הכתוב \"איש איש מבית ישראל אשר ישחט... במחנה או אשר ישחט מחוץ למחנה. ואל פתח אהל מועד לא הביאו להקריב קרבן לה' לפני משכן ה' דם יחשב לאיש ההוא... למען אשר יביאו בני ישראל את זבחיהם אשר הם זובחים על פני השדה \u0003והביאם לה'\u0004 אל פתח אהל מועד...\" (ויקרא יז, ג—ה), המלמד את איסור שחיטת הקדשים מחוץ למקדש? שהרי לא נאסר להישחט בחוץ אלא הראוי להישחט בפנים, ואילו עובר זה כל עוד לא נולד אינו ראוי להישחט כלל!","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 בהצעת תשובתו של רב יוסף לבעייתו זו של אביי. שכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: אמר הכתוב באיסור שחיטת קדשים בחוץ \"ואל פתח אהל מועד לא הביאו\" — ללמדנו שרק על זה ה\u0003ראוי\u0004 לבוא \u0003לפתח אהל מועד\u0004 (להיות מוקרב במקדש) הוא ש\u0003חייבין עליו,\u0004 על שחיטתו, \u0003בחוץ,\u0004 ועובר זה כל עוד לא נולד אינו ראוי לבא לפתח אהל מועד.","פירות תרומה שנפלו לפירות חולין, ונתערבו עד שאי אפשר לזהות את פירות התרומה שבתוך התערובת, אם שיעור פירות החולין לא היה פי מאה משיעור פירות התרומה — לא התבטלה בתוכם התרומה, וממילא נאסרו (\"נדמעו\") כל הפירות למי שאסור באכילת תרומה. ואם לאחר מכן חזרה ונפלה מאותה תערובת סאה פירות לתוך פירות חולין אחרים, \u0003אין המדומע\u0004 כבר \u0003מדמע\u0004 שנית \u0003אלא לפי חשבון\u0004 (חישוב). שאנו מניחים שהתרומה שבתערובת הראשונה מעורבת היטב, ויש בה רק אחוז מסויים של תרומה, לפי חשבון התרומה שנפלה.","ויש צורך לבטל בתערובת השניה רק כנגד חלק זה של אותה תרומה \u0003ו\u0004בדומה לכך, גם \u0003אין המחומץ,\u0004 כלומר, עיסה של חולין שהחמיצה בנתינת שאור של תרומה לתוכה, ודינה של עיסה זו שהיא אסורה כולה באכילה למי שאסור באכילת תרומה, אם נפל לאחר מכן חלק ממנה לתוך עיסה אחרת של חולין — אין אותו חלק \u0003מחמץ\u0004 את העיסה השניה \u0003אלא לפי חשבון\u0004 התרומה שבו. \u0003ו\u0004בדומה לכך, בדין המקוה, שמקוה כשר צריך שיהיו בו מים (שאינם שאובים) בשיעור ארבעים סאה. ואולם מקוה שאין בו ארבעים סאה מים כשרים אם נפלו לתוכו שלשה לוגים מים שאובים והשלימוהו לארבעים — הריהו נפסל בכך. ואומרת המשנה: \u0003אין המים\u0004 ה\u0003שאובין פוסלין את המקוה אלא לפי חשבון\u0004 כפי שיבואר בגמרא.","ואין מי חטאת (מי אפר פרה אדומה), \u0003עושין\u0004 (נעשים) \u0003מי חטאת אלא עם מתן\u0004 ה\u0003אפר\u0004 עליהם. אבל אם נתן בכלי את האפר תחילה, ולאחר מכן את המים — אין אלו מי חטאת כשרים. \u0003ו\u0004עוד הלכה בענין בית הפרס, שהוא שדה שהיה בו קבר ונחרש, והרי יש עתה בתחום הנחרש ספק טומאה שמא עם החרישה נגררה עצם מהמת, וקבעו חכמים שספק הטומאה זה הוא בתחום מאה אמה סביב הקבר. ואמר ש\u0003אין בית הפרס\u0004 \u0003עושין בית הפרס\u0004 אחר, שאם חזר וחרש מתחום מאה אמה אלו לשטח אחר — אין הוא טמא. \u0003ואין תרומה אחר תרומה,\u0004 שאם הפריש תרומה מפירות החייבים בתרומה, וחזר והפריש מהם שוב תרומה — אין זו תרומה.","\u0003ו\u0004כן \u0003אין\u0004 ה\u0003תמורה,\u0004 בהמת חולין שהמירו אותה בבהמת הקדש, ונעשתה אף היא הקדש, \u0003עושה תמורה.\u0004 שאם המירו בהמת חולין אחרת בבהמת תמורה זו — לא חל דין התמורה על בהמת החולין השניה, ואינה מתקדשת בכך. \u0003ו\u0004כן \u0003לא הולד\u0004 הנולד מבהמת הקדש אך לא הוקדש בעצמו \u0003עושה תמורה,\u0004 שאם המירו בהמת חולין עליו — לא חל דין התמורה. ואילו \u0003ר' יהודה אומר: הולד עושה תמורה. אמרו לו\u0004 חכמים לר' יהודה: אין הלכה כדבריך, אלא רק \u0003הקדש\u0004 — הוא ה\u0003עושה תמורה, ואין הולד עושה תמורה.\u0004","במשנה, שנינו שאין המדומע מדמע אלא לפי חשבון, ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 של משנתנו? אמר ר' חייא בר אבא, \u0003אמר ר' יוחנן:\u0004 משנתנו היא ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר,\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה]: \u0003סאה של תרומה שנפלה ל\u0004תוך \u0003פחות ממאה\u0004 סאים פירות של \u0003חולין, ונדמעו\u0004 בכך, אם לאחר מכן חזר \u0003ונפל מן המדומע למקום אחר,\u0004 לתוך פירות חולין אחרים, \u0003ר' אליעזר אומר:\u0004 שיעור זה שנפל לתערובת השניה \u0003מדמע\u0004 \u0003כתרומה ודאי,\u0004 וכל עוד אין שיעור מאה חולין כנגדו — אף התערובת השניה אסורה. וטעם הדבר: \u0003שאני אומר\u0004 מן הספק שה\u0003סאה שנפלה\u0004 לתערובת הראשונה, \u0003היא\u0004 זו \u0003שעלתה,\u0004 שיצאה ממנה בשלמות ונפלה לתערובת השניה.","\u0003וחכמים אומרים: אינה מדמעת אלא לפי חשבון שבה.\u0004 שלדעתם מניחים אנו שכל סאה שבתערובת הראשונה נחשבת כמעורבת היטב ויש בה רק אחוז מסויים של תרומה לפי חשבון התרומה שנפלה, ולכן אין התערובת השניה מדמעת אלא כנגד אחוז זה של התרומה.","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אין המחומץ מחמץ\u0004 אלא לפי חשבון. ומבררים כשיטת מי היא. \u0003אמר ר' אבא, אמר ר' יוחנן: מתניתין\u0004 \u0005[משנתנו]\u0006 זו הריהי ש\u0003לא כ\u0004שיטת ר' אליעזר.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שאור של חולין ושל תרומה שנפלו\u0004 שניהם \u0003לתוך העיסה, ולא בזה\u0004 כשלעצמו יש שיעור \u0003כדי\u0004 \u0003להחמיץ\u0004 את העיסה, \u0003ולא בזה\u0004 כשלעצמו יש שיעור \u0003כדי להחמיץ\u0004 את העיסה, \u0003ונצטרפו\u0004 שניהם \u0003וחימצו\u0004 את העיסה. ש\u0003ר' אליעזר אומר: אחר\u0004 (על פי) השאור ה\u0003אחרון\u0004 שניתן בעיסה, והוא זה שגרם לה שתתחמץ \u0003אני בא\u0004 (קובע) מה דינה של העיסה. שאם היה של חולין — הריהי מותרת באכילה לכל ואם השאור האחרון היה של תרומה — העיסה אסורה באכילה למי שאסור באכילת תרומה. \u0003ו\u0004אילו \u0003חכמים אומרים: בין שנפל\u0004 שאור ה\u0003איסור\u0004 (של התרומה) \u0003לכתחילה\u0004 (בתחלה, לפני שאור החולין), \u0003ובין שנפלה\u0004 שאור ה\u0003איסור בסוף\u0004 (לאחר שאור החולין) — \u0003לעולם אין אסור\u0004 באכילת העיסה מי שאינו מותר באכילת תרומה, \u0003עד שיהא בו\u0004 בשאור של התרומה \u0003כדי להחמיץ\u0004 כשלעצמו.","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אין המים\u0004 ה\u0003שאובין פוסלין את המקוה\u0004 אלא לפי חשבון. ואף בזאת מבררים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 של משנתנו? אמר ר' חייא בר אבא, אמר ר' יוחנן: ר' אליעזר בן יעקב היא, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בתוספתא, \u0003ר' אליעזר בן יעקב אומר: מקוה שיש בו עשרים ואחת סאה מי גשמים,\u0004 שהם רוב שיעורו של המקוה הכשר (שהוא בארבעים סאה), מה עושה כדי להכשירו? — \u0003ממלא\u0004 (שואב מים) \u0003ב\u0004דלי הנישא על \u0003כתף\u0004 (והרי אלו \"מים שאובים\") בשיעור \u0003תשע עשרה סאה,\u0004 וממלאם בבור הסמוך למקוה \u0003ופותקן\u0004 (ומזרימם) דרך תעלה העוברת מהבור \u0003ל\u0004תוך ה\u0003מקוה —\u0004"],["\u0003ו\u0004בכך \u0003הן,\u0004 כל ארבעים הסאה שבמימי המקוה, \u0003טהורין\u0004 (כשרים לטהר). וטעם הדבר, משום \u0003שהשאיבה\u0004 (המים השאובים) \u0003מטהרת ברבייה\u0004 (ברוב) של המים הכשרים לשמש כמי מקוה, \u0003וב\u0004דרך של \u0003המשכה\u0004 (הזרמה) של המים השאובים אל המקוה. וזו כוונת דברי המשנה שאין המים השאובים פוסלים את המקוה אלא לפי חשבון — שמחשבים את כמות המים השאובים הנמשכים אל המקוה, שרק אם הם רוב (עשרים ואחד סאים מתוך ארבעים) בתוך כלל מי המקוה — המקוה פסול.","ותוהים: \u0003מכלל\u0004 דברי ר' יוחנן שהעמיד את משנתנו כשיטת ר' אליעזר בן יעקב עולה \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 שבאופן זה, \u0003ברבייה ובהמשכה, לא\u0004 כשר המקוה? אם כן יש לשאול: \u0003אלא\u0004 מעתה הלכה זו \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 החכם \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 אותה בשם \u0003ר' יוחנן: שאובה\u0004 (מים שאובים) \u0003שהמשיכוה כולה\u0004 (כל הארבעים סאה שבמימי המקוה) — הריהי \u0003טהורה, מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 הלכה זו\u0005]?\u0006 שהרי לפי העמדה זו של המשנה, היא \u0003לא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שהמשכה אינה מועילה כלל למים שאובים, \u0003ולא\u0004 כשיטת \u0003ר' אליעזר\u0004 הסבור שהמשכה מועילה למים שאובים רק אם הם מיעוט מכלל מי המקוה!","\u0003אלא אמר רבה:\u0004 כוונת דברי המשנה שאין המים השאובים פוסלים את המקוה אלא לפי חשבון אינה בדרך המשכה, אלא \u0003לפי חשבון\u0004 (מספר) ה\u0003כלים\u0004 שמהם נשפכו במישרין (שלא בדרך המשכה) המים השאובים אל המקוה. \u0003ו\u0004כשיטת \u0003יוסף בן חוני היא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 מקוה חסר שאין בו מים כשרים בשיעור ארבעים סאה, ונפלו לתוכו שלושה לוגים מים שאובים — פסלוהו. ונחלקו בהלכה זו, שחכמים אומרים: \u0003שלשת לוגין מים שאובין שנפלו למים\u0004 שבמקוה החסר \u0003בשנים ושלשה כלים\u0004 (ונמצא איפוא שבכל כלי היה לפחות לוג מים שאובים), \u0003ואפילו בארבעה וחמשה כלים\u0004 (שבכל כלי היה פחות מלוג מים) — הריהם \u0003פוסלים את המקוה.\u0004 ואילו \u0003יוסף בן חוני אומר:\u0004 רק אם היו המים השאובים \u0003בשנים ושלשה כלים,\u0004 שיש בכל כלי לפחות לוג שלם — \u0003פוסל את המקוה.\u0004 אבל אם היו המים השאובים \u0003בארבעה וחמשה\u0004 כלים, שלא היה בכל כלי לוג שלם של מים שאובים — \u0003אין פוסלין את המקוה.\u0004 וזו כוונת דברי המשנה שהמים השאובים פוסלים לפי חשבון — לפי מספר הכלים שנשפכו מתוכם.","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אין מי חטאת נעשה מי חטאת\u0004 אלא בנתינת אפר הפרה האדומה על המים החיים הנמצאים כבר בכלי, ומבררים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה הלכה זו שבמשנתנו? אמר ר' חייא בר אבא, \u0003אמר ר' יוחנן:\u0004 משנתנו הריהי ש\u0003לא כ\u0004שיטת \u0003ר' שמעון.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדין עשייתם של המים מהם שותה האשה הסוטה (הנחשדת על ידי בעלה בזנות). נאמר בתורה: \"ולקח הכהן מים קדושים בכלי חרש ומן העפר אשר יהיה בקרקע המשכן יקח הכהן ונתן אל המים\" (במדבר ה, יז). הרי שתחילה נותן את המים בכלי, ולאחר מכן נותן עליהם מן העפר. ואולם אם עבר ו\u0003הקדים\u0004 את נתינת ה\u0003עפר\u0004 לכלי, \u0003ל\u0004נתינת ה\u0003מים\u0004 — הרי זה \u0003פסול. ו\u0004אילו \u0003ר' שמעון מכשיר\u0004 את המים הללו.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לשיטתו זו של \u0003ר' שמעון?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשת פרה אדומה: \u0003\"ולקחו לטמא מעפר שרפת החטאת ונתן עליו מים חיים\u0004 אל כלי\" (במדבר יט, יז). \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 הדנה בכתוב זה, \u0003ר' שמעון אומר: וכי עפר הוא? והלא אפר הוא!\u0004","אלא לא \u0003שינה הכתוב ממשמעו\u0004 (מ\"אפר\" ל\"עפר\") אלא כדי \u0003לדון\u0004 (ללמוד דין) \u0003הימנו\u0004 (מדין מי חטאת) בדרך הלימוד של \u0003גזירה שוה\u0004 למי הסוטה. וכך היא גזירה שווה זו: \u0003נאמר כאן\u0004 (במי חטאת) \u0003\"עפר\", ונאמר להלן\u0004 (במי סוטה) \u0003\"עפר\". מה להלן,\u0004 בדין מי סוטה — דרך עשייתם היא במתן ה\u0003עפר על גבי המים, אף כאן,\u0004 בדין מי חטאת — דרך העשייה היא במתן ה\u0003עפר\u0004 (אפר) \u0003על גבי המים. ומה כאן,\u0004 במי חטאת, אם \u0003הקדים\u0004 את נתינת ה\u0003עפר\u0004 (אפר) \u0003ל\u0004נתינת ה\u0003מים\u0004 — \u0003כשר, אף כאן\u0004 במי סוטה, אם \u0003הקדים\u0004 את נתינת ה\u0003עפר למים\u0004 — כשר.","ומבררים עוד: \u0003והכא מנלן\u0004 \u0005[וכאן,\u0006 במי חטאת \u0005מנין לנו]\u0006 שאם הקדים את נתינת האפר לנתינת המים, שהוא כשר? — שכן בפסוק זה שבמי חטאת \"ולקחו לטמא מעפר שרפת החטאת ונתן עליו מים חיים אל כלי\", \u0003תרי קראי כתיבי\u0004 \u0005[שני מקראות,\u0006 שני חלקי פסוק, \u0005נאמרו],\u0006 והמילים \"ונתן עליו\" הכתובים באמצע הפסוק משמען לכאן ולכאן. שמה שנאמר בתחילה \"ולקחו לטמא מעפר שרפת החטאת \u0003ונתן עליו\"\u0004 — \u0003אלמא\u0004 \u0005[מכאן]\u0006 שה\u0003אפר\u0004 הוא שניתן \u0003ברישא\u0004 \u0005[בתחילה]\u0006 בכלי, ולאחר מכן ניתנים המים. \u0003ו\u0004אולם \u0003הדר כתיב\u0004 \u0005[חזר\u0006 ו\u0005אמר]\u0006 הכתוב \"ונתן עליו \u0003מים חיים אל כלי\",\u0004 ומכתוב זה יש ללמוד שבתחילה ניתנים בכלי המים. ומעתה יש לשאול: \u0003הא\u0004 \u0005[זו]\u0006 \u0003כיצד\u0004 ניישבה? אלא אם \u0003רצה\u0004 — נותן את ה\u0003עפר\u0004 (אפר הפרה) \u0003למטה\u0004 (בתחילה), ועליו ניתנים אחר כך המים, ואם \u0003רצה\u0004 — נותן בתחילה את המים, ולאחר מכן נותן את ה\u0003עפר למעלה\u0004 (עליהם).","ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו,\u0006 של משנתנו\u0005]\u0006 הסבור שאם נתן תחילה את אפר הפרה ולאחר מכן את המים — הרי זה פסול, \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה לשיטתו\u0005]?\u0006 ומתרצים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 בהסבר מקור שיטתו, ש\u0003סיפיה דקרא\u0004 \u0005[סופו של הכתוב],\u0006 \"מים חיים אל כלי\" הוא ב\u0003דוקא,\u0004 לומר שרק כך יש לנהוג בסדר עשיית מי החטאת, שקודם ינתנו המים בכלי ומעליהם יתן את האפר. ואילו ראשית הכתוב \"מעפר שרפת החטאת \u0003ונתן עליו\"\u0004 בא ללמדנו דין נוסף בעשיית מי החטאת, שלאחר שנתן את האפר על המים, יש \u0003לערבן\u0004 את המים והאפר, באופן שהמים ישובו ויכסו את האפר.","ושואלים על הסבר זה: \u0003מאי חזית דאמרת סיפיה דקרא\u0004 \u0005[מה ראית,\u0006 העדפת \u0005לומר\u0006 ש\u0005סופו של הכתוב]\u0006 ממנו למדים שיש לתת את המים תחילה הוא זה שב\u0003דוקא, דלמא רישא\u0004 \u0005[שמא תחילתו]\u0006 של הפסוק, ממנו למדים שהאפר ניתן תחילה, היא ב\u0003דוקא?\u0004 ומשיבים: \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר\u0006 כן\u0005],\u0006 שכן \u0003מה מצינו\u0004 (מצאנו) \u0003בכל מקום\u0004 שהדבר ה\u0003מכשיר\u0004 הוא הניתן \u0003למעלה\u0004 (על הדבר הקודם לו בנתינה), כגון עפר המשכן הניתן על המים, במי סוטה. \u0003אף כאן\u0004 במי חטאת — הדבר ה\u0003מכשיר\u0004 (האפר) צריך להינתן \u0003למעלה\u0004 (לאחר שניתנו המים).","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אין בית הפרס\u0004 (שדה שהיה בו קבר, ונחרש, והריהו מטמא) \u0003עושה בית הפרס\u0004 אחר, שאם חזר וחרש מתוך בית הפרס לשטח אחר — אין אותו מקום נחשב כבית הפרס. ומסבירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 זו הריהי ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: בית הפרס\u0004 שנחרש ממנו והלאה — הרי חרישה זו \u0003עושה\u0004 אף את כל השדות הסמוכים (ראה עיונים) שייחשבו כ\u0003בית הפרס. ו\u0004שואלים: לשיטת","\u0003רבנן\u0004 \u0005[חכמים],\u0006 החולקים על ר' אליעזר, \u0003עד כמה\u0004 (מהו תחום) בית הפרס? ובתשובה לכך, מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, מסר שכך \u0003אמר ריש לקיש, אמר ר' שמעון בר אבא:\u0004"],["\u0003שלש שדות,\u0004 שהן שדה זה שנחרש, ועוד שני שדות הנמצאים בכיוון החרישה שנעשתה בשדה זה: כגון שאם חרש בשדה זה מדרום לצפון — השדה הדרומי והשדה הצפוני, הצמודים לשדה זה, אף הם בכלל בית הפרס. ואולם בעוד שהשדה שנחרש הריהו נחשב כולו בית הפרס, שני השדות שלצידו הריהם נחשבים בית הפרס רק בתחום ששיעורו הוא \u0003שתי מענות,\u0004 לאמר, מענה (שיעור תלם הנחרש בחרישה אחת) לצד זה של השדה ומענה לצד זה של השדה. ומסבירים: \u0003וכמה\u0004 הוא שיעור זה של \u0003\"מלא מענה\"\u0004 — \u0003מאה אמה. כדתניא\u0004 \u0005[כמו ששנויה\u0006 הלכה\u0005]:\u0006 \u0003החורש את הקבר —\u0004 \u0003עושה בית הפרס מלא מענה, מאה אמה.\u0004","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אין תרומה אחר תרומה.\u0004 ומבררים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 ומשיבים: כשיטת \u0003ר' עקיבא היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה ובתוספתא\u0005]:\u0006 \u0003השותפין\u0004 בפירותיהם, \u0003שתרמו\u0004 מפירות אלה, \u0003זה אחר זה,\u0004 שתרם אחד מהם, ובא חבירו ותרם אף הוא, \u0003ר' אליעזר אומר: תרומת שניהם\u0004 — \u0003תרומה,\u0004 שהרי מה שהפריש כל אחד מהם, מחלקו הפריש.","ואילו \u0003ר' עקיבא אומר: אין תרומת שניהם תרומה,\u0004 לא תרומתו של השותף הראשון, שכן תרומתו של השותף השני מלמדת שלא נוח לו בתרומת הראשון, ונמצא שתרומתו היא בגדר התורם שלא מדעת חבירו, שאינה תרומה, ואף לא תרומת השני מאותו הטעם. \u0003וחכמים אומרים: אם תרם הראשון כשיעור\u0004 הראוי לתרומה (אחד מחמישים) — נפטרו הפירות מחיוב התרומה, ולכן אין תרומת השני תרומה, ואם הראשון \u0003לא תרם כשיעור\u0004 הראוי לתרומה, וכגון שתרם בעין רעה (אחד מששים) — \u0003תרומת\u0004 השותף \u0003השני\u0004 הריהי \u0003תרומה.\u0004","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אין\u0004 הבהמה שהתקדשה כ\u0003תמורה עושה\u0004 בהמה אחרת שתתקדש ב\u0003תמורה.\u0004 ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור הדין לכך בתורה\u0005]?\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין התמורה: \"ואם המר ימיר בהמה בבהמה והיה הוא \u0003ותמורתו\u0004 יהיה קודש\" (ויקרא כז, י) — ללמדנו שדין התמורה חל רק על בהמת ההקדש ותמורתה, \u0003ולא\u0004 ב\u0003תמורת תמורתו.\u0004","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אין הולד עושה תמורה.\u0004 והסבר הדבר, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"והיה \u0003הוא\u0004 ותמורתו יהיה קודש\" — והרי זה לשון מיעוט: דוקא \u0003הוא\u0004 (בהמת ההקדש) עושה תמורה, \u0003ולא ולד.\u0004","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003ר' יהודה אומר: הולד עושה תמורה.\u0004 והסבר הדבר: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"יהיה\u0004 קודש\" שהוא לשון ריבוי — \u0003לרבות את הולד. ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים שאין הולד עושה תמורה, מה הם לומדים מריבוי זה? — \u0003לרבות\u0004 בדין התמורה את הממיר ב\u0003שוגג כ\u0004דין הממיר ב\u0003מזיד, שבשניהם חל דין התמורה.\u0004","\u0003העופות\u0004 (תורים, בני יונה) שהוקדשו לקרבן הבא מן העוף, \u0003והמנחות\u0004 הבאות כקרבן מסולת חיטים או סולת שעורים — \u0003אין עושין\u0004 בהם תמורה, וטעם הדבר: משום שנאמר \"ואם המר ימיר בהמה בבהמה\" (ויקרא כז, י), הרי \u0003שלא נאמר\u0004 שנוהג דין התמורה \u0003אלא\u0004 ב\u0003בהמה\u0004 של הקדש. ועוד בדיני הקרבנות שמתקיים בהם דין התמורה: בהמות הקדש של \u0003הציבור ו\u0004כן של \u0003השותפין\u0004 — \u0003אין עושין\u0004 בהן \u0003תמורה,\u0004 שאם המירו עליהם בהמה של חולין — אין היא מתקדשת בכך. וטעם הדבר: משום \u0003שנאמר\u0004 בפרשת התמורה \u0003\"לא יחליפנו ולא ימיר\u0004 אותו\" (ויקרא כז, י) — והרי לשון יחיד זה מורה שדווקא קרבנו של \u0003יחיד עושה תמורה, ואין\u0004 קרבנות \u0003הצבור והשותפין עושין תמורה.\u0004 ועוד בדינים אלה של התמורה: \u0003קדשי בדק הבית\u0004 — \u0003אין עושין תמורה,\u0004 שאין ממירים אלא בבהמת הקדש הקדושה בקדושת הגוף.","\u0003אמר ר' שמעון\u0004 בטעם הדבר: \u0003והרי מעשר\u0004 בהמה \u0003בכלל\u0004 כל הקרבנות \u0003היה,\u0004 \u0003ו\u0004אם כן יש לשאול: \u0003למה יצא\u0004 מכלל זה, שחזר הכתוב ואמר בו (בלשון דומה) \"וכל מעשר בקר וצאן כל אשר יעבור תחת השבט העשירי יהיה קודש לה'.","לא יבקר בין טוב לרע ולא ימירנו ואם המר ימירנו והיה הוא ותמורתו יהיה קודש\" (ויקרא כז לב—לג) — לומר לך מתוך ההיקש למעשר בהמה: \u0003מה מעשר\u0004 בהמה — הריהו דווקא \u0003קרבן יחיד\u0004 (שהרי השותפים פטורים ממעשר בהמה), אף כל הקרבנות שממירים בהם, הריהם קרבן יחיד. \u0003יצאו\u0004 מכלל דין התמורה \u0003קרבנות צבור\u0004 וקרבנות השותפים. \u0003ו\u0004עוד נלמד מהיקש זה: \u0003מה מעשר\u0004 בהמה — הריהו קדוש בקדושת הגוף, שהרי הוא \u0003קרבן\u0004 הקרב על ה\u0003מזבח,\u0004 אף כל הקרבנות שממירים בהם הריהם הקדושים בקדושת הגוף, ומכאן ש\u0003יצאו\u0004 מכלל דין התמורה \u0003קרבנות\u0004 (קדשי) \u0003בדק הבית.\u0004","שנינו במשנתנו כי אין קדשי בדק הבית עושים תמורה. ומביאים עוד בענין זה את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהו\u0004 אף \u0003קדשי בדק הבית עושין תמורה?\u0004 — \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"קרבן\"\u0004 (\"ואם בהמה אשר יקריבו ממנה קרבן לה'... לא יחליפנו ולא ימיר אותו\" וגו' ויקרא כז, ט—י), שאין דין התמורה אלא ב\u0003מי שנקראו\u0004 בכתוב \u0003\"קרבן\", יצאו\u0004 מכלל זה \u0003קדשי בדק הבית\u0004 — \u0003שלא נקראו\u0004 בכתוב \u0003\"קרבן\".\u0004","ושואלים: \u0003ו\u0004כי קדשי בדק הבית \u0003לא\u0004 נקראו \"קרבן\"? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בדין השוחט קדשים מחוץ למקדש (\"שחוטי חוץ\"), שאמרה בו התורה: \"...או אשר ישחט מחוץ למחנה. ואל פתח אהל מועד לא הביאו להקריב קרבן לה' לפני משכן ה'\" (ויקרא יז, ג—ד). ודנים: \u0003אי\u0004 \u0005[אם]\u0006 נכללים באיסור שחיטת חוץ כל הקדשים הנקראים בכתוב \u0003\"קרבן\"\u0004 — \u0003שומע אני\u0004 כי בכלל איסור זה \u0003אפילו קדשי בדק הבית, ש\u0004הרי אף הם \u0003נקראו\u0004 בכתוב \u0003\"קרבן\". כענין שנאמר\u0004 בשלל המלחמה שנלקח ממדין: \u0003\"ונקרב את קרבן ה'\u0004 איש אשר מצא כלי זהב אצעדה...","לכפר על נפשותינו\" (במדבר לא, נ), שהיו אלה קדשי בדק הבית — לכך \u0003תלמוד לומר\u0004 \u0003\"ואל פתח אהל מועד לא הביאו\"\u0004 — לומר שדווקא \u0003כל\u0004 קרבן \u0003הבא\u0004 (הראוי לבוא) \u0003אל פתח אהל מועד\u0004 (להיקרב על המזבח), הוא ש\u0003חייבין עליו משום\u0004 איסור \u0003שחוטי חוץ. ו\u0004אילו \u0003כל\u0004 קודש \u0003שאינו בא לפתח אהל מועד\u0004 (שאינו ראוי להיקרב על המזבח) — \u0003אין חייבין עליו משום שחוטי חוץ.\u0004 \u0003אלמא\u0004 \u0005[מכאן]\u0006 ממה שהוצרך הכתוב ללימוד מיוחד (\"ואל פתח אהל מועד לא הביאו\") כדי למעט קדשי בדק הבית, נלמד שבדרך כלל קדשי בדק הבית \u0003איקרו\u0004 \u0005[נקראו]\u0006 בכתוב \u0003\"קרבן\"!\u0004","\u0003אמר ר' חנינא\u0004 בתשובה: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו,\u0006 השניה\u0005]\u0006 שבדין שחוטי חוץ — היא כשיטת \u0003ר' שמעון,\u0004 ואילו \u0003הא\u0004 \u0005[זו]\u0006 הברייתא שבדין תמורה — היא כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 ומפרש את דבריו: \u0003ל\u0004שיטת \u0003ר' שמעון\u0004 במשנתנו, שלמד שאין קדשי בדק הבית בכלל דין התמורה מהיקש למעשר בהמה, ולא למד דין זה מן הכתוב בפרשת התמורה \"ואם בהמה אשר יקריבו ממנה קרבן לה'...\" — אכן קדשי בדק הבית \u0003איקרי\u0004 \u0005[נקראים]\u0006 \u0003\"קרבן\".\u0004 ואולם \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הלמדים שאין קדשי בדק הבית בכלל דין התמורה מהכתוב \"קרבן לה'\" — \u0003לא איקרי\u0004 \u0005[אינם נקראים]\u0006 \u0003\"קרבן\".\u0004","ושואלים על שיטת חכמים: \u0003ו\u0004האם \u0003לא\u0004 נקראו קדשי בדק הבית \"קרבן\"? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בהם \"ונקרב את קרבן ה'\"! ומשיבים: \u0003\"קרבן ה'\"\u0004— \u0003איקרי\u0004 \u0005[\u0006הם \u0005נקראים],\u0006 ואולם \u0003\"קרבן לה'\"\u0004שמשמעו דבר הקרב בעצמו על גבי המזבח — \u0003לא איקרי\u0004 \u0005[אינם נקראים].\u0006","עוד שנינו במשנתנו שאין בכלל דין התמורה קרבן ציבור וקרבן השותפים. ומביאים עוד בענין זה את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 על האמור במעשר בהמה \u0003\"לא יבקר בין טוב לרע ולא ימירנו\u0004 ואם המר ימירנו והיה הוא ותמורתו יהיה קודש\" (ויקרא כז, לג), יש לשאול: \u0003למה נאמר\u0004 ענין התמורה במעשר בהמה? \u0003והלא כבר נאמר\u0004 לפני כן, איסור התמורה בכלל בהמות ההקדש, ככתוב: \u0003\"לא יחליפנו ולא ימיר אתו טוב ברע\u0004 או רע בטוב ואם המר ימיר... והיה הוא ותמורתו יהיה קודש\" (ויקרא כז, י)!","ומשיבים: \u0003לפי שנאמר\u0004 בפרשת התמורה \u0003\"לא יחליפנו ולא ימיר אתו\"\u0004 — והרי \u0003משמע\u0004 לשון זה כולל הן \u0003קרבן יחיד,\u0004 והן \u0003קרבן צבור, ו\u0004הן קרבן מזבח, וקרבן בדק הבית, לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב במעשר בהמה): \u0003\"לא יבקר\"\u0004 — שאין קרבן הציבור והשותפים בכלל דין התמורה. וכיצד מקרא זה הכתוב במעשר בהמה מלמדנו?","— אמר ר' שמעון: והרי מעשר בהמה \u0003בכלל\u0004 כל בהמות ההקדש האמורות בפרשת התמורה \u0003היה, ולמה יצא\u0004 מכללם, להיכתב בו שוב איסור התמורה? — להקישו לפרשת התמורה, ו\u0003לומר לך:\u0004 \u0003מה מעשר\u0004 בהמה הריהו \u0003קרבן\u0004 של \u0003יחיד, ו\u0004הריהו \u0003קרבן מזבח\u0004 (הקרב על המזבח), \u0003ו\u0004הריהו \u0003דבר שבא בחובה\u0004 ולא בנדבה, \u0003ו\u0004הריהו \u0003דבר שאינו\u0004 בא \u0003בשותפות\u0004 אלא רק ביחיד — \u0003אף כל\u0004 הכלולים בדין התמורה הריהם \u0003קרבן יחיד וקרבן מזבח ודבר שבא בחובה\u0004"],["\u0003ודבר שאינו בא בשותפות.\u0004","ועוד באותו ענין. \u0003רבי אומר: למה יצאת\u0004 (יצא) \u0003מעשר\u0004 בהמה מכלל כל הקדשים שחזר הכתוב ואמר בה את דין התמורה, \u0003מעתה,\u0004 לאחר שכבר נאמרה פרשת התמורה בכלל הקדשים? — \u0003לידון\u0004 (ללמדנו דין) מיוחד \u0003ב\u0004מעשר הבהמה, שהוא \u0003\"תמורת שמו\"\u0004 (כלומר, אם בשעת יציאת הצאן מן הדיר להתעשר, טעה המונה וקרא לעשירי \"תשיעי\" ולאחד עשר \"עשירי\" — שניהם קדושים. זה שיצא עשירי קדוש בקדושת מעשר בהמה, לפי שיצא עשירי, וזה שיצא אחד עשר קדוש בקדושת שלמים, לפי שקרא לו \"עשירי\"). \u0003ו\u0004מתוך שנלמד בו דין מיוחד של \"תמורת שמו\", יש צורך ללמוד שחל בו גם הדין הכללי של \u0003\"תמורת גופו\"\u0004 היא התמורה האמורה בכל הקרבנות (ונקראת \"תמורת גופו\" להבדיל מ\"תמורת שמו\").","ובענין זה של תמורת שמו ותמורת גופו, הנוהגות שתיהן במעשר בהמה, יש \u0003לומר לך\u0004 (להשמיעך) כמה וכמה הלכות במעשר בהמה שבהן נבדל דין תמורת שמו מדין תמורת גופו. ואלו הן: זו הבהמה שהינה \u0003תמורת שמו\u0004 של מעשר בהמה — הריהי \u0003קריבה\u0004 על המזבח (כשלמים), ואילו זו שהיא \u0003תמורת גופו\u0004 — \u0003אינה קריבה\u0004 על המזבח כלל (ושלא כשאר בהמות חולין שהומרו בבהמות הקדש, שחלה עליהן קדושת זו שהמירו בה, והריהן קרבות כמותה). ועוד הבדל, ש\u0003תמורת שמו\u0004 של מעשר בהמה — \u0003נגאלת,\u0004 נפדית, לכשיפול בה מום, כדין קרבן השלמים, שדמיה להקדש והיא יוצאת לחולין, ואילו ל\u0003תמורת גופו\u0004 — \u0003אינה נגאלת\u0004 כאמור במעשר בהמה: \"והיה הוא ותמורתו יהיה קודש לא יגאל\" (ויקרא כז, לג). והבדל נוסף, שקדושת \u0003תמורת גופו\u0004 במעשר בהמה — \u0003חלה\u0004 הן \u0003על דבר הראוי\u0004 להקרבה על גבי המזבח, \u0003ו\u0004הן \u0003על דבר שאינו ראוי\u0004 להקרבה, וכגון בעל מום (שהרי קדושת מעשר בהמה חלה אף על בהמת בעלת מום), \u0003ו\u0004אילו \u0003תמורת שמו\u0004 — \u0003אינה חלה אלא על דבר הראוי\u0004 להקרבה \u0003בלבד.\u0004 שאילו היתה זו הבהמה שנקראה בטעות \"עשירי\" בעלת מום — אין היא קדושה בכך, כשאר קדשים שאינם מתקדשים בהיותם בעלי מומים. ונפנים עתה לדון בדברי רבי אלו.","","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתמיהה על כך: וכי \u0003משום דרבי רחמנא דאית ביה\u0004 \u0005[שריבה הכתוב\u0006 את מעשר בהמה \u0005שיש בו]\u0006 דין מיוחד זה של \u0003תמורת שמו,\u0004 לכן \u0003איגרועי איגרע\u0004 \u0005[נגרע,\u0006 הוקל דינו\u0005]\u0006 של מעשר בהמה, שלא ינהג בו דין התמורה הרגיל, כבשאר הקדשים, שלכך נצרך הכתוב לשוב ולהשמיענו שנוהג בו דין התמורה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 ככלל: \u0003מאי דרבי\u0004 \u0005[מה שריבה]\u0006 הכתוב — \u0003רבי\u0004 \u0005[ריבה],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 ש\u0003לא רבי\u0004 \u0005[ריבה]\u0006 הכתוב — \u0003לא רבי\u0004 \u0005[ריבה],\u0006 והיה מקום לומר שבדין מעשר בהמה, ינהג רק דין תמורת שמו, ולא דין תמורת גופו. ולכך נצרכים אנו ללימוד מיוחד, שאף תמורת גופו נוהג בו.","ושואלים: \u0003והא מהיכא תיתי\u0004 \u0005[ו\u0006דבר \u0005זה מהיכן תבוא,\u0006 תעלה על הדעת להיאמר\u0005]? אמר רב הונא בריה\u0006 \u0005[בנו]\u0006 של \u0003רב יהושע: משום דהוה\u0004 \u0005[ש\u0006דין מעשר בהמה \u0005הינו]\u0006 בכלל ההגדרה של \u0003דבר הבא לידון בדבר החדש\u0004 (שכן מיוחד הוא בדין \"תמורת שמו\") — \u0003ו\u0004כלל הוא שכל דבר הבא לידון בדבר החדש, \u0003אין\u0004 לך \u0003בו אלא חידושו בלבד,\u0004 ואין מוסיפים בו חידושים אחרים. לכך הוצרכה התורה לכתוב מיוחד להשמיענו שנוהג אף במעשר בהמה דין \"תמורת גופו\" הרגיל בשאר הקדשים.","ושבים לדון בשיטת ר' שמעון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: ל\u0004שיטת \u0003ר' שמעון דאמר\u0004 \u0005[האומר]\u0006 כי דין התמורה נוהג ב\u0003דבר הבא בחובה,\u0004 האם נסיק מכאן שרק \u0003עולת חובה\u0004 — \u0003היא דעבדה\u0004 \u0005[שעושה]\u0006 \u0003תמורה, הא\u0004 \u0005[הרי]\u0006 ש\u0003עולת נדבה\u0004 — \u0003לא\u0004 עושה תמורה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003עולת נדבה נמי\u0004 \u0005[גם כן]\u0006 עושה תמורה, ש\u0003כיון\u0004 ש\u0003קבלה עליה\u0004 \u0005[עליו]\u0006 להביא עולת נדבה, נחשב הדבר כחובה עליו, ו\u0003עבדה\u0004 \u0005[עושה]\u0006 \u0003תמורה.\u0004","\u0003ולא נצרכה\u0004 הלכה זו של ר' שמעון \u0003אלא ל\u0004דין תמורה ב\u0003עולה הבאה מן המותרות,\u0004 כגון מי שהפריש סכום כסף מסויים לצורך קרבן חטאת או אשם, ולאחר שקנה בהמה לקרבנו נותר מן המעות, שהדין הוא שמביא קרבן עולה. ובקרבן זה, אין נוהג דין תמורה. ומקשים על הסבר זה ממה ששנינו, שנחלקו חכמים (לקמן כ,ב) באופן השימוש במותר מעות אלו. שיש הסבורים שקונים בהן עולת ציבור, ויש הסבורים שמביאים בהן הבעלים עולה (לשם נדבה).","ומעתה יש לשאול: \u0003מאי קסבר\u0004 \u0005[מה הוא,\u0006 ר' שמעון, \u0005סבור]\u0006 \u0003אי קסבר לה כמאן דאמר\u0004 \u0005[אם הוא סבור כמי שאומר]\u0006 \u0003מותרות לנדבת צבור אזלי\u0004 \u0005[הולכים]\u0006 — אין הכתוב צריך להשמיענו שאין תמורה בעולה הבאה מן המותרות, שהרי \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שהיא \u0003לא עבדה\u0004 \u0005[עושה]\u0006 \u0003תמורה, הא\u0004 \u0005[\u0006ש\u0005הרי]\u0006 שנינו במפורש ש\u0003אין תמורה ב\u0004קרבן ה\u0003צבור!\u0004","\u0003אלא\u0004 יש לומר כי \u0003ר' שמעון סבירא ליה כמאן דאמר\u0004 \u0005[סבור\u0006 הוא \u0005כמי שאומר]\u0006 \u0003מותרות לנדבת יחיד\u0004 של הבעלים \u0003אזלי\u0004 \u0005[הולכים].\u0006 ואולם אף זה קשה, שהרי \u0003מאן שמעת ליה האי סברא\u0004 \u0005[מי\u0006 הוא ש\u0005שמעת אותו\u0006 שהוא סובר \u0005סברה זו]\u0006 — \u0003ר' אליעזר,\u0004 והוא \u0003הא שמעינן ליה בהדיא דעבדה\u0004 \u0005[הרי שמענו אותו\u0006 \u0005במפורש ש\u0006לדעתו עולה הבאה מן המותרות \u0005עושה]\u0006 \u0003תמורה! דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003עולה הבאה מן המותרות\u0004 — \u0003עושה תמורה,\u0004 אלו \u0003דברי ר' אליעזר!\u0004 ומשיבים: \u0003ר' שמעון סבר לה כותיה בחדא\u0004 \u0005[סבור הוא כמותו,\u0006 כר' אליעזר, \u0005ב\u0006דבר \u0005אחד],\u0006 בדמי המותרות, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו ב\u0006דבר \u0005אחד].\u0006 שכן \u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 ש\u0003עולה הבאה מן המותרות\u0004 — \u0003עושה תמורה, ו\u0004אילו \u0003איהו סבר\u0004 \u0005[הוא,\u0006 ר' שמעון, \u0005סבור]\u0006 ש\u0003אין עושה תמורה.\u0004","","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאלה זו \u0003דבעיא\u0004 \u0005[ששאל]\u0006 \u0003ר' אבין,\u0004 ונידונה בהרחבה למעלה (דף ט, א—ב) בבירור הסברו של ר' יוחנן בשיטת ר' שמעון, שקרבן שהמירו עליו פעם אחת, שוב אין חוזרים וממירים עליו. ושאלתו היתה במי ש\u0003הפריש\u0004 בהמה אחת לקרבן \u0003אשם להתכפר בו,\u0004 \u0003ו\u0004לאחר מכן \u0003המיר בו\u0004 בהמת חולין, וחלה קדושה על בהמה זו. ואחר כך נפל מום בראשון וחיללו על בהמה אחרת ואבד הקרבן השני, והפריש קרבן אחר, שלישי, לאשם, \u0003ונתכפר באשם\u0004 ה\u0003אחר, ו\u0004לאחר מכן נמצא הקרבן השני, והרי דינו ש\u0003ניתק\u0004 (נעתק) \u0003זה\u0004 השני \u0003לעולה\u0004 (והריהו איפוא בכלל \"עולה הבאה מן המותרות\"), \u0003מהו\u0004 דינו של קרבן זה לענין \u0003שיחזור וימיר בו?\u0004","ומעתה יש לשאול: \u0003אליבא דמאן\u0004 \u0005[לשיטת מי]\u0006 שאל ר' אבין את שאלתו זו, \u0003אילימא אליבא\u0004 \u0005[אם תאמר לשיטת]\u0006 \u0003ר' שמעון\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 ש\u0003ר' שמעון סבירא ליה\u0004 \u0005[הריהו סבור]\u0006 ש\u0003עולה הבאה מן המותרות אין עושה תמורה!\u0004 ומסבירים: \u0003ר' אבין הכי קמיבעיא ליה\u0004 \u0005[כך נשאלה לו]:\u0006 \u0003אי משכחת\u0004 \u0005[אם מוצא אתה]\u0006 \u0003תנא דקאי\u0004 \u0005[העומד,\u0006 הסבור\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 ש\u0003אין ממירין וחוזרין וממירין, ו\u0004אותו תנא \u0003סבירא ליה\u0004 \u0005[סבור הוא]\u0006 מצד אחר \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 ש\u0003עולה הבאה מן המותרות עושה תמורה, מהו\u0004 הדין במקרה זה לענין \u0003שיחזור וימיר בו,\u0004 בקרבן זה שניתק לעולה? ושתי בעיות הן, הבאות זו מתוך זו. שבתחילה שאל ר' אבין \u0003ב\u0004מקרה זה שיש בו \u0003שני גופין וקדושה אחת,\u0004 וכגון שהפריש בהמה לאשם, והמירה על בהמה אחרת, ונפל מום בראשון, וחיללו על בהמה אחרת, ואבד הקרבן השני, והקריב קרבן אחר. ולאחר מכן נמצא הקרבן השני. והשאלה מתייחסת לקרבן השני, האם ממירים עליו או לא. \u0003מאי\u0004 \u0005[מה]\u0006 הדין? וצדדי השאלה: האם נאמר שכיון שגוף אחר הוא — ימירו עליו. או שקדושה אחת, קדושת השני, של אשם, נאצלת מהראשון — ולא ימירו בו? והוסיף ושאל: \u0003ו\u0004אף \u0003אם תימצא לומר\u0004 שאין חוזרים וממירים, כיון ש\u0003קדושה אחת\u0004 היא (או לא), אלא במקרה של \u0003שתי קדושות וגוף אחד,\u0004 וכגון שאבד הקרבן הראשון, ונתכפר בקרבן אחר, ולאחר מכן נמצא הקרבן הראשון, וניתק לעולה. ומעתה הרי אלו שתי קדושות, בתחילה של אשם ולאחר מכן של עולה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין, האם חוזרים וממירים בו? וצדדי השאלה: הרי זה גוף אחד — ואין חוזרים וממירים, או ששתי קדושות הן — וחוזרים וממירים. ומסכמים: אכן, לשיטת תנא זו \u0003תיבעי\u0004","","","",""]]};
